WordHunterWoW_QuestEN[4113] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4114] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4115] = { title = "Corrupted Windblossom", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4116] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4117] = { title = "Corrupted Whipper Root", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4118] = { title = "Corrupted Songflower", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4119] = { title = "Corrupted Night Dragon", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4120] = { title = "The Strength of Corruption", description = "Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, <name>.\n\nIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.\n\nGo, <name>. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.", objectives = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.", completion = "It sounds from your descriptions as if the creatures show a mindless ferocity...\n\nStay alert, <name>. It would be in your best interest to learn more of the corruption. Always know your enemy." }
WordHunterWoW_QuestEN[4121] = { title = "Precarious Predicament", description = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!", objectives = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.", progress = "I will take this traitorous filth, <name>.", completion = "Your heroics will not go unrecognized, <name>. You have earned this tribute. The Warlord will speak with you now in regards to the final mission." }
WordHunterWoW_QuestEN[4122] = { title = "Grark Lorkrub", description = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, <name>. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.", objectives = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.\n\nProvided item:", completion = "Can you not see the power we gain by joining the legion of Blackrock?" }
WordHunterWoW_QuestEN[4123] = { title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", objectives = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, <name>, take this as payment!" }
WordHunterWoW_QuestEN[4124] = { title = "The Missing Courier", description = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.", objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying. It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse. Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro. He should be here in the Stronghold - perhaps in his quarters.", completion = "Latro sent you to me, I presume.  While I think it is a lost cause at this point, I'll take whatever assistance you can offer.  I must admit... I'll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment." }
WordHunterWoW_QuestEN[4125] = { title = "The Missing Courier", description = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.", objectives = "Locate the courier's boat somewhere along the coast of Feralas.", completion = "You have found what appears to be a wrecked row boat.  Through the slightly muddy water you see gaping holes riddling the port side; the boat is nearly shredded down to its simple wooden frame.  Whatever broke this boat most likely tried to snap it in two.  A small crest of the Feathermoon Stronghold is painted on the starboard side.\n\nIn the mud at the base of the boat, a glint of something metallic catches your eye..." }
WordHunterWoW_QuestEN[4126] = { title = "Hurley Blackbreath", description = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!\n\n<name>, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!", objectives = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", progress = "Do you have the recipe, <name>?  I can't stand the idea of those Dark Iron dwarves drinking my family's drink!", completion = "You found it!  Well done!  And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!\n\nThe Thunderbrews are at your service, <name>.  You are a hero of heroes!" }
WordHunterWoW_QuestEN[4127] = { title = "Boat Wreckage", description = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...", objectives = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.", progress = "Ah, welcome back <name>.  I hope that you were able to uncover some clue as to Raschal's ultimate fate, as tragic as that may be.", completion = "Interesting... I believe that this is Raschal's knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife's discovery might not be enough to connect this to Raschal's disappearance; we do, however, have an unconventional option available to us to try and learn more.\n\nHave you ever heard of psychometry?" }
WordHunterWoW_QuestEN[4128] = { title = "Ragnar Thunderbrew", description = "Ho, <name>.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.", objectives = "Speak with Ragnar Thunderbrew.Ho, <name>. I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale. He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested. He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.", completion = "You're right I'm mad!  I've been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn't have enough cause to hate the Dark Iron dwarves!  Now, oh... now they're in for it!" }
WordHunterWoW_QuestEN[4129] = { title = "The Knife Revealed", description = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.", objectives = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.", progress = "Ginro sent you, eh?\n\nMy psychometric readings are fairly draining on the psyche... but so are my losses at Kalimdor Hold 'Em.  They call me \"King of the Bad Beats\" here in the Stronghold.  Unlucky at cards... lucky at mastering the secrets of nature, I guess.\n\nAnyway, of course I'll do it.  This may be just the breakthrough we need to uncover Raschal's fate.  If you would hand me the knife, we can get started.", completion = "Thank you, <name>.\n\nWhile psychometry isn't an exact art by any stretch of the imagination, I've used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you've uncovered will give us a glimpse into what happened to Raschal.\n\nIt will only take a moment to do, but it isn't what I'd call a caster-friendly task.  Bear with me on this." }
WordHunterWoW_QuestEN[4130] = { title = "Psychometric Reading", description = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry <name>.  Tell Gin what I've seen.  He needs to know.", objectives = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.I'm a little wobbly still, sorry. Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however. I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called. He's very worried - almost terrified - about something. So much so, that he is not paying attention to water elementals forming behind him. The images... stop there.\n\nI need to rest, sorry <name>. Tell Gin what I've seen. He needs to know.", completion = "Thanks for passing along Quint's visions to me, <name>.  I'll try to remember to be a little easier on him the next time we play cards.\n\nRaschal can hold his own in a fight, and gnolls aren't anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need." }
WordHunterWoW_QuestEN[4131] = { title = "The Woodpaw Gnolls", description = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.", objectives = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred. Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned. I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.", completion = "Tacked up on a nearby tree are two large leather backpacks.  Each bears a small insignia of the Feathermoon Stronghold on the front of the pack..." }
WordHunterWoW_QuestEN[4132] = { title = "Operation: Death to Angerforge", description = "You have done an exemplary job, <name>. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.", objectives = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", completion = "Finally! The villain been brought to justice! You are a remarkable individual, <name>. Wear this medallion as a symbol of your stalwart dedication to the Horde and the K.E.F." }
WordHunterWoW_QuestEN[4133] = { title = "Vivian Lagrave", description = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian.  She awaits you.", objectives = "Speak with Shadowmaster Vivian Lagrave in Kargath.Shadowmaster Vivian Lagrave is in need of your services. She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian. She awaits you.", completion = "Thank you for coming, <name>.  This place is not without a stark charm, but it lacks the amenities of the Apothecarium.\n\nEnough with the pleasantries.  To business, yes?" }
WordHunterWoW_QuestEN[4134] = { title = "Lost Thunderbrew Recipe", description = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious ale.", objectives = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", progress = "Do you have the recipe for the Thunderbrew Lager, <name>?", completion = "Very good.  I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets.  One day, the dwarves of the Alliance may find the virtues of this drink used against them!\n\nI find that terribly amusing.  Perhaps death has an affect on one's sense of humor... do you think?" }
WordHunterWoW_QuestEN[4135] = { title = "The Writhing Deep", description = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately went.", objectives = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep. According to the note, it is located to the south of the Woodpaw gnoll camps.\n\nProvided item:", completion = "You have discovered a large pod of an alien nature.  The texture of the pod appears mucous, though hardened protrusions stick out from random parts of it.  The pod itself has the height and width to easily encompass a humanoid inside of it... and from the faint humanoid shape visible through the skin of the pod, you surmise that this is what it indeed encapsulates." }
WordHunterWoW_QuestEN[4136] = { title = "Ribbly Screwspigot", description = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head.", objectives = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", progress = "Do you have Ribbly?  Or, at least a part of him?", completion = "Aha!  You found him!  And... it appears that my little brother didn't want to come quietly.  It's a pity.  I would have liked to see the look on his face when I told him our plans to turn him in to Revilgaz.\n\nThank you, <name>.  You've made my family very happy.  And Ribbly's never looked as peaceful as he does now." }
WordHunterWoW_QuestEN[4141] = { title = "Muigin and Larion", description = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect some?", objectives = "Collect 15 Bloodpetals and return to Muigin.", progress = "Larion's got something coming, that's for sure!", completion = "I hope they didn't give you too much trouble, <name>. I try to steer clear of them -- they're wild!\n\nI tried jumping over one... I was attacked! Plants just shouldn't be acting that way!" }
WordHunterWoW_QuestEN[4142] = { title = "A Visit to Gregan", description = "I'm not quite sure what to make of this, <name>. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.", objectives = "Take a Bloodpetal to Gregan Brewspewer in Feralas.", progress = "I live out here in the forest... Peaceful.\n\nWell, at least I thought it would be. I get more visitors out here than I ever did when I lived in Ironforge!", completion = "Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I'll tell you whether or not I can help you." }
WordHunterWoW_QuestEN[4143] = { title = "Haze of Evil", description = "To tell you the truth, <name>, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, <name>!", objectives = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", progress = "Larion's still not speaking to me! He sure knows how to hold a grudge.", completion = "I admit, I'm a bit hesitant to touch that stuff, <name>! But if Gregan says it'll work, then I'm willing to give it a try!" }
WordHunterWoW_QuestEN[4144] = { title = "Bloodpetal Sprouts", description = "", objectives = "Here's the plan, <name>: Go out and collect some bloodpetal sprouts -- you know, the plants that haven't fully sprouted yet, and bring them here. Then I'll see what the Atal'ai haze can do.\n\nYou may think I'm vengeful... Actually, you'd be right about that! \n\nTruth is, I know the way out of here, but until Larion will admit that I'm right, I'm staying right here!\n\nSo off with you, find those bloodpetal sprouts and let's have some fun!", progress = "Here's the plan, <name>: Go out and collect some bloodpetal sprouts -- you know, the plants that haven't fully sprouted yet, and bring them here. Then I'll see what the Atal'ai haze can do.\n\nYou may think I'm vengeful... Actually, you'd be right about that! \n\nTruth is, I know the way out of here, but until Larion will admit that I'm right, I'm staying right here!\n\nSo off with you, find those bloodpetal sprouts and let's have some fun!", completion = "Here goes nothing, <name>! This will get Larion's attention!" }
WordHunterWoW_QuestEN[4145] = { title = "Larion and Muigin", description = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.", objectives = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", completion = "Thanks for your help, <name>, but I'm afraid I have some bad news..." }
WordHunterWoW_QuestEN[4146] = { title = "Zapper Fuel", description = "You're in luck, <name>! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", objectives = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", progress = "This is exhausting, <name>. Those things just won't leave me alone!", completion = "So, Marvon wasn't around? Well, show me what you got, anyway." }
WordHunterWoW_QuestEN[4147] = { title = "Marvon's Workshop", description = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.", objectives = "Travel to Marvon Rivetseeker's workshop in Ratchet.I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet. I'm sure he'll be able to create some sort of gadget that will help us.", completion = "Marvon's been gone quite a long time now, <name>. He went off to Tanaris to study some of the ancient troll ruins.\n\nNow, what was it that you said you needed?" }
WordHunterWoW_QuestEN[4148] = { title = "Bloodpetal Zapper", description = "", objectives = "For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin's little friends...\n\nIf he weren't so stubborn, we could be on our way home, already... But until then, I'll just have to show him that his little prank doesn't bother me at all!", progress = "For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin's little friends...\n\nIf he weren't so stubborn, we could be on our way home, already... But until then, I'll just have to show him that his little prank doesn't bother me at all!", completion = "Looks like this is going to work perfectly, <name>. Now remember, if you see any of those pests around, don't hesitate to use that zapper!" }
WordHunterWoW_QuestEN[4161] = { title = "Recipe of the Kaldorei", description = "Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a <class>, <name>, so listen well to what I have to tell you.\n\nThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, <name>.\n\nGo out and collect seven small spider legs -- no more than that, and return to me.", objectives = "Collect 7 Small Spider Legs.", progress = "Remember the balance, <name>. I wish you to develop an understanding and a strong empathy for the living forests.", completion = "Always remember what I have shown you today, <name>. You are part of the balance that the night elves strive to keep intact, even during troublesome times." }
WordHunterWoW_QuestEN[4181] = { title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n<name>, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", objectives = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?", completion = "Well <name>, you were wise to seek my tutelage! Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that. It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked <name>, and you might learn something." }
WordHunterWoW_QuestEN[4182] = { title = "Dragonkin Menace", description = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, <name>. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake." }
WordHunterWoW_QuestEN[4183] = { title = "The True Masters", description = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.>Upon completion of this quest you will gain:", objectives = "Travel to Lakeshire in Redridge Mountains and deliver Helendis Riverhorn's Letter to Magistrate Solomon." }
WordHunterWoW_QuestEN[4184] = { title = "The True Masters", description = "This is grim news, <name>. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to King Varian Wrynn in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.Upon completion of this quest you will gain:", objectives = "Travel to Stormwind and deliver Solomon's Plea to King Varian Wrynn.\n\nKing Varian Wrynn resides in Stormwind Keep." }
WordHunterWoW_QuestEN[4185] = { title = "The True Masters", description = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, <name>. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.Upon completion of this quest you will gain:", objectives = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor." }
WordHunterWoW_QuestEN[4186] = { title = "The True Masters", description = "I am going to empower you as an acting deputy of Stormwind, <name>.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree.Upon completion of this quest you will gain:", objectives = "Take Wrynn's Decree to Magistrate Solomon in Lakeshire." }
WordHunterWoW_QuestEN[4201] = { title = "The Love Potion", description = "Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!\n\nYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.\n\nPlease, <name>, help a poor soul in her quest for happiness!", objectives = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", progress = "Do you have the ingredients?  The hole in my heart threatens to consume me!", completion = "Oh, you've done it!  I can now make my potion and use it on Rocknot.  Finally, he will fall victim to my charms!\n\nThank you, <name>.  You are a champion of love!" }
WordHunterWoW_QuestEN[4221] = { title = "Corrupted Windblossom", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4222] = { title = "Corrupted Windblossom", description = "", objectives = "" }
WordHunterWoW_QuestEN[4223] = { title = "The True Masters", description = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, <name>. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.Upon completion of this quest you will gain:", objectives = "Speak with Marshal Maxwell in the Burning Steppes.<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, <name>. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[4224] = { title = "The True Masters", description = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, <name>. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.Upon completion of this quest you will gain:", objectives = "Speak with Ragged John." }
WordHunterWoW_QuestEN[4241] = { title = "Marshal Windsor", description = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?Upon completion of this quest you will gain:", objectives = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[4242] = { title = "Abandoned Hope", description = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, <name>.Upon completion of this quest you will gain:", objectives = "Give Marshal Maxwell at Morgan's Vigil in the Burning Steppes the bad news.Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[4243] = { title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find her?", objectives = "Find A-Me 01 in Un'Goro Crater.", completion = "As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01's shoulder, the other is on her head.\n\nNo power seems to be running through her components as you investigate further." }
WordHunterWoW_QuestEN[4244] = { title = "Chasing A-Me 01", description = "A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"\n\nTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.\n\nOnly trying it will tell.", objectives = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", progress = "The panel in which the mithril casing goes is still closed shut. The rest of A-Me 01 remains inert.", completion = "You remove the panel from A-Me 01's back yet again and carefully remove the old mithril casing that seems to have burnt out. The new one slides into place easily. The only thing left to do, assuming the mithril casing was the problem, is to flip the switch to the \"Off\" position, and then back to the \"On\" position." }
WordHunterWoW_QuestEN[4245] = { title = "Chasing A-Me 01", description = "Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.\n\nThis is your last chance... are you sure this is what you want to do?", objectives = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", completion = "Oh, you've done it! Wonderful! Thank you, <name>.\n\nOh, my poor, A-Me. Look at all those dents. We'll get her up and running perfectly with just a little work.\n\nThank you again, <name>. I really appreciate it." }
WordHunterWoW_QuestEN[4261] = { title = "ncient Spirit", description = "Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...\n\nThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.\n\nEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, <name>, tell me you will lead an ancient spirit away from here, where I may finally rest.\n\nOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.", objectives = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.", completion = "Yes, <name>. Felwood has been through much hardship. Thank you for what you have done.\n\nOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps." }
WordHunterWoW_QuestEN[4262] = { title = "Overmaster Pyron", description = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.", objectives = "Slay Overmaster Pyron.\n\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", completion = "Incendius? Oh dear..." }
WordHunterWoW_QuestEN[4263] = { title = "Incendius!", description = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, <name>!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!", objectives = "Find Lord Incendius in Blackrock Depths and destroy him!", completion = "Oh dear! Are you sure Incendius said 'Ragnaros?'\n\n<Jalinda hands you something and pats you on the wrist as she fades deep into thought.>" }
WordHunterWoW_QuestEN[4264] = { title = "A Crumpled Up Note", description = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan.Upon completion of this quest you will gain:", objectives = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all." }
WordHunterWoW_QuestEN[4265] = { title = "Freed from the Hive", description = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"\n\nIt would seem that you've found the missing courier!", objectives = "Free Raschal from the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.", completion = "Welcome home, <name>.  Raschal checked in just a little while ago and told me what happened.\n\nI... no, the entire Stronghold can't even begin to thank you for your great deed; Raschal would have been dead without your timely aid, and your assistance came to us without even so much as the whisper of a mercenary's fee.  You bear the mark of a true hero.  Know that you will always have a friend in Ginro Hearthkindle." }
WordHunterWoW_QuestEN[4266] = { title = "A Hero's Welcome", description = "<name>, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.", objectives = "Speak with Shandris Feathermoon in Feathermoon Stronghold.<name>, General Shandris Feathermoon would like to speak with you personally. No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas. The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.", completion = "<name>, I give you my warmest thanks for the aid you've given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.\n\nNow, if I may... I'd like to ask for your aid one more time.  In light of the discovery of the Zukk'ash hive here in Feralas, I think you're the best choice for this mission." }
WordHunterWoW_QuestEN[4267] = { title = "Rise of the Silithid", description = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, <name>; may Elune watch over us all.", objectives = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.", progress = "Welcome to this blessed temple, friend.  Your arrival here from Feathermoon Stronghold has been foretold to me.  Do you have the report Shandris Feathermoon asked you to bring?", completion = "We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.\n\nThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.\n\nI pray we will have the resolve to defeat them before they destroy us." }
WordHunterWoW_QuestEN[4281] = { title = "Thalanaar Delivery", description = "This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.", objectives = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.", progress = "Welcome to Thalanaar, <class>.  Do you need assistance of some sort?", completion = "Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!\n\nYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier.  I hope that everything works out.  I know that recently, the Woodpaw have become highly agitated from some source to their south.  Maybe he fell to the wilds there; I would be careful, friend.\n\nRegardless, thank you again.  Here is payment for this parcel's delivery." }
WordHunterWoW_QuestEN[4282] = { title = "A Shred of Hope", description = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, <name>?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge." }
WordHunterWoW_QuestEN[4283] = { title = "FIFTY! YEP!", description = "I'm going to let you in on a little secret, soldier. Come a little closer.\n\nI'M THE ONLY SANE ONE HERE!\n\nLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!\n\n<Oralius lowers his voice.>\n\nLet's just keep that between me, you, and my pal Captain Winky.\n\n<Oralius grabs at the air and squeezes.>\n\nAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!\n\n<Oralius blows into a horn.>\n\nSHIP IT!", objectives = "Collect 50 Blackrock Medallions.", progress = "<Oralius is talking into a rather large, severed ogre ear.>\n\nBurning Steppes to control, come in control.", completion = "You've done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!" }
WordHunterWoW_QuestEN[4284] = { title = "Crystals of Power", description = "I'm sure you've noticed 'em, <name>. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?", objectives = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", progress = "I just know I'm onto something here, <name>!", completion = "Now I will continue my experiments! Thank you, <name>." }
WordHunterWoW_QuestEN[4285] = { title = "The Northern Pylon", description = "What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, <name>. I just know they exist.", objectives = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", completion = "I know the stories are true, <name>." }
WordHunterWoW_QuestEN[4286] = { title = "The Good Stuff", description = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!", objectives = "Collect 20 Dark Iron Fanny Packs.", progress = "I can't be bothered right now, <name>. Me and Winky got a meeting to attend.", completion = "<Oralius starts rummaging through the mountainous pile of fanny packs.>\n\nOH WONDERFUL!\n\n<Oralius sticks his large nose into the pile and takes a whiff.>\n\nDELICIOUS! Look at all these goodies!\n\nTake one for yourself, <name>. There's plenty to go around." }
WordHunterWoW_QuestEN[4287] = { title = "The Eastern Pylon", description = "During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, <name>. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?", objectives = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", completion = "Un'Goro is such a strange place, <name>. When you enter the crater, it's as if you are in a completely different world..." }
WordHunterWoW_QuestEN[4288] = { title = "The Western Pylon", description = "My experiments so far have not yielded any positive results, <name>. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\n<name>, search the western area of the crater; a pylon is said to be somewhere in that area.", objectives = "Discover the location of the Western Crystal Pylon.", completion = "There are many hidden areas of the crater along the sides. Try exploring the winding paths if you can't think of anywhere else to look, <name>." }
WordHunterWoW_QuestEN[4289] = { title = "The Apes of Un'Goro", description = "This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.", objectives = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", progress = "Have the creatures here bested you already, <name>?\n\nDo not be dissuaded so easily. Tracking and defeating the apes of Un'Goro is no simple task, even for a great hunter.", completion = "So, you have proven strong, strong enough to best the great apes of Un'Goro--that is good. The challenge was small compared to Lar'korwi, but I will not take such a great victory away from you.\n\nThese pelts will make wonderful clothing for my tribe. You have helped me and proven worthy.\n\nBefore you set off on another task, let us give praise to the Earth Mother and thank the spirits of those apes you killed--they must know their deaths will not be wasted." }
WordHunterWoW_QuestEN[4290] = { title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards.", objectives = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", progress = "Do not take my words lightly, <name>. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, <name>. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh." }
WordHunterWoW_QuestEN[4291] = { title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, <name>. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", objectives = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Be careful, <name>. Getting close to any of nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, <name>. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death." }
WordHunterWoW_QuestEN[4292] = { title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", objectives = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Do not let fear overpower you, <name>. Fear is the great betrayer... you must remain strong!\n\nTake the meat, place it in the small valley, and then use the gland on it. Only then will death come for you.", completion = "The Earth Mother be praised! You've done it! Fair play to you, <name>. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations." }
WordHunterWoW_QuestEN[4293] = { title = "A Sample of Slime...", description = "Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.\n\nGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.", objectives = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.", progress = "I will need at least five corrupted samples for our control group, <name>. Continue to gather Felwood slime samples until you're able to give me that which we'll need. The Lady Sylvanas decrees it...", completion = "Ah, excellent. These samples will do nicely. I thank you for your help.\n\nOnce we've gathered all the samples of slimes, we'll be able to determine more. I am beginning to suspect that Lady Sylvanas' hunch was not only correct, but more insightful than even she could have predicted. These samples are very interesting. Just seeing how they've reacted with my compounds... hmm, yes, we'll definitely need to investigate further." }
WordHunterWoW_QuestEN[4294] = { title = "... and a Batch of Ooze", description = "Have you heard of the Un'Goro Crater, <name>? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.\n\nIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.\n\nI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.", objectives = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.", progress = "Yes, <name>? How goes your search?", completion = "Truly amazing, <name>. This Un'Goro Crater is holding many more secrets than I expected. I wonder what else we will discover as we test further.\n\nSimply amazing... look at the purity of these samples. Hmm, I wonder what it could mean. They seem to be elemental in nature, but... something more. They remind me of... of the Old Gods. We've found traces of them throughout Azeroth, and now I wonder if these creatures aren't related to them somehow.\n\nWe shall have to test further." }
WordHunterWoW_QuestEN[4295] = { title = "Rocknot's Ale", description = "", objectives = "Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I'm getting sober!  I know this because sobriety blurs my vision... and it's making you look like the <race> I slew last week!", progress = "Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I'm getting sober!  I know this because sobriety blurs my vision... and it's making you look like the <race> I slew last week!", completion = "What's this?  Ah!  It smells like Dark Iron Ale!  Drink has blurred my sight, but I can tell that you, sir, are a real friend!" }
WordHunterWoW_QuestEN[4296] = { title = "Tablet of the Seven", description = "I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow.\n\nThat's what I want.  Wealth!\n\nIf we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!", objectives = "Collect the Tablet Transcript.", progress = "Do you have the writings of the Seven, <name>?  Have you learned the secrets from their tablet?", completion = "Ah, you found the tablet!  And your transcription is superb!  Are you sure you're a <class> and not a scribe?\n\nHere you are, <name>.  Here is the payment I promised." }
WordHunterWoW_QuestEN[4297] = { title = "Food for Baby", description = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.\n\nI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.", objectives = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.", progress = "Find that meat yet, <name>? Your little egg here's just about ready to hatch. If he don't have a good enough first meal, then he might not make it past his first week, and I'd hate for that to happen.\n\nCan't much lie to ya, <name>. I'm jealous of you gettin' this egg to begin with. Don't make me regret helpin' ya out like this.", completion = "These'll do nicely, and if I'm not mistaken, your little egg's just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn't think ya'd have to deal with such responsibility, now did ya?" }
WordHunterWoW_QuestEN[4298] = { title = "Becoming a Parent", description = "Whoa, it was a lot more ready than I thought...", objectives = "Speak to Agnar Beastamer in the Hinterlands.", completion = "Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.\n\nCongrats, <name>. You're a parent... kinda." }
WordHunterWoW_QuestEN[4300] = { title = "Bone-Bladed Weapons", description = "Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.\n\nIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.", objectives = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.", progress = "Me clients are not so patient, <name>. Have you gotten any of the claws yet?", completion = "Ah, these do nicely. Thank you, <name>. An' you be here long before they needed... that be good.\n\nMaybe we have a weapon fashioned for you from the claws. What do you say?" }
WordHunterWoW_QuestEN[4301] = { title = "The Mighty U'cha", description = "While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.", objectives = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", progress = "U'cha... the beast was magnificent. Huge and red, with teeth the size of daggers. His arms as thick as tree trunks, and as fast as any mountain lion I have ever laid eyes upon. You should consider yourself lucky to find such a test of bravery--my people would go generations without seeing such a creature.", completion = "Well done, <name>. I am pleased. You have done a great thing here today.\n\nU'cha was one of the greatest apes I had ever seen. The fact that you have bested his strength speaks well of your own strength... and courage.\n\nIt is only fitting that I give you this as a sign of respect. You have earned it." }
WordHunterWoW_QuestEN[4321] = { title = "Making Sense of It", description = "The information you have given me about the pylons is very interesting...\n\nGive me a moment to do some calculations, <name>. Speak to me again in a moment and I should be able to give you the answer we have been looking for.", objectives = "Speak with J.D. Collie in a moment.", completion = "Alright, <name>. This is fascinating... I can only hope that my diagrams are correct! I compiled everything into this manual, which you can have.\n\nI believe I can answer any questions you have about the crystals now, <name>." }
WordHunterWoW_QuestEN[4322] = { title = "Jail Break!", description = "We need to get out of here, <name>. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.You will receive:", objectives = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed." }
WordHunterWoW_QuestEN[4324] = { title = "Yuka Screwspigot", description = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.", objectives = "Speak with Yuka Screwspigot in the Burning Steppes.Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes. She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister. You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.", completion = "Yes, I'm looking for my brother.  We must find him and retrieve him, bless his heart.\n\nBut if we can't bring all of him... then his head will suffice." }
WordHunterWoW_QuestEN[4341] = { title = "Kharan Mighthammer", description = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, <name>!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!", objectives = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, <name>!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!", completion = "Please, let me explain." }
WordHunterWoW_QuestEN[4342] = { title = "Kharan's Tale", description = "Please, hear me out before passing judgement!", objectives = "Listen as Kharan Mighthammer tells his story.", completion = "As you can see, there was nothing I could have done." }
WordHunterWoW_QuestEN[4343] = { title = "Corrupted Windblossom", description = "", objectives = "" }
WordHunterWoW_QuestEN[4361] = { title = "The Bearer of Bad News", description = "You must take this information back to King Magni, <name>. He will know what to do!", objectives = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.You must take this information back to King Magni, <name>. He will know what to do!", completion = "<King Magni slams his fist down in anger.>" }
WordHunterWoW_QuestEN[4362] = { title = "The Fate of the Kingdom", description = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, <name>. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd <name>, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!", objectives = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", completion = "<Princess Bronzebeard weeps over the loss of Emperor Dagran Thaurissan.>\n\nWhy???" }
WordHunterWoW_QuestEN[4363] = { title = "The Princess's Surprise", description = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.", objectives = "Return to Ironforge and speak with King Magni Bronzebeard.Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.", completion = "<King Magni Bronzebeard is visibly upset.>\n\nIt seems that even in death, Thaurissan has won.\n\nYou are dismissed, <name>. Before you leave, you may choose your reward from the royal vault." }
WordHunterWoW_QuestEN[4381] = { title = "Crystal Restore", description = "", objectives = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[4382] = { title = "Crystal Force", description = "", objectives = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", progress = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
