WordHunterWoW_QuestEN[4447] = { title = "Corrupted Night Dragon", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[4448] = { title = "Corrupted Night Dragon", description = "", objectives = "" }
WordHunterWoW_QuestEN[4449] = { title = "Caught!", description = "Hey! Hey, you! Get over here!\n\nYa gotta help me out. I was runnin' from them Dark Iron dwarves, and I hid in here to get out of sight. Damn geologists and their magic ways! They musta seen me hide, cause next thing I knew, they locked the door and stuck me in here.\n\nTeach them geologists a lesson! Oh... an' can ya get me some pieces of silk cloth for... for... nothin'.", objectives = "Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.", progress = "I ain't got all day! Get me those pieces of silk cloth! I mean geologists. Get those geologists! They deserve to feel my, well... your wrath.", completion = "Oh, this is great! Nice feel to it too!\n\nWhat? Oh, yeah... geologists. Got 'em good, did ya? I can't thank ya enough, <name>. That'll give me some time to finish up in here... Thanks again, <name>." }
WordHunterWoW_QuestEN[4450] = { title = "Ledger from Tanaris", description = "Oh, you know what? That reminds me.\n\nYou wanna finish up a little job I took up while I was in Tanaris? It's easy...\n\nKrinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places. Maybe you could take a look at the list and then bring it all to him?\n\nI'll just slide his ledger under the door if you're interested. Take that, and the stuff he wants back to him after ya collected it all.", objectives = "Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.", progress = "Yes, yes? What can I do for you, <race>? I'm awfully busy and have many patrons requesting my services. Perhaps you can speed things up. I don't mean to be rude, but I just don't have the time if I'm to catch up on all my work.", completion = "Oh, you've seen fit to do some of the work I requested. Excellent. And here I thought you were going to ask me to craft you something.\n\nThese are all perfect... and everything's here. Thank you, <class>.\n\nMaybe it wouldn't hurt to reward you some... hmm, what would you find useful." }
WordHunterWoW_QuestEN[4451] = { title = "The Key to Freedom", description = "The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it:\n\n\"Dark Iron Outhouse - Do Not Duplicate.\"\n\nYou have no idea what it means or what it will lead to.", objectives = "Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found.The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it:\n\n\"Dark Iron Outhouse - Do Not Duplicate.\"\n\nYou have no idea what it means or what it will lead to.", progress = "*cough*\n\nWho is it? Can't ya see I'm busy?", completion = "Well, I'll be! How in tarnation!? You found the key! I knew them blasted Dark Irons were hiding it after they locked me in here! Thank ya so much, <name>. You're the greatest! Now, just turn the key and let ol' Locheed outta here!" }
WordHunterWoW_QuestEN[4461] = { title = "Corrupted Whipper Root", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
