WordHunterWoW_QuestEN[5421] = { title = "Fish in a Bucket", description = "I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon!\n\nBelow the docks here in Shadowprey Village, I've many shellfish traps.  If you're kind enough to do my work and collect me my shellfish, then I'll reward you with something you want... get my drift mon?", objectives = "Jinar'Zillen wants you to collect 5 Shellfish from the traps near Shadowprey Village.", progress = "Ya got mah shellfish, mon?", completion = "Sweet mon, nothing beats work being done, especially if it's someone else doing the work... eh?" }
WordHunterWoW_QuestEN[5441] = { title = "Lazy Peons", description = "Cursed peons!  They work hard gathering lumber from the trees of the valley, but they're always taking naps!  I need someone to help keep the peons in line.\n\nYou look like the right <race> for my task.  Here, you take this blackjack and use it on any lazy peons you find sleeping on the job.  A good smack will get them right back to work!  Return the blackjack when you're done.\n\nLousy slacking peons...", objectives = "Use the Foreman's Blackjack on Lazy Peons when they're sleeping. Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!" }
WordHunterWoW_QuestEN[5461] = { title = "The Human, Ras Frostwhisper", description = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.\n\nUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.\n\nYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, <name>.", objectives = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", progress = "A keepsake of remembrance is a rare find, <name>.", completion = "I had doubted the possibility of such an item existing. This certainly opens up an incredible opportunity - one we must not squander.\n\nPrepare yourself, <name>, for what I am about to ask of you will take you into the depths of hell." }
WordHunterWoW_QuestEN[5462] = { title = "The Dying, Ras Frostwhisper", description = "Upon tainted soil, the keepsake must be attuned.\n\nIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.\n\nIt is those grounds that must be found.\n\nThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, <name>.", objectives = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", progress = "Do not ask questions of which you do not want answers.", completion = "<Leonid looks over the keepsake.>\n\nYour quandary stirs up memories that I had hoped would never resurface." }
WordHunterWoW_QuestEN[5463] = { title = "Menethil's Gift", description = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.\n\n<Leonid gazes at the ground and then looks up at you.>\n\nYes, <race>, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge.", objectives = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.", progress = "The area around Menethil's Gift is exceptionally cold.", completion = "You place the keepsake on the tainted soil." }
WordHunterWoW_QuestEN[5464] = { title = "Menethil's Gift", description = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack.", objectives = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", progress = "<Leonid shudders.>", completion = "As the soul clung to the keepsake, so shall it cling to the physical form of Ras Frostwhisper." }
WordHunterWoW_QuestEN[5465] = { title = "Soulbound Keepsake", description = "Return to Marduke with the keepsake, <name>. He will instruct you in its use.", objectives = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", progress = "Have you done the impossible?", completion = "I was certain that you would be joining me as another hapless spirit." }
WordHunterWoW_QuestEN[5466] = { title = "The Lich, Ras Frostwhisper", description = "There is but one task remaining, <name>. Confront the lich, Ras Frostwhisper, in his lair.\n\nUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!\n\nWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.", objectives = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", progress = "You carry the burden of ten thousand restless souls, <name>.", completion = "Ten thousand souls cry out in unison, <name>! You have struck a mortal blow to the Scourge and their masters." }
WordHunterWoW_QuestEN[5481] = { title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill graveyard.", objectives = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard.", progress = "Where's that useless abomination? Either you have what I need or you'd best get out there and find it.", completion = "What's this? Gloom weed?! I've no need for Gloom weed! That mindless mass of flesh is out there picking daisies and convincing the Lady knows how many dupes like you into doing the same. No offense.\n\nVery well, you're here now and that's all that matters. Since I'm not going to bother to try to explain things to that abomination how about you collect what I really need... doom weed!" }
WordHunterWoW_QuestEN[5482] = { title = "Doom Weed", description = "So you can see the predicament that I'm in, <name>. That thing is out there collecting the wrong weeds! I'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", objectives = "Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.", progress = "This had better be good. I trust you have all of the doom weed that I require?", completion = "Ah, my doom weed. Excellent!\n\n<Junior Apothecary Holland rubs his hands together greedily.>\n\nThese will come in quite handy. You've done me, uh, the Lady, a fine service today, <name>. As promised, here is the reward that you deserve." }
WordHunterWoW_QuestEN[5501] = { title = "Bone Collector", description = "We're sitting on a goldmine here, I tell you - a goldmine!  Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them.\n\nThere's a caravan that comes by and picks up my kodo bones and then sells them at Shadowprey Village.  If you can travel to the kodo graveyard south of here and bring me ten kodo bones, I'll give you something in return.  Is it a deal?", objectives = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.", progress = "Do you have the bones?  The caravan will be here any moment.  I need just ten more kodo bones to reach a career high.  A career high, I tell you!", completion = "Ah, goodie!  My bones!\n\nI can't wait till the chaps at home see my face on the front cover of Goblin'preneur.  I'll be the richest goblin in the world... and my physical education teacher said I would never amount to anything." }
WordHunterWoW_QuestEN[5502] = { title = "A Warden of the Horde", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to see all the stuff we did. Do you think we find Blax Bottlerocket again and get a foam sword rack from him? I think he's still pushing that cart up and down the main road in the Drag. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", objectives = "Purchase a Foam Sword Rack from Blax Bottlerocket in Orgrimmar's Drag. Then return your ward to the Orgrimmar orphanage by speaking with Orphan Matron Battlewail in The Drag.", progress = "It is a pleasure to see you again, <name>.  Have you attended to the duties you've volunteered for during Children's Week?", completion = "May the spirits bless you, <name>.  You've done more for Grunth than most would ever think of doing for him.  Thank you - you're the epitome of what it means to be a hero of the Horde.\n\nThe orphans will love your gift; it's not often that they get a new toy.\n\nGrunth had so much fun with you, <name>.  He wanted to give you one of his favorite pets to remember him by." }
WordHunterWoW_QuestEN[5503] = { title = "Argent Dawn Commission", description = "", objectives = "All who fight evil on behalf of the Argent Dawn must don our commission.  Wearing such will earn your right to claim rewards our quartermasters have to offer.\n\nWhile under commission, you'll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess.  Procure these insignia and bring them to me.  For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.\n\nAchieve your destiny, <class> - join the fight today!You will receive:" }
WordHunterWoW_QuestEN[5504] = { title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, <name>.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.Upon completion of this quest you will gain:", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5505] = { title = "The Key to Scholomance", description = "", objectives = "Well, here you are, <name> - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", progress = "Well, here you are, <name> - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", completion = "Good luck, mighty hero. May your victories continue to bring you fame and power as you lay waste to Scholomance!" }
WordHunterWoW_QuestEN[5507] = { title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, <name>.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.", progress = "Ah, noble <class>!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, <name>.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!" }
