WordHunterWoW_QuestEN[5511] = { title = "The Key to Scholomance", description = "", objectives = "Well, here you are, <name> - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", progress = "Well, here you are, <name> - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There's only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.", completion = "Good luck, mighty hero. May your victories continue to bring you fame and power as you lay waste to Scholomance!" }
WordHunterWoW_QuestEN[5513] = { title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, <name>.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.", progress = "Ah, noble <class>!  Have you brought the valor tokens requested of you?  Once you hand them to me, I will make our various mantles available to you for purchase.", completion = "Outstanding - your tribute to the Dawn is duly noted, <name>.  With this accomplished, I am delighted to make our mantles available to you for purchase.  So long as you maintain your current status with us, these mantles will be purchasable from any authorized quartermaster of the Argent Dawn.\n\nFor the Dawn, my brother!" }
WordHunterWoW_QuestEN[5514] = { title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", progress = "Yeah, I know who you are, and I know why you're here.  Dithers sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Dithers said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Dithers imbue them already?  Excellent... otherwise, it would have been a long trip back to the Bulwark for you." }
WordHunterWoW_QuestEN[5515] = { title = "Krastinov's Bag of Horrors", description = "A great weight has been lifted from our hearts, <name>, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.\n\nBefore you may face Kirtonos, however, you must first secure a method in which to summon him.\n\nIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.\n\nFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.", objectives = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", progress = "<Eva fades in and out of focus.>", completion = "The bag of horrors!" }
WordHunterWoW_QuestEN[5517] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands." }
WordHunterWoW_QuestEN[5518] = { title = "The Gordok Ogre Suit", description = "If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.\n\nHow, you ask?  Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos.  The only problem is stability - ten minutes tops.  Bring me what I need, and I'll make you one.  I'm not going anywhere...", objectives = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", progress = "The Ogre Tannin is probably the toughest thing to find for what I need to make the suit - I think they have some upstairs?  It's hard to tell, since this ball and chain doesn't make movement that easy to do...\n\nAnyway, bring me the things I need, and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", completion = "Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin's face.>\n\nHere you go, you're all set.  Remember- this isn't the most securely fashioned item in the world.  You'll have ten minutes of use before it falls apart, and then you're not going to fool anybody!  Try using it just before you approach him, and remember... it only will make him think that YOU are an ally - not your group mates!" }
WordHunterWoW_QuestEN[5519] = { title = "The Gordok Ogre Suit", description = "", objectives = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me the same things I asked for from before, and I'll make you another ogre suit.", progress = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me the same things I asked for from before, and I'll make you another ogre suit.", completion = "Here ya go <name> - put this thing on, and you'll have ten minutes to do whatever.  Good luck!\n\nOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!" }
WordHunterWoW_QuestEN[5521] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5522] = { title = "Leonid Barthalomew", description = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.\n\nLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.\n\nThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded.", objectives = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", progress = "You are the one up to mischief in Blackrock Spire, yes?  Do you have what I asked for?", completion = "Ah, very good.  You do not know the evil power for whom you have labored, but now you will know the truth.  And fear not--I am no servant of that master.  I am Leonid Barthalomew, known as \"the Revered\" to my brethren in the Argent Dawn.\n\nI tricked Tinkee into sending you and the dragon eggs to me.  And it is good that my trick was successful, for had these eggs reached their intended destination, a great power would have fallen into the hands of the enemy." }
WordHunterWoW_QuestEN[5524] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5525] = { title = "Free Knot!", description = "", objectives = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?! Is that it there??!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?! Is that it there??!", completion = "Oh, thank you for freeing me! You - ranked number one. Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
WordHunterWoW_QuestEN[5526] = { title = "Shards of the Felvine", description = "Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, <name>.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.\n\nThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.\n\nGood luck, and Cenarion's speed.", objectives = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.\n\nI know Milli would have had it no other way...", completion = "It is done, brave <class>, and with that the Cenarion Circle is in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this as a token of our enduring gratitude.  Know that you are welcomed here as a hero of the Cenarion Circle for your great deed, <name>.  Thank you." }
WordHunterWoW_QuestEN[5527] = { title = "A Reliquary of Purity", description = "The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.\n\nDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.", objectives = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", progress = "A Reliquary of Purity is an artifact unto itself.  Few were ever made, and almost all of them were thought to have been lost over time.\n\nI admit I have known about the one in Southwind for a little while now.  Honestly, with the rising turmoil in Silithus, I thought to keep our secrets just that - a secret.  To poke and prod would only cause suspicions of our enemies to rise.\n\nAlas, the time for complacency is at an end, especially with the situation in Eldre'Thalas.", completion = "Indeed, you are as resourceful as many claim.  The Cenarion Circle is blessed to have you working in our stead.\n\nWith the Reliquary once more in our hands, my mind is at ease.  I feel more comfortable asking you to not only face down a malfeasant demon, but also to bring back a dangerous item in the process..." }
WordHunterWoW_QuestEN[5528] = { title = "The Gordok Taste Test", description = "", objectives = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!You will receive:" }
WordHunterWoW_QuestEN[5529] = { title = "Plagued Hatchlings", description = "The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!\n\nTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.\n\nGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!", objectives = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", completion = "Well done, <name>!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!" }
WordHunterWoW_QuestEN[5531] = { title = "Betina Bigglezink", description = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.\n\nNow, it is time we ended their research.\n\nTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.", objectives = "Bring the Frozen Eggs to Betina Bigglezink.", progress = "Hello, <name>!  I heard you were here with some dragon eggs?  Well, let's see them!", completion = "There they are!  And in such a nice container.  The perfect size!\n\nWe'll keep these eggs in a safe place so we can study them later, but right now we need that thing you brought them in.\n\nI have created a device with a very specific use: to destroy the undead scholars of the Scholomance.  They are studying dragons in their efforts to create a plagued dragonflight, and we must halt their progress.\n\nI call the device Dawn's Gambit, because... I'm not sure if it works!\n\nWill you find out for us?" }
WordHunterWoW_QuestEN[5533] = { title = "Scholomance", description = "On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.", objectives = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil. Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much. A door bars the way, and try as we might no entry is to be had without a proper key.\n\nAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key. You have proved your worth to me, and now I entrust this task to you. Speak with him on this matter.", completion = "Well met, <class>.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire a key... one that will let you past the front door.\n\nI can only imagine what horrid sights are to be seen inside, <name>.  I don't know how you heroic types do it sometimes..." }
WordHunterWoW_QuestEN[5534] = { title = "Kim'jael's \"Missing\" Equipment", description = "What?! What?!\n\nThat wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some.\n\nIf you're a \"valuable\" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.", objectives = "Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.", progress = "Well, <name>? Where is the rune? You are a good employee, right? You're here to help?\n\nDon't make me think twice about paying you what we agreed upon. What? Oh, we didn't agree on anything? Oh, great... then take your time--just know that it'll be a lot less if you take a long time.", completion = "Haha! Wonderful!\n\nI'll be sure to find out what this is for and why Magus Rimtori--she's the cow that hired me--wanted it. Hah! I got you now, stinkin' Blood elves! Kim'jael! Ha! I'll teach them who the rats are!\n\nYa did good, <name>. Thanks a bundle. Here, take this coin and be off with ya--I've got some things to figure out." }
WordHunterWoW_QuestEN[5535] = { title = "Spiritual Unrest", description = "Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know.\n\nI promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some.\n\nThe spirits haunt the Shadowsong Shrine to the northeast of here.", objectives = "Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.", completion = "Well done, <class>. Thank you for your help. The spirits are at peace, and the threats that their desire for the arcane draw have been lessened.\n\nI am sure that both sides of the conflict that ravishes Azeroth will see you are above such things." }
WordHunterWoW_QuestEN[5536] = { title = "A Land Filled with Hatred", description = "The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance.\n\nI am sure you would prove yourself if you aided me in purging them.\n\nNortheast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their power.", objectives = "Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.", completion = "Well done, <class>. I see you're not only skilled but cunning. To defeat such creatures is a testament to your loyalty to the tenants of the Earthmother, even if you do not recognize her as your own deity. She is in all things on this planet and beyond. Her eyes, one dark and one light, travel across the skies always gazing down upon us.\n\nPlease, take this small amount of coin in appreciation for what you have done." }
WordHunterWoW_QuestEN[5537] = { title = "Skeletal Fragments", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, <name>.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", objectives = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "As morbid as it sounds, we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, <name>!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder." }
WordHunterWoW_QuestEN[5538] = { title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", progress = "Yeah, I know who you are, and I know why you're here.  Arbington sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Arbington said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Arbington imbue them already?  Excellent... otherwise, it would have been a long trip back to Chillwind Point for you." }
WordHunterWoW_QuestEN[5541] = { title = "Ammo for Rumbleshot", description = "Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.\n\nBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!\n\n<name>, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.", objectives = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", progress = "I hope you're not here for ammo, because I'm almost out!", completion = "Great, more ammo!  Old Loslor's shipment finally came through!  The ammo might be late, but just like my grand daddy used to tell me: late's better than never!\n\nThank you much, <name>.  I already have buyers eager for this stuff!" }
WordHunterWoW_QuestEN[5542] = { title = "Demon Dogs", description = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'\n\nYou can start with the Plaguehounds and their runts.\n\nI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.", objectives = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", completion = "Well done, <name>. Come. Rest. Let us eat and talk of days long past!" }
WordHunterWoW_QuestEN[5543] = { title = "Blood Tinged Skies", description = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.\n\nEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.", objectives = "Slay 30 Plaguebats and return to Tirion Fordring.", completion = "You are a shining example of decency, <race>! It has been long since I have felt the blood of heroes pump through my veins. Your acts of bravery are uplifting!" }
WordHunterWoW_QuestEN[5544] = { title = "Carrion Grubbage", description = "My food supplies are running low, <race>. I am ashamed to admit that I might not have enough food to share with you.\n\nCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!", objectives = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", progress = "You will grow to tolerate the taste, <race>.", completion = "May the Light watch over you! Bless you, young one." }
WordHunterWoW_QuestEN[5545] = { title = "A Bundle of Trouble", description = "I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.\n\nI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.", objectives = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.", progress = "That deadline isn't getting any further away, <class>. Please hurry and collect those bundles of wood.", completion = "Excellent! Thanks to you, I should be able to complete the order in time. To show my gratitude, I would like to offer some coin as compensation for your troubles.\n\nThank you and farewell." }
WordHunterWoW_QuestEN[5561] = { title = "Kodo Roundup", description = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.", objectives = "Bring 3 Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.", progress = "The caravan will be here shortly; do you have the newly tamed kodos I was asking for?", completion = "<Smeed Scrabblescrew begins counting.>\n\nThree, excellent, I ask for three tamed kodos and I get three tamed kodos... I am going to be rich... yes, very rich! I hope to see the look on Bibbly's green face when he hears about my success!" }
WordHunterWoW_QuestEN[5581] = { title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one of the Burning Blade leaders myself.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do.\n\nWith the demon threat increasing we must close these portals to stem the tide of demons to this world.", objectives = "Banish 6 Portals at Mannoroc Coven and return to Felgur Twocuts at Ghost Walker Post.", completion = "Your efforts have helped to slow down the enemy, <class>.\n\nThank you." }
WordHunterWoW_QuestEN[5582] = { title = "Healthy Dragon Scale", description = "This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.\n\nBetina Bigglezink will want a sample of this to study.", objectives = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.", progress = "<name>, do you have something to show me?", completion = "Excellent!  This will be invaluable in my continued studies of the machinations of the Scourge.  Thank you, <name>, and if you find more of these scales please bring them to me!" }
WordHunterWoW_QuestEN[5601] = { title = "Sister Pamela", description = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.\n\nDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.\n\nPlease, find her for me!", objectives = "Find Pamela Redpath in Darrowshire.I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not. I fear they were all killed during the battle of Darrowshire.\n\nDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands. Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.\n\nPlease, find her for me!", completion = "Where is my sister Jessica?  She left so long ago, when I was just a little girl.  She cried so much when she went away.  I don't know why she cried!  Maybe she fell and hit her toe.\n\nWhen Jessica was here we used to play games and dance and pick pretty flowers around the house.  And sometimes we'd hide when we saw daddy coming home, then jump out and surprise him!\n\nCome back, Jessica!  If you come back then maybe daddy will too and we can all play together again..." }
WordHunterWoW_QuestEN[5621] = { title = "Garments of the Moon", description = "I need your help, <name>. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya.\n\nWhen you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.You will receive:", objectives = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar." }
WordHunterWoW_QuestEN[5622] = { title = "In Favor of Elune", description = "<name>, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a <priest/priestess> of Elune.\n\nTake care, and may you be protected in your journeys.Upon completion of this quest you will gain:", objectives = "Speak to Laurna Morninglight in Teldrassil.<name>, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a <priest/priestess> of Elune.\n\nTake care, and may you be protected in your journeys.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5623] = { title = "In Favor of the Light", description = "Hello again, young <priest/priestess>. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Josetta in Elwynn Forest.Hello again, young <priest/priestess>. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5624] = { title = "Garments of the Light", description = "Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the <priest/priestess> and supports <him/her>.\n\nBut this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test complete.You will receive:", objectives = "Find Guard Roberts and heal his wounds using Flash Heal." }
WordHunterWoW_QuestEN[5625] = { title = "Garments of the Light", description = "It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.\n\nYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?You will receive:", objectives = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos." }
WordHunterWoW_QuestEN[5626] = { title = "In Favor of the Light", description = "Hey! <name>! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a <priest/priestess>.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.Upon completion of this quest you will gain:", objectives = "Speak to Maxan Anvol in Dun Morogh.Hey! <name>! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a <priest/priestess>.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5627] = { title = "Stars of Elune", description = "", objectives = "" }
WordHunterWoW_QuestEN[5628] = { title = "Returning Home", description = "Ah, yes, hello, <name>? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.\n\nThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Ah, yes, hello, <name>? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.\n\nThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5629] = { title = "Returning Home", description = "Hello again, <name>. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Hello again, <name>. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5630] = { title = "Returning Home", description = "Hello there, <laddy/lassy>. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.\n\nNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Hello there, <laddy/lassy>. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.\n\nNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5631] = { title = "Returning Home", description = "A priestess recently visited our halls seeking you out, young <race>. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.\n\nThe Light be with you, <name>.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.A priestess recently visited our halls seeking you out, young <race>. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.\n\nThe Light be with you, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5632] = { title = "Returning Home", description = "Oh, yes, of course. Hello, <name>. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.\n\nAgain, return to Darnassus when you can.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Oh, yes, of course. Hello, <name>. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.\n\nAgain, return to Darnassus when you can.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5633] = { title = "Returning Home", description = "Greetings, <laddy/lass>. Good to see you here in our great halls. A blessing be on you and your kind.\n\nWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Greetings, <laddy/lass>. Good to see you here in our great halls. A blessing be on you and your kind.\n\nWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5634] = { title = "Desperate Prayer", description = "", objectives = "" }
WordHunterWoW_QuestEN[5635] = { title = "Desperate Prayer", description = "You've caught the attention of our superiors, <name>. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.You've caught the attention of our superiors, <name>. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5636] = { title = "Desperate Prayer", description = "Elune bless you, good <race>. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.Elune bless you, good <race>. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5637] = { title = "Desperate Prayer", description = "Time's come for you to head to Stormwind, <name>. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.Time's come for you to head to Stormwind, <name>. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5638] = { title = "Desperate Prayer", description = "Just a short time ago, one of your priests was here looking for you, <race>. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good <race>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.Just a short time ago, one of your priests was here looking for you, <race>. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good <race>.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5639] = { title = "Desperate Prayer", description = "You're needed in Stormwind, <name>. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, <name>.", objectives = "Speak to High Priestess Laurena in Stormwind.You're needed in Stormwind, <name>. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, <name>." }
WordHunterWoW_QuestEN[5640] = { title = "Desperate Prayer", description = "Praise be to Elune, and to your Light, <name>.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.Praise be to Elune, and to your Light, <name>.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5641] = { title = "A Lack of Fear", description = "", objectives = "" }
WordHunterWoW_QuestEN[5642] = { title = "Shadowguard", description = "Something important is up in Orgrimmar, <name>.\n\nThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar.Something important is up in Orgrimmar, <name>.\n\nThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.You will receive:" }
WordHunterWoW_QuestEN[5643] = { title = "Shadowguard", description = "Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.Upon completion of this quest you will gain:", objectives = "Speak to Ur'kyo in Orgrimmar.Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5644] = { title = "Devouring Plague", description = "Ah, a wonderful day for you, <name>. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, <name>. She will be awaiting you in the War Quarter.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.Ah, a wonderful day for you, <name>. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, <name>. She will be awaiting you in the War Quarter.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5645] = { title = "A Lack of Fear", description = "<name>, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.Upon completion of this quest you will gain:", objectives = "Speak to High Priest Rohan in Ironforge.<name>, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5646] = { title = "Devouring Plague", description = "Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, <name>. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, <name>. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5647] = { title = "A Lack of Fear", description = "Your race is so very strong, <name>. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.You will also receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priest Rohan in Ironforge.Your race is so very strong, <name>. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.You will also receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5648] = { title = "Garments of Spirituality", description = "You be ready for your first test, <name>. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors.\n\nYou do this, an' me thinks that be sufficient proof that you ready to move on in our ways.You will receive:", objectives = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill." }
WordHunterWoW_QuestEN[5649] = { title = "In Favor of Spirituality", description = "Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.\n\nYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.Upon completion of this quest you will gain:", objectives = "Speak to Tai'jin in Durotar.Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.\n\nYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5650] = { title = "Garments of Darkness", description = "Our power comes from darkness and shadow, <name>, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you.\n\nNorth of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then return to me.You will receive:", objectives = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill." }
WordHunterWoW_QuestEN[5651] = { title = "In Favor of Darkness", description = "There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.\n\nSeek out Dark Cleric Beryl in Brill when you're ready to learn more.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Dark Cleric Beryl in Tirisfal Glades.There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.\n\nSeek out Dark Cleric Beryl in Brill when you're ready to learn more.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5652] = { title = "Hex of Weakness", description = "", objectives = "" }
WordHunterWoW_QuestEN[5654] = { title = "Hex of Weakness", description = "It be time for you to meet with Ur'kyo, <name>. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.Upon completion of this quest you will gain:", objectives = "Speak to Ur'kyo in Orgrimmar.It be time for you to meet with Ur'kyo, <name>. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5655] = { title = "Hex of Weakness", description = "I sent here to make sure that you not wander too far from home, <name>. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar.I sent here to make sure that you not wander too far from home, <name>. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.You will receive:" }
WordHunterWoW_QuestEN[5656] = { title = "Hex of Weakness", description = "It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, <name>.\n\nUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar.It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, <name>.\n\nUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.You will receive:" }
WordHunterWoW_QuestEN[5657] = { title = "Hex of Weakness", description = "Home. Return home, young <race>.\n\nYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.\n\nGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar.Home. Return home, young <race>.\n\nYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.\n\nGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.You will receive:" }
WordHunterWoW_QuestEN[5658] = { title = "Touch of Weakness", description = "", objectives = "" }
WordHunterWoW_QuestEN[5660] = { title = "Touch of Weakness", description = "You be far from home, <class>. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.You be far from home, <class>. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5661] = { title = "Touch of Weakness", description = "You be far from home out here in the Bloodhoof Village, <name>. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.\n\nI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.\n\nGo to meet Aelthalyste in the War Quarter in that city of yours.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.You be far from home out here in the Bloodhoof Village, <name>. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.\n\nI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.\n\nGo to meet Aelthalyste in the War Quarter in that city of yours.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5662] = { title = "Touch of Weakness", description = "My respect to you and your kind, <name>. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.My respect to you and your kind, <name>. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5663] = { title = "Touch of Weakness", description = "Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.\n\nYou can find Aelthalyste in the War Quarter deep in the Undercity.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity.Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.\n\nYou can find Aelthalyste in the War Quarter deep in the Undercity.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5672] = { title = "Elune's Grace", description = "", objectives = "" }
WordHunterWoW_QuestEN[5673] = { title = "Elune's Grace", description = "You know you have access to any of our trainers at any time, <name>, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.\n\nReturn there when you can and speak to Priestess Alathea.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.You know you have access to any of our trainers at any time, <name>, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.\n\nReturn there when you can and speak to Priestess Alathea.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5674] = { title = "Elune's Grace", description = "A wonderful day has come, <name>. You've reached the age in which our <priests/priestesses> are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.A wonderful day has come, <name>. You've reached the age in which our <priests/priestesses> are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5675] = { title = "Elune's Grace", description = "Time's a wastin', <lad/lass>. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus.Time's a wastin', <lad/lass>. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5676] = { title = "Arcane Feedback", description = "", objectives = "" }
WordHunterWoW_QuestEN[5677] = { title = "Arcane Feedback", description = "As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, <name>... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, <name>... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5678] = { title = "Arcane Feedback", description = "It is time for you to return to Stormwind, young one. Your superiors there have called you back for more training. And although it disturbs me some, your race and mine are allies and I would not betray that.\n\nI do not mean to be so coy with you--my distrust of arcane magics, be they divine inspired or not, is still strong within me.\n\nYou will know of what I speak after you return to your Cathedral of Light. Speak to High Priestess Laurena when you arrive.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind.It is time for you to return to Stormwind, young one. Your superiors there have called you back for more training. And although it disturbs me some, your race and mine are allies and I would not betray that.\n\nI do not mean to be so coy with you--my distrust of arcane magics, be they divine inspired or not, is still strong within me.\n\nYou will know of what I speak after you return to your Cathedral of Light. Speak to High Priestess Laurena when you arrive.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5679] = { title = "Devouring Plague", description = "", objectives = "" }
WordHunterWoW_QuestEN[5680] = { title = "Shadowguard", description = "", objectives = "" }
WordHunterWoW_QuestEN[5713] = { title = "One Shot.  One Kill.", description = "I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.\n\nI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.\n\nShould we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.", objectives = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.", completion = "You bring most welcome news <class>. It is good to hear that Aynasha is alive and well thanks to you. I would hope that you might accept a reward for your valor. May Elune watch over you and light your path." }
WordHunterWoW_QuestEN[5721] = { title = "The Battle of Darrowshire", description = "Now, <name>, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", objectives = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if came to our house, so I made some tea!\n\nI hope you like lots of sugar!" }
WordHunterWoW_QuestEN[5722] = { title = "Searching for the Lost Satchel", description = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.", objectives = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.", completion = "The body looks seriously beaten by clubs or fists, but most of the corpse's clothing and equipment still looks present. It seems the troggs do not overly care much for material wealth.\n\nYou begin to search the body for anything of interest that might help Magatha." }
WordHunterWoW_QuestEN[5723] = { title = "Testing an Enemy's Strength", description = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.", objectives = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", completion = "I am glad to see you took Magatha's task seriously. Thank you, <name>. I'm sure the troggs will have a harder time coming to the surface with their numbers so greatly reduced.\n\nPerhaps in the future we can take time to figure out where such creatures came from, and what they really want." }
WordHunterWoW_QuestEN[5724] = { title = "Returning the Lost Satchel", description = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.", objectives = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.", progress = "Were you able to find anything, <name>? Any clues as to why one of her clansman had to die needlessly would be helpful.", completion = "Excellent, <name>. Thank you.\n\nMagatha told me that if you were successful in finding her clansman that you be given this. Please, take it in thanks." }
WordHunterWoW_QuestEN[5725] = { title = "The Power to Destroy...", description = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.Upon completion of this quest you will gain:", objectives = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity." }
WordHunterWoW_QuestEN[5726] = { title = "Hidden Enemies", description = "One thing I will not tolerate are traitors in our midst, <name>. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.", objectives = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", progress = "Do you have the insignia yet, <name>?\n\nIt will be a vital tool in infiltrating what I believe is the greatest threat to the Horde, and finally finding peace in our new home.\n\nYou will learn how intricate a web men and orcs alike can weave when they are motivated by greed and power. The hidden agendas, the corruption, all of it will become clear. You will find yourself in the midst of a war you never knew existed.", completion = "Good, <name>! The spirits be praised, perhaps you are the one who will finally put my greatest fears to rest! Who would suspect someone so young and so brave would rise up and champion our cause? You remind me of myself when I was younger. I will ensure that you are justly rewarded for your efforts if we both survive the coming storm.\n\nBut there is time for more praise later. You've not accomplished anything in comparison to what you will face... but this is a good start." }
WordHunterWoW_QuestEN[5727] = { title = "Hidden Enemies", description = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.", objectives = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", completion = "Excellent! Most excellent, <class>!\n\nWhat you have done this day is only the first step in a much broader foundation--a foundation that we will build the destruction of the Shadow Council on, once and for all.\n\nTell me all he said... and leave not one word out--it may be more important than you realize." }
WordHunterWoW_QuestEN[5728] = { title = "Hidden Enemies", description = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, <name>. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his <brothers/sisters> in arms.", objectives = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", completion = "I am glad you've returned, <name>. Some of those loyal to me brought word immediately that the caverns below Orgrimmar were in disarray now that their leaders have been slain. I even heard reports that Neeru was more than agitated. It seems we've put a dent in his armor. I can't say I'm displeased... even with such a minor victory." }
WordHunterWoW_QuestEN[5729] = { title = "Hidden Enemies", description = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too overt.", objectives = "Speak to Neeru Fireblade in Orgrimmar.I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too overt.", completion = "What is it?! Oh, you, <class>... my apologies. My anger rivals that of a rabid kodo bull... but perhaps it is my own fault. In sending travelers into Ragefire Chasm, I should have seen the possibility that some harm would come from it. It seems both Bazzalan and Jergosh were taken unaware and slain by some of Thrall's do-gooders. A most inopportune time, but there is nothing that can be done about it now." }
WordHunterWoW_QuestEN[5730] = { title = "Hidden Enemies", description = "You are one of my lieutenants! Prepare yourself, <class>. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.", objectives = "Speak to Thrall in Orgrimmar and tell him what you've learned.You are one of my lieutenants! Prepare yourself, <class>. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.", completion = "Ashenvale? Hmm, I had not heard of any presence of the Council or the Burning Blade in Ashenvale. My spies will investigate, <name>. You have done well.\n\nFor now, rest, and keep yourself occupied with other tasks. I will call upon you again soon.\n\nLok-Tar Ogar!" }
WordHunterWoW_QuestEN[5741] = { title = "Sceptre of Light", description = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.", objectives = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.", progress = "Do you have the Sceptre of Light?", completion = "The elusive Sceptre of Light!  Your acquisition of it has removed a grave threat to the world.  Well done, <class>, well done." }
WordHunterWoW_QuestEN[5742] = { title = "Redemption", description = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.", objectives = "Listen to what Tirion Fordring has to say.", completion = "The Fordring redemption will be a difficult task. Are you prepared?" }
WordHunterWoW_QuestEN[5761] = { title = "Slaying the Beast", description = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.", objectives = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", progress = "Have you killed the beast? He surely must be the leader of the Searing Blade in Ragefire Chasm.", completion = "Ha! You've done it! Thrall will be so pleased.\n\nI will ensure this heart is taken care of properly.\n\nFor now though, you must celebrate your victory. I will inform Thrall of your success.\n\nThank you for your aid, <class>." }
WordHunterWoW_QuestEN[5762] = { title = "Hemet Nesingwary Jr.", description = "I have a package for a new customer of mine, a dwarf named Hemet Nesingwary Jr..  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to take his father's place and hunt the beasts there, but he left me some money to send his delivery when I could.  \n\nJunior's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me?\n\nI heard he has a camp in Stranglethorn, north of Grom'gol.", objectives = "Take Kravel's Crate to Hemet Nesingwary Jr. in Stranglethorn Vale.", progress = "Is that desert dust on your collar?\n\nHm... if my nose tells true, I'd say it's not desert dust, it's desert salt!   Been to the Shimmering Flats, have you?", completion = "Great, my package from Koalbeard!  Thank you <name>.  This crate holds special-gauge ammunition - my father swears by it - and it'll serve us well out in the jungle!\n\nHere's your pay, and tell me, how is crusty old Kravel these days?  Up to no good I'd wager..." }
WordHunterWoW_QuestEN[5763] = { title = "Hunting in Stranglethorn", description = "Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.\n\nWhen he left for Stranglethorn, I vowed to one day welcome him back.  Now he has gone on to hunt in lands unknown, but his son has taken his place.\n\nTake this kodo horn as a gift to Hemet Jr..  You will find him in Stranglethorn, north of the Grom'gol Base camp.", objectives = "Bring Roon's Kodo Horn to Hemet Nesingwary Jr. in Stranglethorn.", progress = "Sit, <class>.  Soon enough you'll strike back into the jungle.", completion = "Ah, this horn belongs to a <race>, Roon Wildmane.  My father spoke often of the good times they had together hunting the beasts of Desolace.  So Roon is inviting me to join him, is he?\n\nWe're neck deep in the jungle right now, but thank you, <name>.  Perhaps my next expedition will take me to Desolace, the land of the centaurs." }
WordHunterWoW_QuestEN[5781] = { title = "Of Forgotten Memories", description = "To help Taelan regain what he has lost, you must gather items from his past.\n\nThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.\n\nAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.\n\nYou must venture to the Undercroft and recover Taelan's hammer.", objectives = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", progress = "He must be redeemed.", completion = "<Tirion blinks to hold back tears.>\n\nIt was destiny that we meet, <name>. You have blessed me with your kindness." }
WordHunterWoW_QuestEN[5801] = { title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Arbington again.", objectives = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\n\nBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "Do you have the stem of the skeletal key finished?  I'm sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we <name>?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the nefarious being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own." }
WordHunterWoW_QuestEN[5802] = { title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Dithers again.", objectives = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\n\nBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "Do you have the stem of the skeletal key finished?  I'm truly sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we <name>?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own." }
WordHunterWoW_QuestEN[5803] = { title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, <name>!", objectives = "Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "You've come this far <name> - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key.  Get Araj's scarab by whatever means necessary and bring it to me - I will fuse it on as the head of the key.", completion = "Yes, this is it!  I... again, I'm absolutely amazed at the depths of your heroism.  It simply boggles the mind the lengths you are willing to go to achieve victory over the forces of darkness.\n\nAllow me now to play my small part in this.  I've prepared a special solvent that should allow me to secure the scarab on as the head of the key, infusing it with the power to breach the locked door of Scholomance.\n\nHere goes nothing..." }
WordHunterWoW_QuestEN[5804] = { title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, <name>!", objectives = "Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "You've come this far <name> - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key.  Get Araj's scarab, by hook or by crook, and bring it to me - I will fuse it on as the head of the key.", completion = "Yes, this is it!  I... again, I'm absolutely amazed at the depths of your cunning and bravery.  It simply boggles the mind the lengths you are willing to go in order achieve victory.\n\nAllow me now to play my small part in this.  I've prepared a special solvent that should allow me to secure the scarab on as the head of the key, infusing it with the power to breech the locked door of Scholomance.\n\nThis should take just a moment..." }
WordHunterWoW_QuestEN[5805] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "Bring the Goldshire Gift Voucher to Merissa Stilwell in Goldshire.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, <name>. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" }
WordHunterWoW_QuestEN[5821] = { title = "Bodyguard for Hire", description = "Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!\n\nI'll tell you what {class}, if you protect us past the Kolkar village we'll make it worth your while.\n\nIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.", objectives = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.", completion = "You know, it doesn't seem prosperous to be paying the likes of you to guard Gizelton Caravan. <class>, if I were a bit taller I could take on a second job and sit kodo-side-saddle with the biggest gun my hands could carry... and I'd show them blasted centaur who's their papa." }
WordHunterWoW_QuestEN[5841] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Kharanos Gift Voucher to Yori Crackhelm in Kharanos.", progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, <name>. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" }
WordHunterWoW_QuestEN[5842] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Dolanaar Gift Voucher to Orenthil Whisperwind in Dolanaar." }
WordHunterWoW_QuestEN[5843] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Razor Hill Gift Voucher to Magga in Razor Hill.", progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, <name>. We welcome you to the world of Azeroth, and offer you one of these unique gifts!" }
WordHunterWoW_QuestEN[5844] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Bloodhoof Village Gift Voucher to Vorn Skyseer in Bloodhoof Village." }
WordHunterWoW_QuestEN[5845] = { title = "Of Lost Honor", description = "The Order of the Silver Hand was utterly decimated when Uther was slain.\n\nThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.\n\nWere any of the Order left alive, he thought - and did it matter?\n\nIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.\n\nYou must travel to Northdale and recover that symbol of lost honor.", objectives = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", progress = "My faith will guide you, <name>. The Light knows no bounds.", completion = "It is as glorious now - even in its tattered state - as the day I looked upon it and took my oath of allegiance.\n\nHis redemption comes and perhaps mine with it..." }
WordHunterWoW_QuestEN[5846] = { title = "Of Love and Family", description = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.\n\nIf this painting still exists, you must find it.\n\nTravel to the ruined island of Caer Darrow and see if the painting or the artist remain.", objectives = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.", completion = "How could I forget? Many of the spirits on this island are cursed to relive their last happy memory before they met their tragic end.\n\nI too am cursed, but not as they - I am one of the few that remembers all...\n\nPerhaps this thing that you ask me is why I haunt these ruins. Perhaps this thing I tell you shall set me free." }
WordHunterWoW_QuestEN[5847] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Brill Gift Voucher to Claire Willower in Brill." }
WordHunterWoW_QuestEN[5848] = { title = "Of Love and Family", description = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.\n\nAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.\n\nTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'\n\nMay the Light guide your actions.", objectives = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\n\nReturn the painting to Tirion Fordring.", progress = "The painting, <name>. Do you have the painting?", completion = "<Tirion nearly collapses when he sees the painting.>\n\n<He begins to sob in an almost frenetic manner.>" }
WordHunterWoW_QuestEN[5861] = { title = "Find Myranda", description = "<name>, you have done all that I have asked thus far. Only one step remains in your quest of redemption.\n\nYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.\n\nThere is only one way in which to deliver my message and that is through a guise of deception.\n\nTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.", objectives = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.", progress = "I knew this day would come.", completion = "I was Tirion's most trusted advisor when he held rank as Lord of Mardenholde. I openly dissented the verdict passed by the Order of the Silver Hand and was banished for my insolence.\n\nHe has been through much heart ache and disappointment in his life, <race>. Are you prepared to right the wrongs set upon the Fordrings?" }
WordHunterWoW_QuestEN[5862] = { title = "Scarlet Subterfuge", description = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.\n\nShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.\n\nSpeak to me again when you are ready.", objectives = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\n\nHearthglen is to the north, Taelan should be inside of Mardenholde Keep.", progress = "Are you the reinforcements from Tyr's Hand?", completion = "What is this, soldier?\n\n<Taelan opens the box and begins to examine its contents.>\n\nThis... this cannot be true. But all that you have shown me...\n\n<Taelan falls to one knee, his heartbeat quickens. The fury of ages is about to be loosed upon this town.>" }
WordHunterWoW_QuestEN[5863] = { title = "The Dunemaul Compound", description = "Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins.\n\nThe Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force.\n\nThe leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres.", objectives = "Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", completion = "I'm so glad you were able to do this for me, <name>! Thanks for your help!" }
WordHunterWoW_QuestEN[5881] = { title = "Calling in the Reserves", description = "The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.\n\nI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.", objectives = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.", progress = "You have news from Maggran Earthbinder?", completion = "This is great news; I have been sitting here guarding this hunk of wood for too long. Now I can spend some time with my family... Yippee!" }
WordHunterWoW_QuestEN[5882] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", progress = "Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, <name>! Wherever they are, use the salve I have given you to purify them." }
WordHunterWoW_QuestEN[5883] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make." }
WordHunterWoW_QuestEN[5884] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work <name> - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no <race>!" }
WordHunterWoW_QuestEN[5885] = { title = "Salve via Skinning", description = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", objectives = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, <name>!" }
WordHunterWoW_QuestEN[5886] = { title = "Salve via Disenchanting", description = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser eternal essences will work.\n\nI just need a single lesser eternal essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", objectives = "The power of a disenchanted magical item is felt by the essence it creates. I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!", progress = "The power of a disenchanted magical item is felt by the essence it creates. I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, <name>. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!" }
WordHunterWoW_QuestEN[5887] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", progress = "Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves. Scour Felwood for corrupted plants, <name>! Wherever they are, use the salve I have given you to purify them." }
WordHunterWoW_QuestEN[5888] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve. If you find more vitriol when you mine in Felwood, remember to hold on to it for me! The more of it you find, the more salve I will be able to make." }
WordHunterWoW_QuestEN[5889] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work <name> - every bit of this, once we purify it, will help us take back Felwood. Here, take some doses of Cenarion plant salve and head into the forest. The reclaiming of the land from the corruption waits for no <race>!" }
WordHunterWoW_QuestEN[5890] = { title = "Salve via Skinning", description = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", objectives = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, <name>!" }
WordHunterWoW_QuestEN[5891] = { title = "Salve via Disenchanting", description = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser eternal essences will work.\n\nI just need a single lesser eternal essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", objectives = "The power of a disenchanted magical item is felt by the essence it creates. I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!", progress = "The power of a disenchanted magical item is felt by the essence it creates. I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, <name>. Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were. If you need more salve, then find me here!" }
WordHunterWoW_QuestEN[5892] = { title = "Irondeep Supplies", description = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, <name>.  Enter the mine and bring me a load of them.", objectives = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Do you have the supplies, <name>?  We can never have enough!", completion = "Well done!  I'll put these supplies to good use!  Thanks, <name>!" }
WordHunterWoW_QuestEN[5893] = { title = "Coldtooth Supplies", description = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, <name>!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...", objectives = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Have you been to the Coldtooth mine, <name>?  Do you have the supplies I asked for?", completion = "Ah, you got  them.  Good work, <name>!  These supplies are a little musty from sitting in that dark mine for so long, but we'll make use of them nonetheless.\n\nThank you, <name>.  Your deeds are vital to the maintenance of our fighting forces." }
WordHunterWoW_QuestEN[5901] = { title = "A Plague Upon Thee", description = "So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I'm sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, <name>?\n\nStart by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.", objectives = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.", progress = "Do you have the termites yet, <name>? I am sure it is obvious to a smart <class> like yourself.\n\nOnce we have enough of them, we'll make sure no one can use the lumber mill ever again!", completion = "These will do nicely, <name>. Thank you.\n\nIf you're ready, we can get on with the next step." }
WordHunterWoW_QuestEN[5902] = { title = "A Plague Upon Thee", description = "Now that we have plenty of termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; someplace high, like on a crate or something.\n\nAfter you open it, the rest should take care of itself. Just come back here and I'll reward you for helping me.", objectives = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item:", completion = "The termites are obviously getting restless as you place the barrel on top of the crate." }
WordHunterWoW_QuestEN[5903] = { title = "A Plague Upon Thee", description = "I've tried many times to rout out the Scarlet Crusade through force alone, but to no avail. So, as an alternative, I've decided to make their lives more difficult.\n\nIf you are willing to help, I want to infest that lumber mill with the most terrible species of termites ever found.\n\nIn Plaguewood, near the once-great Stratholme, there is a breed that survived the plague and the Scourge combined. Find their mounds and fill this jar with them, so we can prepare them to be unleashed on the Crusade.", objectives = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", progress = "Did you find the termite mounds, <name>? I've heard they are all over Plaguewood.", completion = "These will do nicely, <name>. Thank you. Just look at them... so many of them all huddled up. I almost feel bad for the Crusade, but then again, it was never their mill to take, now, was it?" }
WordHunterWoW_QuestEN[5904] = { title = "A Plague Upon Thee", description = "Now that we have the termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; find someplace suitable, like on a crate and then open it. The termites should do their work from there and make the mill useless to the Crusade.", objectives = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item:", completion = "The termites are obviously getting restless as you place the barrel on top of the crate." }
WordHunterWoW_QuestEN[5921] = { title = "Moonglade", description = "All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.Upon completion of this quest you will gain:", objectives = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian. Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5922] = { title = "Moonglade", description = "All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.", objectives = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", completion = "\"And so it begins, Father Cenarius. And so it begins.\"\n\nDendrite makes a quick, invisible gesture in the air above him. A slight aura of power falls over him.\n\n\"The first perspective of nature you must adapt to is that of the bear. I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!\"" }
WordHunterWoW_QuestEN[5923] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", objectives = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5924] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", objectives = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5925] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", objectives = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5926] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", objectives = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5927] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", objectives = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5928] = { title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", objectives = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young <class>. The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature. Animals and plants are our friends as well as our charges. We choose to devote our lives as preservers of balance for their sakes as well as our own. Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!" }
WordHunterWoW_QuestEN[5929] = { title = "Great Bear Spirit", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", objectives = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", completion = "Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met. You gaze upon me with strength and knowing intent, though this intent is yet not focused. You will now learn to focus your strength and adopt the nature of the bear into your work.\"" }
WordHunterWoW_QuestEN[5930] = { title = "Great Bear Spirit", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", objectives = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", completion = "Dendrite makes another invisible gesture in the air above him as you approach. Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met. You gaze upon me with strength and knowing intent, though this intent is yet not focused. You will now learn to focus your strength and adopt the nature of the bear into your work.\"" }
WordHunterWoW_QuestEN[5931] = { title = "Back to Darnassus", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.Upon completion of this quest you will gain:", objectives = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me. Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered. Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one. We shall meet again.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5932] = { title = "Back to Thunder Bluff", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.Upon completion of this quest you will gain:", objectives = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me. Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature. Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one. We shall meet again.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[5941] = { title = "Return to Chromie", description = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.\n\nI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!\n\nShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal.", objectives = "Take the Bundle of Relics to Chromie in Andorhal.", progress = "I have been in contact with your friend Carlin.  He feels great pain for the doom of his village, but he speaks very highly of you and knows that you can set things right.\n\nOh, but I'm drifting from the subject at hand... <name>, do you have the relics I asked for?", completion = "Ah yes, there they are.  Together they weave a powerful spell, one that will raise the spirits of Darrowshire.\n\nWith that spell, and with a little luck, we can save Joseph Redpath!" }
WordHunterWoW_QuestEN[5942] = { title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you <name>.  Thank you!  You're a very nice <man/lady>!", objectives = "Bring Joseph's Key to Joseph's Chest.", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens..." }
WordHunterWoW_QuestEN[5943] = { title = "Gizelton Caravan", description = "You look like a capable {race}. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp.", objectives = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.", completion = "Not sure it's a prosperous proposition to be paying so much money to protect the Gizelton Caravan. Cork and Rigger only make one gold piece a week, but as long as they keep paying for my kodos I can care less how they run their business." }
WordHunterWoW_QuestEN[5944] = { title = "In Dreams", description = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.\n\nI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.\n\nI want not to dream anymore.\n\nTake me to him.", objectives = "Escort Taelan Fordring out of Hearthglen.", completion = "The death of my son at the hands of these monsters will not pass without incident. Take solace in knowing that the Order is reborn.\n\nI now take my place as Highlord of the new Order of the Silver Hand.\n\nThese possessions of my past - they are all that I have to offer for all that you have done. Please, take these as a symbol of my gratitude; all have served me well over the years.\n\nMay we meet again, in better times, and reminisce of days long past... battles hard fought... dreams redeemed." }
WordHunterWoW_QuestEN[5961] = { title = "The Champion of the Banshee Queen", description = "It pleases me greatly to see the battle hardened join our cause. Our numbers grow in size and strength as each day passes. Perhaps you are prepared to test your mettle, <class>?\n\nAmong the first of my champions was Nathanos, now known as the Blightcaller. Few exist with more dedication or vigor amidst our ranks.\n\nSeek him out in the Eastern Plaguelands. He resides at the Marris Stead; occasionally roaming the decimated wastes, slaying all Scourge and Alliance filth that cross his path.", objectives = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead.It pleases me greatly to see the battle hardened join our cause. Our numbers grow in size and strength as each day passes. Perhaps you are prepared to test your mettle, <class>?\n\nAmong the first of my champions was Nathanos, now known as the Blightcaller. Few exist with more dedication or vigor amidst our ranks.\n\nSeek him out in the Eastern Plaguelands. He resides at the Marris Stead; occasionally roaming the decimated wastes, slaying all Scourge and Alliance filth that cross his path.", completion = "Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption." }
WordHunterWoW_QuestEN[5981] = { title = "Rampaging Giants", description = "Around 4,000 years ago, Tyrande Whisperwind saved the life of the frostsaber queen, at the hands of rampaging giants. Since then, the frostsabers have been allies of the night elves.\n\nThese same giants that once were a danger to the frostsabers, still exist not too far from here. They are called the frostmaul, and they have taken over the large valley to the south.\n\nProve your loyalty to the frostsabers; kill these giants in the name of the frostsaber queen, Shy-Rotam!", objectives = "Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers.", completion = "Excellent, <name>. Your determination has been duly noted." }
WordHunterWoW_QuestEN[6001] = { title = "Body and Heart", description = "Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Moondust, <name>... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!Upon completion of this quest you will gain:", objectives = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done." }
WordHunterWoW_QuestEN[6002] = { title = "Body and Heart", description = "On land west of Taurajo in the Barrens - just before it turns into Mulgore - lies a Moonkin Stone.  The moonkin are special beasts, not native to these parts.  Lunaclaw, the stone's defender, will face you when Cenarion Lunardust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Lunardust, <name>... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!Upon completion of this quest you will gain:", objectives = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done." }
WordHunterWoW_QuestEN[6004] = { title = "Unfinished Business", description = "I was sent as a scout to do some damage and gauge the strength of Hearthglen's defenses. Some people in the Alliance feel the little town has more than historical importance. It's not my job to question what that importance is, but regardless, I'm in no shape to continue until I rest up.\n\nIf you're willing, I'd pay handsomely for some help. Start south of here at their camp near the small bulwark they've set up. If you prove strong enough, maybe I could get your help with my main goal.", objectives = "Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", completion = "Well done, <name>. I'm amazed you dealt with them so quickly. Thank you.\n\nI have yet to meet anyone that approves of the Scarlet Crusade and their methods. I believe in the Light as much as anyone else in Stormwind, but they've demonstrated that they only want to kill anyone not loyal to their movement... even innocents." }
WordHunterWoW_QuestEN[6021] = { title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from the pit below, then take them back to their evil, dead troll hideout--the Undercroft to the west.\n\nGo there and take out Zaeldarr, <name>.  I'm sick to death of his mischief!", objectives = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", progress = "Did you find the hideout, <name>?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!" }
WordHunterWoW_QuestEN[6022] = { title = "To Kill With Purpose", description = "You kill with purpose while you remain on my stead.\n\nYour first task is to feed my hounds.\n\nTake this mortar and pestle and travel to Corin's Crossing. Once there, you will find a robust selection of Scourge to slaughter. From their fresh carcasses I need living rot. Take that living rot and grind it up in the mortar, then let it sit to coagulate. Bring the coagulated rot back here.\n\nAnd imbecile, realize that living rot from the undead doesn't remain 'living' for very long. You must kill quickly!", objectives = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", progress = "Are you crying? If this is too 'tedious' for you, 'hero,' I recommend that you head back to the Dark Lady and inform her of the horrible mistreatment you received at my farmstead.\n\nNow get out of my sight!", completion = "Disappointing. I was hoping that I'd be feeding you to my hounds, instead.\n\n<Nathanos sighs.>\n\nWell, at least they'll have something to eat." }
WordHunterWoW_QuestEN[6023] = { title = "Unfinished Business", description = "My real mission was to weaken the Scarlet Crusade's outlying forces and then infiltrate Hearthglen to gauge their numbers. I'm still in no shape to do it on my own, so perhaps I could ask you to aid me again, <name>? From what information I gathered before being discovered, the Crusade has two important members that are the backbone of their forces outside the town: Huntsman Radley and Cavalier Durgen. Kill them, and we're making progress. They should be along Hearthglen Pass outside the town proper.", objectives = "Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", completion = "Thank you, <name>. You've been more help than I could have hoped for. The air here just seems to suck my will. I feel tired, and I can tell I'm not getting any better the longer I'm here.\n\nI'm not really sure how I'm going to infiltrate Hearthglen itself and report on how strong the Scarlet Crusade's presence is.\n\nBut that's another matter, before you leave, here, take this... as payment for your help. Thank you again." }
WordHunterWoW_QuestEN[6024] = { title = "Hameya's Plea", description = "Kill me.  Before it's too late.\n\nI am Hameya.  While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed.  We are infected.\n\nI can feel the lich's words now, urging me to reach Zul'Mashar and infect more of my people.  I cannot resist, and so I wrote this scroll before my will left me.\n\nI buried a chest in dirt next to a wagon behind this crypt, but only my key will open it.  I have the key.  If you want my treasure, then find me.\n\nKill me.  Before it's too late.", objectives = "Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", progress = "This chest buried here is securely locked.", completion = "Hameya's chest is opened!!" }
WordHunterWoW_QuestEN[6025] = { title = "Unfinished Business", description = "What? Really? You want to know more? But you've already done so much for me, <name>. I couldn't possibly ask you to enter Hearthglen itself on my behalf.\n\nAre you sure, <name>? Hearthglen is much more dangerous than the Pass--I cannot provide you any protection  or even information about what you might face.\n\nWell, if you really are willing to help, then enter the town and find a high place to gain a good view of the town. From there you can gauge their numbers and report them back to me. But be careful....", objectives = "Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.", completion = "You've done it, <name>! Thank you!\n\nI'll return to Elling... I mean Stormwind as soon as I can. Here, take this coin, it's the least I can do for you. You're a credit to your people, <name>. Thank you and good luck." }
WordHunterWoW_QuestEN[6026] = { title = "That's Asking A Lot", description = "These here Argent Dawn people commissioned ol' Smokey to do a little demolition work for 'em. Smokey's mammy ain't raised no dummy. When gold coin is slapped on the table, Smokey's services are available. That's my motto!\n\nNow I'd be willing to split the commission with you if you're willing to do a little legwork. Here's the deal: I'm going to head over to Plaguewood and mark the buildings we need destroyed. You gather the components for the bombs. Meet back here when you've got everything. Deal?", objectives = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.\n\nYou will have to find a blacksmith and an engineer for these items.", progress = "Trust ol' Smokey, <race>. The reward will be worth it. These Argent Dawn folk don't mess around when it comes to payment.", completion = "I can pay you half up front and half when the job is done." }
WordHunterWoW_QuestEN[6027] = { title = "Book of the Ancients", description = "{name}, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!", objectives = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.", progress = "Ah, <name>!  It's good to see you again.  Do you have the Book of the Ancients?", completion = "The long lost Book of the Ancients!  I will ensure this book is passed on to the high council.  You've done well today, and for that you are to be thanked... as a hero should be thanked!" }
WordHunterWoW_QuestEN[6028] = { title = "The Everlook Report", description = "I am looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Pureheart at Chillwind Camp; it's a ways from here, located along the southern fringe of the Western Plaguelands.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from her!", objectives = "Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands.", progress = "Greetings, <class>.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp.  I might also have some work for you...", completion = "Very resourceful, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks." }
WordHunterWoW_QuestEN[6029] = { title = "The Everlook Report", description = "I'm looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Garush at the Bulwark; it's a ways from here, located along the western fringe of the Western Plaguelands, east of Tirisfal Glades.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from him!", objectives = "Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands.", progress = "Greetings, <class>.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Bulwark.  I might also offer you the chance to fight for a cause that's worth fighting for!", completion = "Resourceful for a human, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks." }
WordHunterWoW_QuestEN[6030] = { title = "Duke Nicholas Zverenhoff", description = "A recluse medium found in these parts by the name of Umbranse has provided the Argent Dawn with quite a literary masterpiece... one that amounts to quite possibly the largest collection of jibber-jabber I've ever seen written.\n\nOne of the Dawn's most respected leaders, Duke Nicholas Zverenhoff, is a brilliant linguist.  Could you take this to him for me - for a reward, of course?  Light's Hope Chapel - that's where he's currently at, far in the eastern part of the Eastern Plaguelands.", objectives = "Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.", progress = "May the Light guide you in these troubling times, <class>.  What brings you here to this beacon of hope in the middle of darkness and despair?", completion = "This... this is a very special book you have brought me.  I'd like to tell you that \"special\" in this case means \"unique and quite possibly illuminating\", but that remains to be seen.\n\n\"Ooooooo?\"  Who in their right mind thinks this up?\n\nWell now, I've heard of this Umbranse that Gregor spoke of, so this isn't without merit.  I'll do my best to decipher it.  As for you... please, have this - courtesy of the Argent Dawn.  While you are here, perhaps there are some other things you can aid us with." }
WordHunterWoW_QuestEN[6031] = { title = "Runecloth", description = "In Timbermaw, we are content.  We do not like strangers.  This is good for us, but it is bad for trade.\n\nNot long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak.  Runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing.\n\nWill you bring me runecloth?  If you bring me enough, then I will give you something in trade.", objectives = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.", progress = "Do you have the runecloth?  My people are eager for more items of runecloth!", completion = "Ah, you brought the cloth.  Such fine material it is!\n\nThank you, <name>.  You are a true friend.  Please accept this in exchange." }
WordHunterWoW_QuestEN[6032] = { title = "Sacred Cloth", description = "Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us.  But mooncloth is sacred.\n\nBring me a small supply of this holy cloth, and I will teach you a secret fashioning technique. ", objectives = "Bring 2 Mooncloth to Meilosh in Timbermaw Hold.", progress = "Have you brought the mooncloth, <name>?", completion = "Ah, very good.  This mooncloth will be used for garments sacred to our people.  Thank you, <name>.  Now I will train you." }
WordHunterWoW_QuestEN[6041] = { title = "When Smokey Sings, I Get Violent", description = "While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished.\n\nHere's the plan: I'm going to give you ten sticks of my special compound. You're going to take them over to Plaguewood and plant them inside the Scourge structures that I've had marked for detonation.\n\n<Smokey snaps his fingers.>\n\nBing! It's just that easy.", objectives = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.\n\nOnce you plant the bomb, leave the building and marvel at your handiwork.\n\nBy the way, Smokey's Special Compound is rather... unstable.", completion = "You're much darker than I remember. You got that look going for you; the look that says, 'I've been charred by a high explosive bomb.'\n\n<Smokey laughs.>\n\nAnyhow! Here's your cut of the loot. I've thrown in a little something extra to help soothe the burns." }
WordHunterWoW_QuestEN[6042] = { title = "Un-Life's Little Annoyances", description = "You cannot take two steps off of this farm without running into one of those obnoxious bats. I want to be able to take the hounds out and slaughter Scourge without being accosted by any damned, dirty bats. Obviously, I have better things to do with my time than mindlessly kill bats day in and day out. You, however, do not.\n\nWhat? Your training? This is your training! Now get out of my sight and don't come back until you've killed a fair number of those winged demons. Don't disappoint me.", objectives = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", completion = "It's incredible what a little anger and rage can get accomplished." }
WordHunterWoW_QuestEN[6061] = { title = "Taming the Beast", description = "As a tauren, it is important to follow the traditions of our ancestors by fighting mighty creatures. By besting these creatures, we are able to intake their spirits, allowing us to become closer to the Earthmother.\n\nIn the same way, taming a beast to fight alongside us helps us become one with nature around us. Eventually, you will learn to tame a beast of your choosing. But all things take practice, and you have much to learn. Begin by taking this taming rod; you must tame an adult plainstrider.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village." }
WordHunterWoW_QuestEN[6062] = { title = "Taming the Beast", description = "It is an admirable skill to command one's authority over nature. As a hunter, you must strive to learn to use the force and power inherent to any creature of your choosing.\n\nGaining control of an animal is not an easy feat; it is a task that you must undertake with much determination.\n\nFor your first assignment, take this taming rod and use it to tame a dire mottled boar. You can find them quite close to Razor Hill. Practice your skills in battle with the boar at your side, then return to me.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill." }
WordHunterWoW_QuestEN[6063] = { title = "Taming the Beast", description = "As a hunter, it is important to remember the responsibility you hold in your hands. Nature is not a power that can be bent to obey our desires; it is one that is to be respected and acknowledged as something stronger than your very existence.\n\n<name>, you must prove your understanding of this before you will gain the ability to tame an animal to be your companion.\n\nYour first task is to take this taming rod. With it, you will be able to tame a webwood lurker. Tame it, and practice your skills as a hunter.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar." }
WordHunterWoW_QuestEN[6064] = { title = "Taming the Beast", description = "Hi there, <lad/lass>! So, you'd be wanting to know how you can gain a pet of your own?\n\nWell, let's get started. There's nothing more important than yer equipment when it comes to hunting, but we can chat about my new Shrapnel Blaster some other time. Fer now, let's focus on something I'm sure you're quite interested in: a pet!\n\nThe best way to learn is for you to try out several creatures as companions and see what ya like. So, find a large crag boar, then use the taming rod to tame it.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos." }
WordHunterWoW_QuestEN[6065] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.Upon completion of this quest you will gain:", objectives = "Speak with Yaw Sharpmane at Bloodhoof Village in Mulgore." }
WordHunterWoW_QuestEN[6066] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", objectives = "Speak with Yaw Sharpmane at Bloodhoof Village in Mulgore.", completion = "Yes, I do believe you are ready..." }
WordHunterWoW_QuestEN[6067] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", objectives = "Speak with Yaw Sharpmane at Bloodhoof Village in Mulgore.", completion = "Yes, I do believe you are ready..." }
WordHunterWoW_QuestEN[6068] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", objectives = "Speak with Thotar at Razor Hill in Durotar.", completion = "Yes, it is time for you to begin your training." }
WordHunterWoW_QuestEN[6069] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", objectives = "Speak with Thotar at Razor Hill in Durotar.", completion = "Yes, it is time for you to begin your training." }
WordHunterWoW_QuestEN[6070] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", objectives = "Speak with Thotar at Razor Hill in Durotar.", completion = "Yes, it is time for you to begin your training." }
WordHunterWoW_QuestEN[6071] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", objectives = "Speak with Dazalar at Dolanaar in Teldrassil.", completion = "Yes, it is time, <class>." }
