WordHunterWoW_QuestEN[6074] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", objectives = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, I do believe you are ready, as well...." }
WordHunterWoW_QuestEN[6075] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", objectives = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, I do believe you are ready, as well...." }
WordHunterWoW_QuestEN[6076] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", objectives = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, I do believe you are ready, as well...." }
WordHunterWoW_QuestEN[6081] = { title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him in the Valley of Honor.\n\nGood luck, <name>.Upon completion of this quest you will gain:", objectives = "Speak with Ormak Grimshot in Orgrimmar.You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him in the Valley of Honor.\n\nGood luck, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6082] = { title = "Taming the Beast", description = "The final creature you need to tame is one you should strive to emulate; the armored scorpid. It strikes quickly and confidently; to control a force such as this is your fate as a hunter.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing; this creature will be yours to command. Under your control, your pet will gain experience alongside you. I will also show you how to call it and dismiss it as you wish.You will learn:", objectives = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill." }
WordHunterWoW_QuestEN[6083] = { title = "Taming the Beast", description = "The advantage a pet affords you against your rivals is duly noted, <name>. When you gain control over another creature, you are adding to your own strength. Your pet must become an extension of yourself.\n\nThe next task requires you to turn from the land; you will find the next creature in the waters off the coast. Across from Sen'jin Village, near the Echo Isles. look for a spirited crab called the surf crawler. Use the taming rod to tame it, then practice your skills.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill." }
WordHunterWoW_QuestEN[6084] = { title = "Taming the Beast", description = "Those crag boars are quite burly; maybe you'd like something with a little more finesse? Alright then, I've got jus' the thing. South and east of here, you'll find large white cats called snow leopards. Just like an elegantly-carved rifle, behind their beautiful exterior lies a powerful fighter, capable of doing extreme damage. You'll find them to be much more agile an' swift than the boar you tamed.\n\nTake this taming rod and see how you like the snow leopard.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos." }
WordHunterWoW_QuestEN[6085] = { title = "Taming the Beast", description = "Perhaps you'd like a creature that possesses little more than brute strength. The ice claw bear is an excellent companion for a fledgling hunter like yourself, and can be found east of Kharanos. Here is the taming rod; try this animal as a pet and see if ya like it!\n\nWhen you return, I'll give ya the skills you will need to tame an animal of your choosing; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as ya like.You will learn:", objectives = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos." }
WordHunterWoW_QuestEN[6086] = { title = "Training the Beast", description = "<name>, ya now have the power to tame a pet, but you must also gain the skills ta train it.\n\nTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', <lad/lass>!\n\nBelia is a friendly sort; you should have no problems gaining her approval. Good luck, <name>.Upon completion of this quest you will gain:", objectives = "Speak with Belia Thundergranite in Ironforge.<name>, ya now have the power to tame a pet, but you must also gain the skills ta train it.\n\nTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', <lad/lass>!\n\nBelia is a friendly sort; you should have no problems gaining her approval. Good luck, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6087] = { title = "Taming the Beast", description = "You have a fiery spirit, hunter, readily awaiting your next challenge.\n\nYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.\n\nDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.\n\nHere is the taming rod, <name>. Tame a prairie stalker and practice your skills.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village." }
WordHunterWoW_QuestEN[6088] = { title = "Taming the Beast", description = "The final task that I have for you requires that you tame a creature that inhabits the sky. The swoop is a difficult opponent, but as your ally, you will acquire its sharp attacks and threatening presence.\n\nBy the will of the Earthmother, when you return I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.You will learn:", objectives = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village." }
WordHunterWoW_QuestEN[6089] = { title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Thunder Bluff. There you must speak to one of our most revered hunters, Holt Thunderhorn. If he deems you worthy, he will give you the ability to train your new pet.\n\nHolt has bested the most powerful and feared beasts of Azeroth, and commands many strong creatures of his own. His ties to the Earthmother are strong, and you can learn much from him. Good luck, <name>.Upon completion of this quest you will gain:", objectives = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff." }
WordHunterWoW_QuestEN[6101] = { title = "Taming the Beast", description = "The variance of nature is something that can be relied upon, <name>. It is predictable in the way that it never remains the same; it is always changing.\n\nThe tasks I give to you will help you to see and appreciate the vast differences of the creatures you may choose as your companion.\n\nTake this taming rod and use it to tame a nightsaber stalker, found to the south. Practice your skills as a hunter. Then you will begin to understand the similarities and differences of nature.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar." }
WordHunterWoW_QuestEN[6102] = { title = "Taming the Beast", description = "You have tamed two creatures that inhabit the land, now you must tame one that soars the skies. Use the taming rod to tame a strigid screecher, found west of here. Practice your skills with this mighty owl at your side.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.You will learn:", objectives = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar." }
WordHunterWoW_QuestEN[6103] = { title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.\n\nWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, <name>.Upon completion of this quest you will gain:", objectives = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.\n\nWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6121] = { title = "Lessons Anew", description = "You're now ready to learn about poison and the power we as druids have over it, <name>.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.Upon completion of this quest you will gain:", objectives = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven." }
WordHunterWoW_QuestEN[6122] = { title = "The Principal Source", description = "The Cliffspring Falls in Darkshore serves as the principal source of drinking water for the region, and now I suspect it is the principal source of the poison that is harming the local fauna - deer specifically.  Use this sampler to draw some water from the mouth of the cave; be careful, as dangerous naga now reside in a cave by the falls.\n\nOnce filled, deliver it to Alanndarian Nightsong in Auberdine.  She is the one that requested our aid, and you will work with her to address this malady.Upon completion of this quest you will gain:", objectives = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore." }
WordHunterWoW_QuestEN[6123] = { title = "Gathering the Cure", description = "The water will serve as the base of the curative salve I'll make for the deer.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if we're unlucky and you aren't one then you'll need to find one to help us out.\n\nFinally for potency, I need some lunar fungus.  Finding lunar fungal blooms is easy enough; they're all over the place in caves just to the east of here.  Moonkin reside in the caves and they're irritable as of late, so be careful.Upon completion of this quest you will gain:", objectives = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve." }
WordHunterWoW_QuestEN[6124] = { title = "Curing the Sick", description = "The amount of salve made out of the reagents you brought me is good enough for ten doses, <name>.  While I work with the village to try and make some more salve, I'd like for you to help us get a head start.  All around Darkshore are sickly deer; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend Auberdine's thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!You will receive:", objectives = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins." }
WordHunterWoW_QuestEN[6125] = { title = "Power over Poison", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Mathrengyl Bearwalker in Darnassus, <name>.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.Upon completion of this quest you will gain:", objectives = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.You've learned what it means to cure poison without the benefit of spiritual aid. Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Mathrengyl Bearwalker in Darnassus, <name>. He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid. We shall speak again.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6126] = { title = "Lessons Anew", description = "You're now ready to learn about poison and the power we as druids have over it, <name>.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.Upon completion of this quest you will gain:", objectives = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven." }
WordHunterWoW_QuestEN[6127] = { title = "The Principal Source", description = "Dreadmist Peak to the northwest of the Crossroads is most likely a primary candidate as to the source of the spread of the poison.  Its airy peaks have pools of water that influence the weather patterns.  I suspect the water is now tainted by the demon-worshipping Burning Blade.\n\nUse this sampler to draw water from the pool at the very top of the peak.  Once filled, deliver it to Tonga Runetotem at the Crossroads.  He is the one that requested our aid, and you will work with him to address this malady.Upon completion of this quest you will gain:", objectives = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens." }
WordHunterWoW_QuestEN[6128] = { title = "Gathering the Cure", description = "The water will serve as the base of the curative salve I shall make for the gazelles.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if you are not familiar with this skill you'll need to find one to help us out.\n\nFinally for potency, I need kodo horns - mere chips and fragments will not suffice.  Kodos you can handle wander the northern part of the Barrens; bring some down for the greater good of the balance <name>, and fetch the horns for me.Upon completion of this quest you will gain:", objectives = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve." }
WordHunterWoW_QuestEN[6129] = { title = "Curing the Sick", description = "I was able to make enough salve for ten doses of curing, <name>.  While I work with local authorities to try and make some more salve, I'd like for you to help us get a head start.  All around the northern Barrens are sickly gazelles; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend our thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!You will receive:", objectives = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads." }
WordHunterWoW_QuestEN[6130] = { title = "Power over Poison", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Turak Runetotem in Thunder Bluff, <name>.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.Upon completion of this quest you will gain:", objectives = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.You've learned what it means to cure poison without the benefit of spiritual aid. Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Turak Runetotem in Thunder Bluff, <name>. He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid. We shall speak again.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6131] = { title = "Timbermaw Ally", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.Upon completion of this quest you will gain:", objectives = "Grazle wants you to prove yourself by killing 5 Deadwood Warriors, 5 Deadwood Pathfinders, and 5 Deadwood Gardeners." }
WordHunterWoW_QuestEN[6132] = { title = "Get Me Out of Here!", description = "Get me out of here!\n\nI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don't want to talk!  I think they want to eat me!\n\nGet me out of here and my brother Hornizz will pay you big!  He's at our camp next to the kodo graveyard, to the east.\n\nLet's hurry, {name}.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...", objectives = "Escort Melizza Brimbuzzle.", completion = "My sister Melizza said you'd be coming.  Thanks a lot for getting her out of the jam she was in; it's too bad that she's already probably found herself in a new one!" }
WordHunterWoW_QuestEN[6133] = { title = "The Ranger Lord's Behest", description = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, <class>: A document detailing my life as a mortal.\n\nBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.\n\nAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering...", objectives = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\n\nYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", progress = "Do not leave me waiting, <class>.", completion = "I trust you did not read the registry. Not even you would do something that idiotic..." }
WordHunterWoW_QuestEN[6134] = { title = "Ghost-o-plasm Round Up", description = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the Magram!  If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs.\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm--that's what we'll sell to the Magram.", objectives = "Collect 8 Ghost-o-plasms.", progress = "Where's my ghost-o-plasm, <name>?", completion = "There it is!  Looks like you got some of it on you too.  Kinda slimey, eh?\n\nWell, thanks a lot for all the trouble, <name>.  This stuff will be worth a fortune... if I can convince the centaurs what it is!" }
WordHunterWoW_QuestEN[6135] = { title = "Duskwing, Oh How I Hate Thee...", description = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.\n\nI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.\n\nThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded.", objectives = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.\n\nIt is said that Duskwing roams the countryside to the north of Marris Stead.", progress = "I would not recommend that you take on this challenge alone, <class>.", completion = "Excellent work, imbecile. I shall fashion this fur into something you can use." }
WordHunterWoW_QuestEN[6136] = { title = "The Corpulent One", description = "Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor. Borelgore has been known to devour others who tried to hunt him.", objectives = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.", completion = "Keep this up and I may have to promote you from imbecile to mental deficient, first class." }
WordHunterWoW_QuestEN[6141] = { title = "Brother Anton", description = "My brother in arms, Brother Anton, heard rumors of an undead infestation in distant Kalimdor, in a land known as Desolace.  Anton immediately booked passage to that place, to seek and destroy the undead menace!\n\nHe is looking for those with the bravery and resolve to aid him.  If your heart is true, then speak with Anton.  He is in Desolace, in the Alliance town of Nijel's Point.", objectives = "Speak with Brother Anton in Desolace.", completion = "I received word of aid arriving from the east.  Are you the source of these rumors?  Have you come here to help the Scarlet Brother in its crusade?\n\nIf so, then listen close..." }
WordHunterWoW_QuestEN[6142] = { title = "Clam Bait", description = "You have the look of a fisherman, <class>! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?\n\nUp north you will find a wrecked ship off the coast. Soft-shelled clams are littered throughout the area. If you bring me back 10 pieces of soft-shelled clam meat, I will give you something in return.", objectives = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.", progress = "I can't wait to go fishing with some fresh soft-shelled clam meat; did you bring me the 10 pieces of it I need?", completion = "Perfect mon, this is just what the witch doctor told me to do for my headache. He says, \"Mai'Lahii - go fish. It'll make you feel better\"\n\nWell, I feel better already, thanks mon!" }
WordHunterWoW_QuestEN[6143] = { title = "Other Fish to Fry", description = "Maybe you heard or maybe you haven't... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.\n\nThe naga attacked us one morning, killing everyone except me.\n\nMe conscience can't handle the guilt, <class>; I need you to go and fry them naga for me. I'll make the effort worth your while; you think you can help me with that?", objectives = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.", completion = "As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.\n\nHere mon, your reward as I promised. It's small in comparison to the gratification of knowing the naga fried for their hated act upon my crew." }
WordHunterWoW_QuestEN[6144] = { title = "The Call to Command", description = "The order has come down, <class>. Bragor Bloodfist himself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to Bragor Bloodfist. Do not embarrass me, <class>!", objectives = "Travel to the Undercity and speak with Bragor Bloodfist.", completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into your lands, desecrate your structures and monuments and murder your people.\n\nThe Dark Lady wishes deal with this insect once and for all and I agree. You will become the instrument of the Horde's reckoning." }
WordHunterWoW_QuestEN[6145] = { title = "The Crimson Courier", description = "Just as the body cannot survive without the head, the head cannot survive without the body. The defenses of the Scarlet Crusade's command inside Stratholme are almost impenetrable. We must, instead, cut the body out from under the head.\n\nMy Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, <race>! Find the Crimson Courier and recover that report. Return it to Nathanos.", objectives = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", progress = "Succeed now and you will have almost earned my respect, <class>.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!" }
WordHunterWoW_QuestEN[6146] = { title = "Nathanos' Ruse", description = "I have made some adjustments to this command. Should our little ruse work, they will expose the Scarlet Oracle and we shall strike!\n\nNow pay attention, <class>. You are to deliver this command to the Crusader Lord, Valdelmar.\n\nHow? You are going to hand it to him, imbecile.\n\nTake the command and this rotten apple to Tyr's Hand. When you cross into the city, eat the apple. You will transform into something more... palatable to the humans. Take the command and hand it to the Crusader Lord, Valdelmar.", objectives = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.", progress = "This is unacceptable, soldier!", completion = "Where have you been? We had thought the Scourge had captured you." }
WordHunterWoW_QuestEN[6147] = { title = "Return to Nathanos", description = "The Grand Crusader makes an unusual request. Hrm, regardless... what he asks will be done. Return to the Scarlet Bastion and notify him that the Oracle will be en route shortly.\n\nWe will take every precaution to ensure that she makes it to Stratholme unharmed.", objectives = "Return to Nathanos Blightcaller with the new information.The Grand Crusader makes an unusual request. Hrm, regardless... what he asks will be done. Return to the Scarlet Bastion and notify him that the Oracle will be en route shortly.\n\nWe will take every precaution to ensure that she makes it to Stratholme unharmed.", completion = "The fools! My deception went unnoticed! Prepare yourself, <class>. We must strike with cold cunning!" }
WordHunterWoW_QuestEN[6148] = { title = "The Scarlet Oracle, Demetria", description = "Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.\n\nWhile this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'\n\nTrack down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, worm.", objectives = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.", completion = "They will be reeling from this blow for years! Well done, <name>! You have earned not only my respect but also this reward." }
WordHunterWoW_QuestEN[6161] = { title = "Claim Rackmore's Treasure!", description = "Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures.  To prevent his treasure from falling into enemy hands, he hid his chest on Ranazjar Isle.\n\nTo open the chest requires two keys, a silver and a gold.  These keys were lost, but if the keys and the chest are found, a treasure awaits!", objectives = "Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest.", progress = "This chest is securely locked.", completion = "Chest opens to reveal Rackmore's treasure!" }
WordHunterWoW_QuestEN[6162] = { title = "Husband's Last Battle", description = "My husband traveled Felwood for the honor of our clan, doing battle against the Shadow Council and other corrupt atrocities!\n\nAfter he escaped death numerous times, I received a letter from him saying that a druid asked him for help against a great befouled furbolg named Overlord Ror--the two were never heard from again.\n\nI want this Ror's clawed hand, <name>. I want it to pay for leaving me a widow! I believe the creature is to the south... near the Ashenvale border.", objectives = "Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.", progress = "Do you have the beast's claw yet, <name>? It will pay for its crimes. I don't care if it's corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!", completion = "You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.\n\nThank you again, <name>." }
WordHunterWoW_QuestEN[6163] = { title = "Ramstein", description = "I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge.\n\nThe wretch. The filth. It hovered above me, entrails hanging from its gaping chest cavity.\n\nI woke as Scourge. For so long I was helpless. My mind had coalesced with the Lich King's.\n\nShe came for me... somewhere, somehow, I knew she would. Free.\n\nAnd now, I must have my vengeance - my vengeance on that which took from me my life. Destroy it.", objectives = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", progress = "After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The monster...", completion = "I wonder... did it beg for mercy? Could it know what mercy is?\n\n<Nathanos spits.>\n\nI will hang this beast's head upon my wall.\n\nYou have earned a spot amongst one of my champions, <name>." }
WordHunterWoW_QuestEN[6164] = { title = "Augustus' Receipt Book", description = "I'm ready for business!  What you do want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", objectives = "Get Augustus' Receipt Book from the inn in Terrordale.", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, <name>!  Stupendous!  Insanely good, I say!" }
WordHunterWoW_QuestEN[6181] = { title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Thor, our gryphon master.  He's just down the hill; bring him my note, and then take a gryphon to Stormwind.", objectives = "Bring Lewis' Note to Thor the gryphon master.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!" }
WordHunterWoW_QuestEN[6182] = { title = "The First and the Last", description = "Nathanos Marris was the first and last of the human ranger lords. A disciple of Sylvanas Windrunner, now the Banshee Queen of the Forsaken.\n\nWe had thought that Nathanos had been killed in action in the defense of Lordaeron five years ago. Although his corpse was never recovered, it was assumed that he did not make it out of the Eastern Plaguelands.\n\nMathias Shaw has been investigating the disappearance and may have some new information. Report to him at once. He resides in Old Town, at the Barracks.", objectives = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.", completion = "After some reports of unusual Forsaken activity in the Eastern Plaguelands, SI:7 agents were dispatched to investigate. The results of that investigation are unsettling." }
WordHunterWoW_QuestEN[6183] = { title = "Honor the Dead", description = "Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.\n\nWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos,\" and \"Blightcaller.\"\n\nI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?", objectives = "Speak with Mathias Shaw again if you wish to accept his task.Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.\n\nWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos,\" and \"Blightcaller.\"\n\nI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?", completion = "<Mathias nods.>\n\nI had faith that Wrynn would send me men and women of honor - the most dedicated soldiers of the Alliance." }
WordHunterWoW_QuestEN[6184] = { title = "Flint Shadowmore", description = "The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.\n\nFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.\n\nGood luck, <name>.", objectives = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.\n\nFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.\n\nGood luck, <name>.", completion = "The first mission will be straight up, <name>. You go in, you come out. Recon..." }
WordHunterWoW_QuestEN[6185] = { title = "The Eastern Plagues", description = "As I said, your first mission is one of reconnaissance. Nothing fancy, <name>. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.\n\nBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.\n\n<Flint swallows hard.>\n\nAll SI:7 agents carry this insignia.\n\n<Flint shows you his SI:7 insignia.>\n\nBring any of those that you may find back to me.", objectives = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", progress = "An... Any luck??", completion = "Rutger. Fredo. Turyen. All... dead...\n\n<Flint clutches the insignias tightly.>\n\nWhere were they? Did you discover any more information about this monster, the Blightcaller?" }
WordHunterWoW_QuestEN[6186] = { title = "The Blightcaller Cometh", description = "<The blood appears to have completely drained from Flint's face.>\n\nNa... Nathanos did this? Nathanos is the Blightcaller?\n\nWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?\n\nI... I am sorry to ask this of you, <name>, but King Wrynn must be informed of this turn of events at once. Please, return to Stormwind and deliver the news.", objectives = "Return to Stormwind and inform King Varian Wrynn of the fate of Nathanos Marris.<The blood appears to have completely drained from Flint's face.>\n\nNa... Nathanos did this? Nathanos is the Blightcaller?\n\nWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?\n\nI... I am sorry to ask this of you, <name>, but King Wrynn must be informed of this turn of events at once. Please, return to Stormwind and deliver the news.", completion = "An agent of the Forsaken? The champion of the Banshee Queen?\n\n<King Varian Wrynn grimaces.>\n\nRidiculous..." }
WordHunterWoW_QuestEN[6187] = { title = "Order Must Be Restored", description = "Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?\n\nNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.\n\nAnd now... the champion of the Forsaken.\n\nNo. This cannot be. Order must be restored.\n\nGather an army, <name>. Return to the Plagues with your army and destroy the Blightcaller.\n\nI wish you luck, <name>. Truly, you will need it for this battle.", objectives = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, <name>. The Horde will defend the ranger lord with their very lives.", completion = "It is a tragedy. I think... I believe that our kind is cursed, <name>. We are cursed to lose our greatest warriors; our most noble heroes; our most gifted scholars.\n\nWe are indebted to you and I assure you, <name>, wherever Nathanos Marris is now, he smiles down upon you." }
WordHunterWoW_QuestEN[6221] = { title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  For this reason, I am deeply saddened by having to fight my own brethren.\n\nPlease, <name>, do what must be done, and do not mention the details; they upset me far too much.Upon completion of this quest you will gain:", objectives = "Nafien would like you to kill 5 Deadwood Den Watchers, 5 Deadwood Avengers, and 5 Deadwood Shamans." }
WordHunterWoW_QuestEN[6241] = { title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, <name>. While we do allow safe passage to those that have proven they can be trusted, we try to avoid other furbolg tribes if at all possible.\n\nLately I have noticed that the Winterfall tribe has become increasingly hostile towards us. They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nIf you could reduce their numbers this would help us greatly, <name>.Upon completion of this quest you will gain:", objectives = "Salfa wants you to kill 6 Winterfall Totemics, 6 Winterfall Den Watchers, and 6 Winterfall Pathfinders." }
WordHunterWoW_QuestEN[6261] = { title = "Dungar Longdrink", description = "<name>, I gathered into this crate everything Lewis asked for.  Can you take it to him?\n\nIf you've already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don't want our fighting men and women in Westfall to go without fresh equipment!", objectives = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Westfall, eh?  Have you been to Westfall before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!" }
WordHunterWoW_QuestEN[6281] = { title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", objectives = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Quartermaster Lewis?  I'm not surprised he needs more gear.  Sentinel Hill is far away, in a land Stormwind has all but forgotten.\n\nWell thank you, <name>.  Here's some money to cover your travel costs." }
WordHunterWoW_QuestEN[6282] = { title = "Harpies Threaten", description = "Tauren take pride as the protector of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.\n\nThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.\n\nI need you to cull the harpies, <name>!", objectives = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", completion = "This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!" }
WordHunterWoW_QuestEN[6283] = { title = "Bloodfury Bloodline", description = "Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!\n\nShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.\n\nGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.", objectives = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.", progress = "Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.\n\nThe bloodfuries will be helpless with out... surely we can vanquish them forever!", completion = "Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all tauren should.\n\nPlease accept this as a reward for your troubles." }
WordHunterWoW_QuestEN[6284] = { title = "Arachnophobia", description = "Warning: Proceed into Sishir Canyon west of here at your own risk.\n\nBesseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair.\n\nMaggran Earthbinder in Sun Rock Retreat has placed a bounty on Besseleth. Slay her and bring proof of your killing to Maggran; there you will receive your reward for disposing this eight-legged menace.", objectives = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.", progress = "Besseleth is a ruthless predator... I fear for those that travel Webwinder Path at night. It's then that she and her children prey upon innocent travelers. I myself fell prey to her two-foot fang of death, but luckily I was able to fend her off and get to safety. I would give anything to see that monster destroyed.", completion = "Good hunting, <name>! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.\n\n\n\nPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark." }
WordHunterWoW_QuestEN[6285] = { title = "Return to Lewis", description = "The gryphon master in Westfall is Thor.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Thor, so just speak with me again when you're ready to take a gryphon to Westfall.  Once there, you can deliver Osric's Crate to Quartermaster Lewis.", objectives = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, <name>.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Sentinel Hill often!" }
WordHunterWoW_QuestEN[6301] = { title = "Cycle of Rebirth", description = "Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.\n\n<name>, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water's edge.\n\nOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.", objectives = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.", progress = "The continuous destruction caused by war and those that seek a profit from lumber pains me deeply. To aid the cycle of rebirth and replenish the lands, I need Gaea seeds. Do you have them, <class>?", completion = "Ah, <name>, you have the Gaea seeds. Watch and see how the blessing of the Earthmother can cause even these small kernels of life to bloom and flourish." }
WordHunterWoW_QuestEN[6321] = { title = "Supplying Brill", description = "Executor Zygand asked me to take stock of our equipment here in Brill.  With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need.\n\nI found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field.\n\nHere is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity.  Take the order to Bat Handler Anette and speak with her about transport to the Undercity.", objectives = "Bring Morris's Order to Bat Handler Anette.", progress = "You appear to be on official business...", completion = "Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for Brill must not be left under stocked." }
WordHunterWoW_QuestEN[6322] = { title = "Michael Garrett", description = "I have placed Brill's supplies into this crate.  If you have already visited Brill and spoken with their bat master, then you may ride a bat back to her.\n\nSpeak with the Undercity's bat master, Michael Garrett.  He can provide you with a bat to Brill.", objectives = "Bring Gordon's Crate to Michael Garrett.", progress = "If you must travel a long distance, then a bat is your best option.", completion = "This crate must reach Brill quickly?  That is easily done; our bats fly there daily." }
WordHunterWoW_QuestEN[6323] = { title = "Ride to the Undercity", description = "One of my bats can take you to the Undercity.  Normally these flights require a small fee, but the flight to Undercity is complimentary for a handsome {race} like you.  Speak with me again when you are ready so that we may arrange your transport.\n\nYou will find Gordon Wendham in the Trade Quarter of the Undercity.  That is the same quarter where my bat will land.", objectives = "Request a bat ride to the Undercity from the bat master Bat Handler Anette, then take Morris's Order to Gordon Wendham in the Undercity.", progress = "I keep my weapons in top condition.  They are cleaned and ready for use.", completion = "An order from Brill?  Very well.  It is an honor to serve those who serve our Dark Lady." }
WordHunterWoW_QuestEN[6324] = { title = "Return to Morris", description = "The bat master in Brill is Bat Handler Anette.  If you have already met her, then I can give you a bat to fly back to her.\n\nOur bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master.\n\nYou have met Anette in Brill, so you may now fly bats there.  Speak with me again when you are ready.", objectives = "Buy a bat ride to Brill from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Morris in Brill.", progress = "<name>, you return.  Do you have our supplies from the Undercity?", completion = "Good work, <name>.  These weapons will ensure our Deathguards don't get caught unprepared.\n\nYou have done a valuable service for our Dark Lady." }
WordHunterWoW_QuestEN[6341] = { title = "To Darnassus", description = "Everyone in Dolanaar is so proud of Sister Aquinne. I'm certain she'll be pleased to receive this thoughtful gift from Nyoma.\n\nWhen you're ready to travel to Darnassus, just speak to me again and for a few coins, you can hire a hippogryph to take you there. I'm told Sister Aquinne enjoys the solitude of a small plaza just south of the hippogryph master in Darnassus. Look for her there after you arrive.", objectives = "Speak to Fidelio to purchase a flight to Darnassus, then bring the Dolanaar Recipe Book to Sister Aquinne in Darnassus.", progress = "How may I help you?", completion = "Something for me? I wonder who sent it..." }
WordHunterWoW_QuestEN[6342] = { title = "An Unexpected Gift", description = "This is wonderful! It's just the kind of thing I need to remind me of home while I continue my studies in the Temple of the Moon. I'll try out one of the recipes tonight. I can't wait!\n\nWould you take this short note of thanks back to Nyoma? You can hire a hippogryph to take you back to Dolanaar. Just visit our hippogryph master, Leora, when you're ready to leave. She'll help you get a ride back to Dolanaar.", objectives = "Bring Sister Aquinne's Note to Leora, the hippogryph master in Darnassus.", progress = "Are you ready to return to Dolanaar?", completion = "Do you need a ride back to Dolanaar?" }
WordHunterWoW_QuestEN[6343] = { title = "Return to Nyoma", description = "It will be easy to get you a flight back to Dolanaar. Since you already know Fidelio in Dolanaar, you'll be able to fly back there without any problems.\n\nWhenever you arrive in a new town, you should remember to speak to the flight master so that you can fly to and from the new location.\n\nSpeak with me when you're ready to hire a hippogryph to return to Dolanaar.", objectives = "Speak to Leora to hire a hippogryph to take you back to Dolanaar. Once you've arrived in Dolanaar, take Sister Aquinne's Note to Nyoma.", progress = "<name>, you're back from Darnassus?", completion = "It sounds like she loved it. Thank you for bringing the book to Sister Aquinne, <name>. One of these days, I intend to take her up on her invitation to visit her in Darnassus." }
WordHunterWoW_QuestEN[6344] = { title = "Reminders of Home", description = "A friend of mine, Sister Aquinne, is training to be a priestess of the moon in Darnassus.  She left Dolanaar to study in the temple last year. Her letters say she is doing well and learning much, but she misses home and her old friends. I've put together a book of her favorite recipes from Dolanaar.\n\nIf you have time, would you take them to her in Darnassus? You can rent a hippogryph from Fidelio. He's in the center of town, just across from the inn.", objectives = "Bring the Dolanaar Recipe Book to Fidelio in Dolanaar.", progress = "How can I help you?", completion = "That's very thoughtful of Nyoma. For a few coins, I can arrange quick transportation to the capital by hippogryph." }
WordHunterWoW_QuestEN[6361] = { title = "A Bundle of Hides", description = "I have a bundle of hides from the animals of Mulgore, and must get them to Thunder Bluff.  A colleague there, Ahanu, will use the hides to create leather goods.\n\nWill you take the hides to him for me?\n\nThe quickest way to Thunder Bluff is on the back of a wind rider.  Bring the bundle of hides to Tak, our wind rider master in Bloodhoof Village, and speak to him about transport to Thunder Bluff.", objectives = "Bring the Bundle of Hides to the wind rider master Tak in Bloodhoof Village.", progress = "Are you here for a wind rider?  You have something to transport?", completion = "If you must take these hides to Thunder Bluff, then you have come to the right place." }
WordHunterWoW_QuestEN[6362] = { title = "Ride to Thunder Bluff", description = "For a small fee, I will give you a wind rider to Thunder Bluff.  There's no faster way to the city!\n\nIf that is acceptable, speak to me again when you are ready to go.\n\nIf you're taking those hides to Ahanu, then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff.  And that's right where you'll land!", objectives = "Buy a wind rider to Thunder Bluff from the wind rider master Tak, then bring the Bundle of Hides to Ahanu in Thunder Bluff.", progress = "There is dust on your shoulders that must be from Mulgore.  You have spoken with my friend Varg?", completion = "Ah, a new bundle of hides.  I will get to work on these immediately!\n\nThank you, brother.  You have done me a great service.  Here are some coins to pay for your time and travel costs." }
WordHunterWoW_QuestEN[6363] = { title = "Tal the Wind Rider Master", description = "I have prepared leather goods for Varg to sell at the Bloodhoof Village.  Will you bring them to him?\n\nIf you have already been to Bloodhoof Village and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him.\n\nTake the leather goods to Tal, our wind rider master in Thunder Bluff, and speak with him to arrange transport to Bloodhoof Village.", objectives = "Bring Ahanu's Leather Goods to Tal in Thunder Bluff.", progress = "Greetings, <class>.  What can I do for you?", completion = "You need to take this to Bloodhoof Village, eh?  That's not a problem.  If you've already been there and spoken to Tak, then you can take one of my wind riders back to him." }
WordHunterWoW_QuestEN[6364] = { title = "Return to Varg", description = "In order to fly to a town, you must have already been there and spoken with the wind rider master of that town.  You have been to the Bloodhoof Village and spoken to their wind rider master Tak, so for a small fee you can take a wind rider to him from here.\n\nSpeak with me again when you are ready.  Once at Bloodhoof Village, you can then deliver the leather goods to Varg Windwhisper.", objectives = "Buy a wind rider to Bloodhoof Village from the wind rider master Tal, then bring Ahanu's Leather Goods to Varg Windwhisper.", progress = "<name>, you are back from Thunder Bluff?  Did you deliver the hides to Ahanu?", completion = "Ahanu sent me finished products?  Very good.  There are many hunters and adventurers in Bloodhoof Village now and business is lively.  I am sure I'll sell these goods very soon.\n\nThank you for all your efforts, <name>.  I am in your debt." }
WordHunterWoW_QuestEN[6365] = { title = "Meats to Orgrimmar", description = "I have some choice cuts of meat that I want to send to a friend.  Her name is Gryshka, the innkeeper in Orgrimmar.  Will you deliver the meat for me?\n\nThe fastest way to Orgrimmar is on a wind rider.  Take the meats to the Razor Hill wind rider master, Burok, and speak with him about transport to Orgrimmar.", objectives = "Bring Grimtak's Meats to Burok in Razor Hill.", progress = "You need to get somewhere fast?  Then you're talking to the right orc!", completion = "You have to get this meat to Orgrimmar?  That is no problem.  For a small fee, my wind rider can take you there." }
WordHunterWoW_QuestEN[6381] = { title = "New Life", description = "As you have seen, <class>, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale. Beware, for harpies and angry fire elementals still plague the scarred land.\n\n<name>, take these enchanted Gaea seeds and plant them in fertile mounds of soil. The cycle of life must go on!", objectives = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.", progress = "These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.\n\nHave you planted all of the Gaea seeds?", completion = "This is great victory for the land. In time, other things will come to pass: the Venture Co. will pack up their buzz saws and axes, the angry fire spirits will calm, and the harpies will be pushed out by the land.\n\nOnly then <name>, will Stonetalon be truly at peace.\n\nYou have done well <class>; take one of these items as thanks for the new life you have created here today." }
WordHunterWoW_QuestEN[6382] = { title = "The Ashenvale Hunt", description = "Your strength impresses me, <class>.  Your willingness to embrace the hunt gives me confidence that you could move on to bigger game... and bigger challenges.\n\nThe forests of Ashenvale represent a vast untamed wild that the Horde seeks to impose its own will upon, both politically and spiritually.  If you seek to prove yourself in an unproven land, seek the guidance of Senani Thunderheart in Splintertree Post.  The outpost is due north of the path leading from the Barrens.", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.Your strength impresses me, <class>. Your willingness to embrace the hunt gives me confidence that you could move on to bigger game... and bigger challenges.\n\nThe forests of Ashenvale represent a vast untamed wild that the Horde seeks to impose its own will upon, both politically and spiritually. If you seek to prove yourself in an unproven land, seek the guidance of Senani Thunderheart in Splintertree Post. The outpost is due north of the path leading from the Barrens.", completion = "Welcome to the new frontier, <name>.  Ashenvale is a land of opportunity, one where a young <class> like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know." }
WordHunterWoW_QuestEN[6383] = { title = "The Ashenvale Hunt", description = "", objectives = "There are three legendary creatures that make up the Ashenvale Hunt; you may seek them and test yourself against their cunning and might.  In the process, you will hopefully learn something about yourself.  The creatures are: the bear Ursangous, the nightsaber cat Shadumbra, and the hippogryph Sharptalon.\n\nThe creatures of the Ashenvale Hunt are powerful, and you may find that you'll need aid in bringing them down.  If you should best them, bring me proof of your deed." }
WordHunterWoW_QuestEN[6384] = { title = "Ride to Orgrimmar", description = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Grimtak's meats to Gryshka.  Her inn is in the Valley of Strength.\n\nSpeak with me again when you are ready for the journey.", objectives = "Buy a wind rider to Orgrimmar from the wind rider master Burok, then bring Grimtak's Meats to Gryshka in Orgrimmar.", progress = "Something smells good!  You don't have raw meat on you, do you?", completion = "Oh, wonderful!  Those are fine cuts!  These are from Grimtak, are they?  That orc sure knows his way into a lady's heart...\n\nOh, I can't wait to cook it.  But not too much!  Meat is best served rare, don't you think?" }
WordHunterWoW_QuestEN[6385] = { title = "Doras the Wind Rider Master", description = "I've written a letter of thanks to Grimtak.  Will you deliver it for me?  If you've already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.", objectives = "Bring Gryshka's Letter to Doras in Orgrimmar.", progress = "Do you need one of my wind riders?", completion = "You have to get this to Razor Hill in Durotar?  Yes, I can get you there..." }
WordHunterWoW_QuestEN[6386] = { title = "Return to Razor Hill", description = "My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.\n\nYou have been to Razor Hill and spoken to their wind rider master Burok, so now you can fly directly to him from here.  Once you're at Razor Hill, you can deliver Gryshka's letter to Grimtak.\n\nSpeak with me when you are ready to go.", objectives = "Buy a wind rider to Razor Hill from the wind rider master Doras, then bring Gryshka's Letter to Grimtak at Razor Hill.", progress = "Have you returned from Orgrimmar?  Did Gryshka like the meat I sent her?", completion = "Hah!  I guess she liked it!  Nothing brings red to a lady's cheeks like a big, juicy steak!\n\nThank you, <name>.  You've done me a great service.  Here is some money for your trouble, and don't be surprised if I invite you to my wedding!" }
WordHunterWoW_QuestEN[6387] = { title = "Honor Students", description = "I see a lot of young dwarves at my door, eager to learn the trade of cooking.  And if there's one thing a cook needs more than anything, it's a cleaver!\n\nI have a list of students who scored high in their lessons and earned an honorary cleaver.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the cleavers ready.\n\nThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard, and speak with him about transport to Ironforge.", objectives = "Bring Gremlock's List to Brolan Galebeard in Kharanos.", progress = "Have you had your fill of Kharanos so soon?  Are you ready to leave for another city?", completion = "You have to get this to Ironforge, eh?  For a small fee I can put you on the back of one of my gryphons, and it'll take you there.  How does that sound?" }
WordHunterWoW_QuestEN[6388] = { title = "Gryth Thurden", description = "Here are the honorary cleavers for Gremlock's students.  If you've already been to Kharanos, then you should fly a gryphon back there!\n\nTake the cleavers to our gryphon master, Gryth Thurden, and speak with him about a ride back to Kharanos.", objectives = "Bring the Honorary Cleavers to Gryth Thurden in Ironforge.", progress = "You look like you have somewhere to go.  Need one of my gryphons?", completion = "You have to get these to Kharanos, eh?  That won't be a problem.  As long as you've already been to Kharanos and spoken to Brolan Galebeard, then you can take one of my gryphons back to him." }
WordHunterWoW_QuestEN[6389] = { title = "A Plague Upon Thee", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", objectives = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", progress = "Have you done it, <name>? Have you released the termites? The Light help us if the Scarlet Crusade were able to hold onto both the mill and Hearthglen. They should have neither. They're just capitalizing on the victims of the last war and should be put down like rabid animals!", completion = "Haha! Thank you, <name>! You've done it! My father's spirit can now rest and I can live in peace.\n\nThank you again. If there is anything I can do for you, please, just ask." }
WordHunterWoW_QuestEN[6390] = { title = "A Plague Upon Thee", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", objectives = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades.", progress = "Have you done it, <name>? Have you released the termites in the lumber mill?\n\nIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!", completion = "Thank you, <name>. Here, take this coin. I'm sorry it's not more, but try to take some joy in helping destroy the Scarlet Crusade's efforts!" }
WordHunterWoW_QuestEN[6391] = { title = "Ride to Ironforge", description = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Gremlock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!\n\nSpeak to me again when you're ready for the journey.", objectives = "Buy a gryphon to Ironforge from the gryphon master Brolan Galebeard, then bring Gremlock's List to Golnir Bouldertoe in Ironforge.", progress = "What can I do for you, sir?", completion = "Ah, the latest list of Gremlock's best pupils.  I have a batch of honorary cleavers ready to go.  I just need to engrave the names of the students..." }
WordHunterWoW_QuestEN[6392] = { title = "Return to Gremlock", description = "For a small fee you can buy a gryphon ride to Kharanos... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.\n\nYou've already been to Brolan, the gryphon master of Kharanos, so now you can return to him.  And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor.\n\nSpeak with me when you're ready to go.", objectives = "Buy a gryphon to Kharanos from the gryphon master Gryth Thurden, then bring the Honorary Cleavers to Gremlock Pilsnor in Kharanos.", progress = "Ah, <name>.  Have you returned from Ironforge?", completion = "You brought the cleavers.  Great!  I'll get these to my students.  I'm sure they're eager to use them on some fresh boar meat.\n\nThank you for your help, <name>.  I am in your debt, but I hope this money will at least cover your travel costs." }
WordHunterWoW_QuestEN[6393] = { title = "Elemental War", description = "The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.\n\n<name>, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.", objectives = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.", progress = "The Tribunal of the Tides grows impatient. They seek to end this war that has raged across all dimensions for eons. My brethren are anxious to hear news of the glorious victory over the hated fire elementals. Have you the Incendrites that I require?", completion = "The water spirits within me bubble with the excitement. <name>, you have given me a glorious victory to report to the Tribunal of the Tides." }
WordHunterWoW_QuestEN[6394] = { title = "Thazz'ril's Pick", description = "<name>, you are a dependable <race>.  Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind.  When I later returned to retrieve it I found the cave was filled with vicious beasts!  Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls.  My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", objectives = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", progress = "Have you entered the Burning Blade Coven, <name>?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, <name>.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!" }
WordHunterWoW_QuestEN[6395] = { title = "Marla's Last Wish", description = "My friend Marla Fipps lived with her husband Samuel before the plague, but when the plague came Samuel succumbed and joined the Scourge's ranks.\n\nMarla was spared an undeath only to die at the hands of her now mindless husband.  So strong was her love, however, that her last dying wish was to be buried with her beloved Samuel.\n\nSamuel Fipps roams at a ruined camp along the road northeast of Deathknell.  Defeat him and grant Marla's wish: bury him at her grave, in the first row of our graveyard.", objectives = "Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.", completion = "You have done a good deed today, <name>.  Although our struggle against the Scourge continues, let us hope that Marla and Samuel will find peace together in their final resting place." }
WordHunterWoW_QuestEN[6401] = { title = "Kaya's Alive", description = "Tell Tammra Windfield, Kaya's aunt who's at Sun Rock Retreat, about the good news! Kaya is alive! We had thought she was lost after the brutal attack on our village. Follow the path to the west to get to Sun Rock Retreat.", objectives = "Tell Tammra Windfield in Sun Rock Retreat the good news.Tell Tammra Windfield, Kaya's aunt who's at Sun Rock Retreat, about the good news! Kaya is alive! We had thought she was lost after the brutal attack on our village. Follow the path to the west to get to Sun Rock Retreat.", completion = "My goodness, my niece Kaya is alive! That is good news indeed. Thank you, <name>." }
WordHunterWoW_QuestEN[6402] = { title = "Stormwind Rendezvous", description = "You are to meet with Windsor at the gates of Stormwind.\n\nWhat Windsor is about to unveil will shake the very foundation of the kingdom!\n\nDo not attempt to venture there alone, <name>. You must amass an army! Gather your compatriots. To arms!Upon completion of this quest you will gain:", objectives = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.You are to meet with Windsor at the gates of Stormwind.\n\nWhat Windsor is about to unveil will shake the very foundation of the kingdom!\n\nDo not attempt to venture there alone, <name>. You must amass an army! Gather your compatriots. To arms!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6403] = { title = "The Great Masquerade", description = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\n\nAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.\n\nWorry not, for together, we shall be victorious!\n\nAre you ready?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Follow Reginald Windsor through Stormwind. Protect him from harm!" }
WordHunterWoW_QuestEN[6421] = { title = "Boulderslide Ravine", description = "Something is amiss here in Stonetalon. Can you feel the tension in the air, <name>?\n\nSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what's happening in that cave.  I also need you to investigate the depth of that cave.\n\nGo young <class>, it's imperative I know what evil lurks under these mountains.", objectives = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.", progress = "What news have you discovered from Boulderslide Ravine? I recall some legend that deals with Resonite... I just cannot place my hoof on it. Perhaps knowing what lies at the bottom of the cave will illuminate their devious intentions.", completion = "Ah... Yes! That's it; the Resonite crystals have a trace of Earthen magic. The kobolds must have dug deep uncovering an Earthen.\n\nLegend states that the Earthen are creatures created by the Titans.  They were used to create the land our feet walk on. This most definitely is a threat that cannot be ignored.\n\n<Mor'rogal shakes his head.>\n\nPerhaps I can enchant these ore samples to use against this kobold plot." }
WordHunterWoW_QuestEN[6441] = { title = "Satyr Horns", description = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your time.", objectives = "Collect 16 Satyr Horns for Pixel in Splintertree Post.", progress = "I hope you can be quick about getting those horns, <name>. I'm heading back to Ratchet soon!", completion = "These are perfect, <name>! Thanks for helping me out!\n\nOh, and this is for your time..." }
WordHunterWoW_QuestEN[6442] = { title = "Naga at the Zoram Strand", description = "There is evil lurking here along the coast, {race}.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!", objectives = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.", progress = "The naga increase in numbers, <name>. Please complete this task for me.", completion = "We could use more of your kind around here, <name>. Thank you for your help." }
WordHunterWoW_QuestEN[6461] = { title = "Blood Feeders", description = "We Trolls here at Malaka'Jin have prospered from the land; Stonetalon Mountain offers great hunting for us to live on.\n\nLately, we have attracted the wrong dinner guests... the spiders in these mountains have been raiding our camps at night looking to steal our hunt.\n\nIf you were to help us kill off these ghastly beasts we at Malaka'Jin would be in your debt. Spiders are everywhere in Stonetalon - just head north from here and you will see what I am talking about.", objectives = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.", completion = "Sweet, mon! Good news, perhaps we will have fewer unwanted dinner guests tonight.\n\nMany thanks, <name>.  We are forever in your debt." }
WordHunterWoW_QuestEN[6462] = { title = "Troll Charm", description = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\n{name}, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.", objectives = "Bring 8 Troll Charms to Mitsuwa at Hellscream's Watch.", progress = "Did you find the charms, <name>?  Every moment the furbolgs possess those sacred items, my blood boils with rage!", completion = "You found them!  Thank you!  Thank you, <name>!  You do not know how great a thing you have done for me.\n\nA troll without his charm is like an orc without his battle scars...\n\nWorthless." }
WordHunterWoW_QuestEN[6481] = { title = "Earthen Arise", description = "You have uncovered a dark threat to the land, <class>. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc.\n\nI have changed the mixture of the Resonite crystals that you gathered with my shamanistic powers. Take the enchanted Resonite crystal and smash open the Resonite cask, which houses the Earthen.\n\nWhen awakened, Goggeroc will be weakened... Slay him, <name>!", objectives = "Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.", progress = "I fear if we do not dispose of this threat immediately, all of Stonetalon will be lost. The might of an Earthen can not be matched by any means. When awakened, Goggeroc will be weak from his long slumber, this will be the opportunity that you must take advantage of... go now <name>!", completion = "You bear good news, <class>! I fear the possibilities of what an Earthen would mean to Kalimdor.\n\nSlaying Goggeroc was a task for no one less than a hero. You have done well; all of Stonetalon and Kalimdor are indebted to you, noble <class>.\n\nAccept this as your reward most honored one." }
WordHunterWoW_QuestEN[6482] = { title = "Freedom to Ruul", description = "Eh?  Who are you?\n\n{name}?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\n{name}! I must escape!", objectives = "Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.", completion = "You found my brother!  He was captured by the Thistlefurs?  That is terrible news to hear, for although many Furbolgs are noble creatures, the Thistlefurs are corrupt.\n\nThank you for rescuing my brother, <name>.  I do not want to think of how they treated poor Ruul.  He will likely sleep long after this ordeal..." }
WordHunterWoW_QuestEN[6501] = { title = "The Dragon's Eye", description = "A fragment of the shattered medallion is all that I can offer.\n\nYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, <name>.\n\nWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck.Upon completion of this quest you will gain:", objectives = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." }
WordHunterWoW_QuestEN[6502] = { title = "Drakefire Amulet", description = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.\n\nIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?\n\nReturn with his blood, <race>, and I shall enchant the fragment into something that will grant you access to Onyxia's lair.You will receive:", objectives = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire." }
WordHunterWoW_QuestEN[6503] = { title = "Ashenvale Outrunners", description = "Blasted elves! Dey knew right where to hit us!\n\nIt was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens!\n\nNever too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!", objectives = "Kill 9 Ashenvale Outrunners.", completion = "Good, good!\n\nThe fewer 'a dem elves runnin' around, the better." }
WordHunterWoW_QuestEN[6504] = { title = "The Lost Pages", description = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?", objectives = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.", progress = "I hope you find the pages soon, <name>! I really need to get back to work!", completion = "Reading isn't my strong point... but now I'll be able to get back to work! Thanks, <name>!" }
WordHunterWoW_QuestEN[6521] = { title = "An Unholy Alliance", description = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, <name>. Return to me after the deed is done.", objectives = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", progress = "Have you found the Ambassador, <name>? Is he dead?\n\nWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.\n\nThe only optimistic sign from the events you've told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.", completion = "Good. Well done, <class>.\n\nNow that Malcin is dead, we can at least know that the Scourges advances will be halted. I thank you for your efforts and wishes to reward you with a gift.\n\nAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough." }
WordHunterWoW_QuestEN[6522] = { title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", objectives = "Take the Small Scroll to Bragor Bloodfist at the Royal Quarter in the Undercity.", progress = "What business is it you wish to speak of, <name>? You must feel it is important if you continue to pester me.", completion = "I recognize the insignia on this scroll, <name>. You found this on that crone who reigns over Razorfen Kraul? Interesting.\n\nThe Scourge aren't content with one continent it seems. This Ambassador Malcin--the one who wrote the note--is one of the Scourge's plagued servants, a human diplomat to the kingdom of Lordaeron before things... changed.\n\nIf the Scourge are trying to gain a foothold in Kalimdor, then it is up to us to act." }
WordHunterWoW_QuestEN[6523] = { title = "Protect Kaya", description = "Thank you for rescuing me! We must leave quickly before they discover that I am free. Please escort me to Camp Aparaje. From there, I know my way.\n\nMy father, Makaba Flathoof, will be desperate to know that I am safe.", objectives = "Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", completion = "Kaya is alive! <name>, I have you to thank for rescuing her." }
WordHunterWoW_QuestEN[6541] = { title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", objectives = "Report to Kadrak at the watch tower in Northern Barrens.", completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree." }
WordHunterWoW_QuestEN[6542] = { title = "Report to Kadrak", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", objectives = "Report to Kadrak at the watch tower in northern Barrens.", completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree." }
WordHunterWoW_QuestEN[6543] = { title = "The Warsong Reports", description = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.", objectives = "Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.", progress = "Hurry, <name>. They must receive their reports; it is urgent.", completion = "I can see that you are one that can be counted on. These updates are crucial to our plans to further our presence in Ashenvale. We can now plan our next move." }
WordHunterWoW_QuestEN[6544] = { title = "Torek's Assault", description = "Hey!  {class}!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, {name}, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?", objectives = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", completion = "So Torek's attack was successful!  Well done, <name>.  Night elves are decent foes.  A little skinny, but strong and fierce!  I'm sure the battle was something to see...\n\nAnd I hope you gained a scar or two!" }
WordHunterWoW_QuestEN[6545] = { title = "Warsong Runner Update", description = "", objectives = "So you're here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.\n\nYou'd best learn fast if you expect to keep up here. The threat of the naga grows, <name>. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.\n\nBut if you'd like to pitch in with that effort, speak with one of the others here at the outpost.", progress = "So you're here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.\n\nYou'd best learn fast if you expect to keep up here. The threat of the naga grows, <name>. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.\n\nBut if you'd like to pitch in with that effort, speak with one of the others here at the outpost.", completion = "Well, my update will explain all of this to Kadrak. You must return this to him as quickly as possible." }
WordHunterWoW_QuestEN[6546] = { title = "Warsong Outrider Update", description = "", objectives = "Much danger lies along this path, <name>. You'd do best to remember this while traveling in these lands. The threat of the alliance is quite near.\n\nWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale.  I have also discovered that the naga have taken over a large area of the land of Azshara.\n\nIt's good to see that we are still bolstering our numbers -- be ready for what lies ahead, <name>.", progress = "Much danger lies along this path, <name>. You'd do best to remember this while traveling in these lands. The threat of the alliance is quite near.\n\nWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale.  I have also discovered that the naga have taken over a large area of the land of Azshara.\n\nIt's good to see that we are still bolstering our numbers -- be ready for what lies ahead, <name>.", completion = "Take my update to Kadrak. Swiftly, <name>." }
WordHunterWoW_QuestEN[6547] = { title = "Warsong Scout Update", description = "", objectives = "Keep an eye out, <race>. The elves are often hiding in the shadows...\n\nWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.\n\nI assume you have my next orders from Kadrak?", progress = "Keep an eye out, <race>. The elves are often hiding in the shadows...\n\nWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.\n\nI assume you have my next orders from Kadrak?", completion = "Let Kadrak know of the success we have had here holding off the night elves. Our plans are going well." }
WordHunterWoW_QuestEN[6548] = { title = "Avenge My Village", description = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\n<name>, all I wish now is that more of them are dead. You will find them just to the west of here.", objectives = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", completion = "<name>, I thank you... but I will never forget what the Grimtotem have done to my village." }
WordHunterWoW_QuestEN[6561] = { title = "Blackfathom Villainy", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, <name>, please.", objectives = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", progress = "May the Earthmother be with you, <name>.\n\nPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.", completion = "Kelris has eluded the Argent Dawn for some time.\n\nFor some time they considered him dead or missing.\n\nBy ending his reign you have spared the lives of many innocent people, <name>.\n\nEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!\n\nYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, <name>." }
WordHunterWoW_QuestEN[6562] = { title = "Trouble in the Deeps", description = "Je'neu Sancrea is in need of aid. He waits just inside Blackfathom Deeps in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, <name>. There are forces there that will not take to your presence kindly.", objectives = "Speak to Je'neu Sancrea in Ashenvale.Je'neu Sancrea is in need of aid. He waits just inside Blackfathom Deeps in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, <name>. There are forces there that will not take to your presence kindly.", completion = "Tsunaman sent you? Excellent. Then we have matters to discuss." }
WordHunterWoW_QuestEN[6563] = { title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", objectives = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", progress = "How goes your search for the crystals, <name>? Have you witnessed the naga harvesting them? I pray to my ancestors we find the reason they are collecting such things.", completion = "Well done, <name>. These are the crystals I spoke of. Intriguing...\n\nI can feel the power within them. The spirits of water cling to them. Whatever the naga were going to use these for... well, let us be glad they are no longer in their hands." }
WordHunterWoW_QuestEN[6564] = { title = "Allegiance to the Old Gods", description = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"", objectives = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", progress = "Yes, <name>? What is it you need? There is still much I must learn about the crystals the naga are gathering.", completion = "This is interesting indeed. I am glad you have brought it to my attention.\n\nNow we have a name for our troubles... Lorgus Jett." }
WordHunterWoW_QuestEN[6565] = { title = "Allegiance to the Old Gods", description = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, <name>. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here.", objectives = "Kill Lorgus Jett.", completion = "Very good!! Thank you, <name>. We may not have stopped the Twilight's Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.\n\nWho knows what other plans they have manifesting, but we can rest easy for now." }
WordHunterWoW_QuestEN[6566] = { title = "What the Wind Carries", description = "It is good to see you again, <name>. The wind carries with it news from the Eastern Kingdom.\n\nSit, listen.Upon completion of this quest you will gain:", objectives = "Listen to Thrall." }
WordHunterWoW_QuestEN[6567] = { title = "The Champion of the Horde", description = "Rexxar, one of my most loyal champions, has discovered a way into the lair of the dragon. However he has left Azeroth to join our expedition into Outland.\n\nHowever, he left his companion, Rokaro, in Shadowprey Village with this information. You are to seek him out.Upon completion of this quest you will gain:", objectives = "Seek out Rokaro at Shadowprey Village in Desolace.Rexxar, one of my most loyal champions, has discovered a way into the lair of the dragon. However he has left Azeroth to join our expedition into Outland.\n\nHowever, he left his companion, Rokaro, in Shadowprey Village with this information. You are to seek him out.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6568] = { title = "Mistress of Deception", description = "Illusion and disguise. That is how you will fool the Black Dragonflight, and gain what you seek.\n\nThough I could teach you something of the skills of deception, you need the help of a master.\n\nI know of one who could do this. In the Western Plaguelands, you will find Myranda the Hag, once a master illusionist of Lordaeron. She has helped us in the past, and if she believes the cause worthy, she may help you.\n\nTake this message to her.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver Rokaro's Letter to Myranda the Hag in the Western Plaguelands." }
WordHunterWoW_QuestEN[6569] = { title = "Oculus Illusions", description = "So the <race> wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. The Warchief has entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.Upon completion of this quest you will gain:", objectives = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete." }
WordHunterWoW_QuestEN[6570] = { title = "Emberstrife", description = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.\n\nEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.\n\nTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!Upon completion of this quest you will gain:", objectives = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.\n\nProvided item:" }
WordHunterWoW_QuestEN[6571] = { title = "Warsong Supplies", description = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?", objectives = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.", progress = "I hope you can come through with the supplies! I'm in big trouble if I don't deliver them soon!", completion = "Excellent, <name>. You've saved me a lot of work!\n\nBut don't think that I'm not grateful!" }
WordHunterWoW_QuestEN[6581] = { title = "Warsong Saw Blades", description = "", objectives = "Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.\n\n..But what sort of payment do you have for me? You can't just take them, you know! My time isn't cheap!\n\nWhat I really need is a good gun to carry with me on my travels. A girl's gotta protect herself, you know? There's a gun I really like that I'm sure an engineer would have no problem making.\n\nSo, if you bring me a deadly blunderbuss, I'll give you the saw blade shipment. Do we have a deal?", progress = "Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.\n\n..But what sort of payment do you have for me? You can't just take them, you know! My time isn't cheap!\n\nWhat I really need is a good gun to carry with me on my travels. A girl's gotta protect herself, you know? There's a gun I really like that I'm sure an engineer would have no problem making.\n\nSo, if you bring me a deadly blunderbuss, I'll give you the saw blade shipment. Do we have a deal?", completion = "This is perfect -- just the thing! Well, here's the shipment." }
WordHunterWoW_QuestEN[6582] = { title = "The Test of Skulls, Scryer", description = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.Upon completion of this quest you will gain:", objectives = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring." }
WordHunterWoW_QuestEN[6583] = { title = "The Test of Skulls, Somnus", description = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...Upon completion of this quest you will gain:", objectives = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." }
WordHunterWoW_QuestEN[6584] = { title = "The Test of Skulls, Chronalis", description = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.Upon completion of this quest you will gain:", objectives = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife." }
WordHunterWoW_QuestEN[6585] = { title = "The Test of Skulls, Axtroz", description = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!Upon completion of this quest you will gain:", objectives = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." }
WordHunterWoW_QuestEN[6601] = { title = "Ascension...", description = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rokaro and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." }
WordHunterWoW_QuestEN[6602] = { title = "Blood of the Black Dragon Champion", description = "How would you feel about paying a visit to the General? No illusions, this time.\n\nCeremony? A pretty word to describe the bloodletting that amuses the Black Dragonflight.\n\nAll this amulet requires is the blood of General Drakkisath. Primitive security. There are other ways to receive the General's blood.\n\nGo to Blackrock Spire and kill Drakkisath. Return with his blood and I will activate the key to Onyxia's lair.You will receive:", objectives = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rokaro." }
WordHunterWoW_QuestEN[6603] = { title = "Trouble in Winterspring!", description = "There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.", objectives = "Find Donova Snowden near the hot springs in Winterspring.There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.", completion = "Well, hi there! So Meggi told you of the trouble I have found here?" }
WordHunterWoW_QuestEN[6604] = { title = "Enraged Wildkin", description = "Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?", objectives = "Speak with Jaron Stoneshaper at Starfall Village.Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?", completion = "Aye, what can I do for you?" }
WordHunterWoW_QuestEN[6605] = { title = "A Strange One", description = "I just got back from Felwood, <name>. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...", objectives = "Speak with Winna Hazzard in Felwood.I just got back from Felwood, <name>. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...", completion = "Ah, <class>. I see that there is hope yet. Are you here to assist me?" }
WordHunterWoW_QuestEN[6606] = { title = "A Little Luck", description = "We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!Upon completion of this quest you will gain:", objectives = "Speak with Witch Doctor Mau'ari in Everlook.We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6607] = { title = "Nat Pagle, Angler Extreme", description = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:", objectives = "Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!", progress = "Anything bitin' today?", completion = "Now that's a fine catch!\n\nCome over here, lemme show you how to set a few lines." }
WordHunterWoW_QuestEN[6608] = { title = "You Too Good.", description = "Lumak no can teach {name} no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", objectives = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).", completion = "'Course, you must be a friend of Lumak's.\n\nFishin'? I can tell you all 'bout fishin'." }
WordHunterWoW_QuestEN[6609] = { title = "I Got Nothin' Left!", description = "I'm a dwarf fer cryin' out loud, <lad/missy>! I ain't been designed to fish! I mean look at me! I'm practically made outta stone.\n\nI got nothin' left - ye tapped me out. I've taught ye all I know, flipflop!\n\nDon't ye get it? Ah, fine. I got an ol' friend over on Kalimdor who can help ye out. 'Is name be Nat Pagle, a fine lad. Find him on the islands south o' Theramore. Git goin'!", objectives = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!", completion = "I've always got room on my island for visitors... I reckon..." }
WordHunterWoW_QuestEN[6610] = { title = "Clamlette Surprise", description = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, {name}, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:", objectives = "Dirge Quikcleave wants you to get the following items:\n\n10 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Fine Aged Cheddar. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.", progress = "My cravings are going to be the end of me! Hurry, <name> - before I dip into my own supply.", completion = "You are in for a special treat, <name>. Watch and learn!" }
WordHunterWoW_QuestEN[6611] = { title = "To Gadgetzan You Go!", description = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat {race} needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!", objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", completion = "<Dirge spits out some leather sandal bits.>\n\nPfftooey...\n\n<Dirge hacks loudly.>\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates." }
WordHunterWoW_QuestEN[6612] = { title = "I Know A Guy...", description = "I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, <lad/missy> - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.", objectives = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", completion = "<Dirge spits out leather.>\n\nPfftey...\n\n<Dirge hacks loudly.>\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates, <race>." }
WordHunterWoW_QuestEN[6621] = { title = "King of the Foulweald", description = "My research has paid off.\n\nI believe that with a show of force, we can diminish the furbolgs' aggressiveness.\n\nTake this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, {name}. This is no task for a single {class}.", objectives = "Place Senani's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Senani at Silverwind Refuge.", progress = "Did you defeat Chief Murgut, <name>?  Did you retrieve his foulweald totem?", completion = "Good work, <name>.  Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:\n\nThe Horde is not to be trifled with.\n\nI don't believe that tribe will be giving us much trouble for a long time." }
WordHunterWoW_QuestEN[6622] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.\n", objectives = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", completion = "Doctor <name>, welcome to Horde Trauma." }
WordHunterWoW_QuestEN[6623] = { title = "Horde Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!", objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.", completion = "Wonderful. Put on your scrubs, we are to start at once!" }
WordHunterWoW_QuestEN[6624] = { title = "Triage", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.\n", objectives = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", completion = "Doctor <name>, welcome to Alliance Trauma." }
WordHunterWoW_QuestEN[6625] = { title = "Alliance Trauma", description = "Doctor {name}, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!", objectives = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.", completion = "Wonderful. Put on your scrubs, we are to start at once!" }
WordHunterWoW_QuestEN[6626] = { title = "A Host of Evil", description = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, <name>. What do you say? Are you up for some hunting?", objectives = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", completion = "Thank you, <name>! The work you've done will be a great help, I'm sure.\n\nI will continue my study of this diplomat and the rest of the quilboar here. If you seek greater adventure, I'd find a few friends and head into the cave that looks like a great boar maw just over there. I'm sure once you're inside you'll find greater challenges to face." }
WordHunterWoW_QuestEN[6627] = { title = "Test of Lore", description = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, <class>, so do not feel pressured. You may take as long as you like to answer.", objectives = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", completion = "Well done, <class>. You have studied the text I asked you to, and now you have passed another of our tests." }
WordHunterWoW_QuestEN[6628] = { title = "Test of Lore", description = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.\n\nAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, <name>--there is no pressure to answer quickly.", objectives = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.", completion = "Well done, <name>. I had my doubts if you studied the text I asked you to get, but you've answered correctly." }
WordHunterWoW_QuestEN[6629] = { title = "Kill Grundig Darkcloud", description = "<name>, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.", objectives = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.", completion = "Grundig Darkcloud is dead! <name>, I will always be grateful for what you've done here today." }
WordHunterWoW_QuestEN[6641] = { title = "Vorsha the Lasher", description = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, {name}. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.", objectives = "Defeat Vorsha the Lasher.", completion = "I have witnessed many naga attacks since I arrived here. It puts my mind at ease that Vorsha will no longer roam freely.\n\nWe are in your debt, <name>." }
WordHunterWoW_QuestEN[6642] = { title = "Favor Amongst the Brotherhood, Dark Iron Ore", description = "", objectives = "Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.\n\nFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.", progress = "Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.\n\nFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
WordHunterWoW_QuestEN[6643] = { title = "Favor Amongst the Brotherhood, Fiery Core", description = "", objectives = "Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.\n\nMany of the Brotherhood have been lost in their search for Fiery Cores.\n\nOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.", progress = "Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.\n\nMany of the Brotherhood have been lost in their search for Fiery Cores.\n\nOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
WordHunterWoW_QuestEN[6644] = { title = "Favor Amongst the Brotherhood, Lava Core", description = "", objectives = "The Thorium Brotherhood sympathizes with your plight, <race>. This is why Lokthos has been empowered to bargain.\n\nOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.", progress = "The Thorium Brotherhood sympathizes with your plight, <race>. This is why Lokthos has been empowered to bargain.\n\nOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
WordHunterWoW_QuestEN[6645] = { title = "Favor Amongst the Brotherhood, Core Leather", description = "", objectives = "Many of the sacred recipes require the skin from Ragnaros' chosen pets.\n\nOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.", progress = "Many of the sacred recipes require the skin from Ragnaros' chosen pets.\n\nOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
WordHunterWoW_QuestEN[6646] = { title = "Favor Amongst the Brotherhood, Blood of the Mountain", description = "", objectives = "The tears of the Fire Lord are a rare find indeed.\n\nOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.", progress = "The tears of the Fire Lord are a rare find indeed.\n\nOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades." }
WordHunterWoW_QuestEN[6661] = { title = "Deeprun Rat Roundup", description = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...", objectives = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty.", progress = "Yarrr... Swabby, what be takin' ye so long?", completion = "These'll werk nicely, matey. Me brother needs em still tickin' and kickin,' else they go sour... Ye don't want to taste no sour rat kabob." }
WordHunterWoW_QuestEN[6662] = { title = "Me Brother, Nipsy", description = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.", objectives = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.", progress = "<Nipsy puts his index finger through one of the air holes in the carton.>\n\nAlive and kicking... and just in time!", completion = "Poor Monty. Ever since the Gnomeregan incident, he hasn't been the same. That boy has never seen an ocean in his life, let alone being some kind of pirate.\n\n<Nipsy sighs.>\n\nAt least he keeps the flow of twitching critters coming." }
WordHunterWoW_QuestEN[6681] = { title = "The Manor, Ravenholdt", description = "<name>,\n\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\n\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\n\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\n\nRegards,\n\nFahrad", objectives = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared.", progress = "Did you meet Milton?\n\n<Fahrad laughs.>", completion = "Most excellent, young thief.\n\nYou look a bit beaten down, but no worse for the wear.\n\nA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?\n\nSpeak with the guards outside. They will get you started." }
WordHunterWoW_QuestEN[6701] = { title = "Syndicate Emblems", description = "", objectives = "We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population!\n\nWe've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally.\n\nPick their pockets clean and turn the emblems in to me or one of the other guards.\n\nStart at Durnholde, south of here.", progress = "We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population!\n\nWe've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally.\n\nPick their pockets clean and turn the emblems in to me or one of the other guards.\n\nStart at Durnholde, south of here.", completion = "Hey, nice work! Keep this up and the other rogues might stop spitting on you." }
WordHunterWoW_QuestEN[6721] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Dazalar at Dolanaar in Teldrassil.Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6722] = { title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Dazalar at Dolanaar in Teldrassil.Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[6741] = { title = "More Booty!", description = "", objectives = "I need more armor scraps, <name>!  Do you have any?", progress = "I need more armor scraps, <name>!  Do you have any?", completion = "Thanks again, <name>.  You do the Horde proud..." }
WordHunterWoW_QuestEN[6761] = { title = "The New Frontier", description = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.", objectives = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid. Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice. It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race. Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.", completion = "Yes <class>, thank you for coming.  I apologize about the misunderstanding... the air is thick with mistrust between the Arch Druid here and Keeper Remulos in Moonglade.  Each suspect the other of chicanery, and the fact that strange corruptions of Teldrassil continue unabated are still an issue here.  It does little to quell mistrust.\n\nRegardless, our duty to the Cenarion Circle remains... even if those who lead it may disagree with one another." }
WordHunterWoW_QuestEN[6762] = { title = "Rabine Saturna", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro. You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly. There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.", completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  I also know that Arch Druid of Darnassus expressed his displeasure to you in your lending us aid.  Rest assured that it is for the greater good, and that you will be safe from any ill-conceived repercussions you may be the target of.\n\nYou are among friends here, <name>." }
WordHunterWoW_QuestEN[6781] = { title = "More Armor Scraps", description = "", objectives = "<name>, we need more armor scraps to supply our troops!", progress = "<name>, we need more armor scraps to supply our troops!", completion = "These are some good pieces, <name>.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
WordHunterWoW_QuestEN[6801] = { title = "Lokholar the Ice Lord", description = "", objectives = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", progress = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!" }
WordHunterWoW_QuestEN[6804] = { title = "Poisoned Water", description = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!\n\nTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.Upon completion of this quest you will gain:", objectives = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands. Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara." }
WordHunterWoW_QuestEN[6805] = { title = "Stormers and Rumblers", description = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.", objectives = "Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara.", completion = "Your bravery is proven, as is your worth to us.  Perhaps I may have future tasks for you, tasks more befitting a valued ally of the Waterlords." }
WordHunterWoW_QuestEN[6821] = { title = "Eye of the Emberseer", description = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.Upon completion of this quest you will gain:", objectives = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara." }
WordHunterWoW_QuestEN[6822] = { title = "The Molten Core", description = "<name>, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, <name>.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.Upon completion of this quest you will gain:", objectives = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara." }
WordHunterWoW_QuestEN[6823] = { title = "Agent of Hydraxis", description = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.\n\nThe campaign will be long, but if you persevere then your glory and honor will be great.Upon completion of this quest you will gain:", objectives = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara." }
WordHunterWoW_QuestEN[6824] = { title = "Hands of the Enemy", description = "<name>, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.\n\nBut its success would further our war efforts tremendously and... it was deemed worth risking you.\n\nWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!\n\nThis task will take every resource you possess, <name>, but if can do it then the Firelords will be dealt a terrible blow.", objectives = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", progress = "Have you defeated Lucifron and the others, <name>?  Do you have the hands of the enemy?", completion = "You have the hands!  You defeated the fire captains!  I would not have thought it possible, had I not known you and what you are capable of.\n\n<name>, your exploits are without number, but word of this last feat will send waves among the Waterlords.  Your name may one day be legend to us.\n\nSpeak with me again, <name>.  I may have yet another task..." }
WordHunterWoW_QuestEN[6825] = { title = "Call of Air - Guse's Fleet", description = "", objectives = "We must prepare the new fleet of War Riders, <race>! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.\n\nI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!", progress = "We must prepare the new fleet of War Riders, <race>! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.\n\nI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!", completion = "The fleet feeds on their flesh. It consumes the enemy.\n\nFlight is imminent!" }
WordHunterWoW_QuestEN[6826] = { title = "Call of Air - Jeztor's Fleet", description = "", objectives = "You've worked hard, <name>, but we have only just begun!\n\nMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!\n\nMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.\n\nMake haste, soldier!", progress = "You've worked hard, <name>, but we have only just begun!\n\nMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!\n\nMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.\n\nMake haste, soldier!", completion = "More! More! Bring more for they are soon to be ready!" }
WordHunterWoW_QuestEN[6827] = { title = "Call of Air - Mulverick's Fleet", description = "", objectives = "I was locked up in a dwarven hellhole for days. You better believe I want revenge!\n\nWe must plan carefully.\n\nFirst, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.", progress = "I was locked up in a dwarven hellhole for days. You better believe I want revenge!\n\nWe must plan carefully.\n\nFirst, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.", completion = "Not enough! I would expect this level of work from an initiate, but you, <name>? Come on, soldier! HUSTLE! More flesh is needed!" }
WordHunterWoW_QuestEN[6843] = { title = "Da Foo", description = "", objectives = "" }
WordHunterWoW_QuestEN[6844] = { title = "Umber, Archivist", description = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.", objectives = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", progress = "Why, hello there!  Hrmm...\n\nLet me be a little honest with you, friend... you smell a bit ripe.  Whiffy, one might say.  Now I'm not making a personal assailment of your being.  I'm just saying... in the future, you may want to freshen up a little after coming in from the field.  It will make those first impressions a little more positively impressionable!\n\nAnyhoo... what can I do for you?", completion = "Well great monkey toads!  What have you got here?  It's sort of book shaped, I guess... I'll try and crack this shell on it.\n\nLayo sent you to me from Silithus?  I've only heard very hushed rumblings - which I guess aren't all that hushed when you think about it - about the horrors that are going on out there.  Couple that with my lack of pleasure for anything bug-like, and you've got the recipe for me needing to stay here with the books!" }
WordHunterWoW_QuestEN[6845] = { title = "Uncovering Past Secrets", description = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, <name>... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.", objectives = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", completion = "Ah, <name> - I had hoped you would stop by.  I am glad to see you well.\n\nI received notice you would be coming in from the field, and I wanted to personally express the Cenarion Circle's gratitude for the assistance you've given us thus far.  No doubt there are more secrets to uncover from Silithus; your delivery to Umber should prove most interesting once uncovered.  Please, accept this as a token of our continued appreciation for your aid.\n\nThank you, generous <class>." }
WordHunterWoW_QuestEN[6846] = { title = "Begin the Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[6847] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>Upon completion of this quest you will gain:", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!" }
WordHunterWoW_QuestEN[6848] = { title = "Master Ryson's All Seeing Eye", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>You will receive:", objectives = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!" }
WordHunterWoW_QuestEN[6861] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.You will receive:", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw." }
WordHunterWoW_QuestEN[6862] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.You will receive:", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw." }
WordHunterWoW_QuestEN[6881] = { title = "Ivus the Forest Lord", description = "", objectives = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", progress = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", completion = "Well done, <name>. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause." }
WordHunterWoW_QuestEN[6901] = { title = "Launch the Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[6921] = { title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n<name>, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!", objectives = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud." }
WordHunterWoW_QuestEN[6922] = { title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.", objectives = "Bring the Strange Water Globe to Je'neu Sancrea in Blackfathom Deeps.", progress = "Ah, hello again <name>.  I was just reading the waves of the sea, much like I always do.  What brings you to me?", completion = "This... this is quite the find, <name>.\n\nYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight's Hammer, our studies will also show how they did it as well.\n\nYou did well in bringing this to me.  Please - take this, along with the Earthen Ring's warmest regards." }
WordHunterWoW_QuestEN[6941] = { title = "Call of Air - Vipore's Fleet", description = "", objectives = "The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.", progress = "The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.", completion = "The flight will be ready soon. Continue your efforts!" }
WordHunterWoW_QuestEN[6942] = { title = "Call of Air - Slidore's Fleet", description = "", objectives = "My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.\n\nThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.\n\nOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!", progress = "My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.\n\nThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.\n\nOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!", completion = "Keep em coming, soldier! The Aerie gryphons will be ready to strike in no time at all!" }
WordHunterWoW_QuestEN[6943] = { title = "Call of Air - Ichman's Fleet", description = "", objectives = "Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.\n\nReturn to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!", progress = "Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.\n\nReturn to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!", completion = "Can you see it? Look at them, soldier! They're coming around... Soon, Ichman's flight will once again strike at the heart of the valley! Stormpike will rule the skies!" }
WordHunterWoW_QuestEN[6961] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Great-father Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." }
WordHunterWoW_QuestEN[6962] = { title = "Treats for Great-father Winter", description = "Hey, can you do Great-father Winter a favor, um, little boy?\n\nNot to needlessly talk about myself in the third person, but Great-father Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Great-father and fetch some for me?", objectives = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Great-father Winter in Orgrimmar.", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Great-father Winter there, <name>.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort." }
WordHunterWoW_QuestEN[6963] = { title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains area of Hillsbrad Foothills, and that's where our man went.\n\nSee if both are out there, safe and sound!", objectives = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Hillsbrad Foothills.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold..." }
WordHunterWoW_QuestEN[6964] = { title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", objectives = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.", completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us tauren.  Nowadays, it seems as though others have turned the legend of this season of renewal into something that helps to sell candies and presents.\n\nIt's no surprise that Furmund is bitter about that sort of change.  He and other tauren like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast." }
WordHunterWoW_QuestEN[6981] = { title = "The Glowing Shard", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", objectives = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.", progress = "Hello, <race>. What can I do for you?", completion = "Oh... I have never seen anything like this..." }
WordHunterWoW_QuestEN[6982] = { title = "Coldtooth Supplies", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, <name>.  The mine is to the distant south, deep in Horde territory.", objectives = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Did you enter the Coldtooth mine in Horde territory, <name>?  Did you raid their supplies?", completion = "You got them!  Well done, <name>!  I'll go through these supplies and get them ready for our own troops!" }
WordHunterWoW_QuestEN[6983] = { title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Orgrimmar are disappointed!", objectives = "Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills.", progress = "<name> - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pastures' Feast of Winter Veil!\n\nYou're a true hero to everyone here at Smokywood Pastures and to all the children, of course!" }
WordHunterWoW_QuestEN[6984] = { title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", objectives = "Speak with Great-father Winter in Orgrimmar.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future." }
WordHunterWoW_QuestEN[6985] = { title = "Irondeep Supplies", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, <name>.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", objectives = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Did you enter the Irondeep mine, <name>?  Did you raid its supplies?", completion = "You got them!  Nicely done, <name>!  And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!" }
WordHunterWoW_QuestEN[7001] = { title = "Empty Stables", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", objectives = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", completion = "I can only hope that those charged with collecting ram hides are as determined as you, <name>.\n\nAt this rate, we will have the stables full in a matter of hours!" }
WordHunterWoW_QuestEN[7002] = { title = "Ram Hide Harnesses", description = "", objectives = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!", progress = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!" }
WordHunterWoW_QuestEN[7003] = { title = "Zapped Giants", description = "I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?\n\nI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!", objectives = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", progress = "Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won't do something as disappointing as explode on the user.\n\nOh, I mean for the zappers other than the one I gave you.  Absolutely!", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, <name>.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!" }
WordHunterWoW_QuestEN[7021] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Great-father Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." }
WordHunterWoW_QuestEN[7022] = { title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." }
WordHunterWoW_QuestEN[7023] = { title = "Greatfather Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Ironforge!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." }
WordHunterWoW_QuestEN[7024] = { title = "Great-father Winter is Here!", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Great-father Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", objectives = "Speak with Great-father Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", completion = "Ho ho hello.  I am Great-father Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah." }
WordHunterWoW_QuestEN[7025] = { title = "Treats for Greatfather Winter", description = "Hey, can you do Greatfather Winter a favor, um, little boy?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", objectives = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Greatfather Winter there, <name>.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort." }
WordHunterWoW_QuestEN[7026] = { title = "Ram Riding Harnesses", description = "", objectives = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!", progress = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!" }
WordHunterWoW_QuestEN[7027] = { title = "Empty Stables", description = "Just look at the stables, <name>! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.\n\nYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.\n\nWhen we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!", objectives = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.", progress = "Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", completion = "The stables will be full in no time at all. Keep up the good work!" }
WordHunterWoW_QuestEN[7028] = { title = "Twisted Evils", description = "The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, <class>. Relics of the old gods lie hidden behind the giant doors.\n\nIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.\n\nOnce I get the carvings, I will be able to... study them. These powers have been too long at rest...", objectives = "Collect 15 Theradric Crystal Carvings for Willow in Desolace.", progress = "Don't ask questions!\n\nYou have my request.", completion = "Ha ha ha! I knew you'd be back.\n\n<Willow mutters.>\n\n...So easy to convince.\n\n...Will do anything for the right price. Heh heh heh..." }
WordHunterWoW_QuestEN[7029] = { title = "Vyletongue Corruption", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", objectives = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, <name>...", completion = "Thank you for returning this, <name>. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude." }
WordHunterWoW_QuestEN[7041] = { title = "Vyletongue Corruption", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", objectives = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, <name>...", completion = "Thank you for returning this, <name>. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude." }
WordHunterWoW_QuestEN[7042] = { title = "Stolen Winter Veil Treats", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains area of Hillsbrad Foothills, and that's where our man went.\n\nSee if both are out there, safe and sound!", objectives = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Hillsbrad Foothills.", completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold..." }
WordHunterWoW_QuestEN[7043] = { title = "You're a Mean One...", description = "A creature called \"The Abominable Greench\" stole our shipment of treats, {name}.  Be careful though!  He's vicious and a bunch of those little green gnomes do his bidding!\n\nYou're gonna need some help in facing him.  Rumor has it he's holding our treats and our beloved Metzen the Reindeer at Growless Cave in the Hillsbrad Foothills!  Find the treats {name} and bring them back before the celebration is ruined and all the children of Stormwind are disappointed!", objectives = "Recover the Stolen Treats and free Metzen the Reindeer after defeating the Abominable Greench, who is hiding out near Growless Cave in the Hillsbrad Foothills.", progress = "<name> - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pastures' Feast of Winter Veil!\n\nYou're a true hero to everyone here at Smokywood Pastures and to all the children, of course!" }
WordHunterWoW_QuestEN[7044] = { title = "Legends of Maraudon", description = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.\n\nVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.\n\nYou must help him! Find the pieces, and speak to my brother... somehow.", objectives = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\n\nFind a way to speak with Celebras.", progress = "I have awoken from a nightmare that seemed it would never end...", completion = "Now that you have recovered the two parts of my scepter, I have hope that Maraudon may one day be rid of the Vyle corruption." }
WordHunterWoW_QuestEN[7045] = { title = "A Smokywood Pastures' Thank You!", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, {name}.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", objectives = "Speak with Greatfather Winter in Ironforge.", completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future." }
WordHunterWoW_QuestEN[7046] = { title = "The Scepter of Celebras", description = "My scepter was once a source of hope for me. It once granted me power over these caverns. I had hoped to bring peace to the spirit of my uncle...\n\nFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.\n\nTogether, we shall create the Scepter of Celebras once again!", objectives = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.\n\nSpeak with him when the ritual is complete.", completion = "Please take this, and know that the power allotted to you now must be used for good. Continue your journey through the caverns, and with hope, you will find the remains of my uncle. Much danger awaits you, <name>.\n\nSpeak with me again should the need arise." }
WordHunterWoW_QuestEN[7061] = { title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Baine Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.  ", objectives = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Baine Bloodhoof in Thunder Bluff.", progress = "I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend. I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore. Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public thought over the years.  Yes, I know that the goblins are helping to revive the season for their own ends, the fact that our people reflect upon it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young <class>.  I salute your wisdom." }
WordHunterWoW_QuestEN[7062] = { title = "The Reason for the Season", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorers' League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", objectives = "Speak with Historian Karnik at the Explorers' League in Ironforge about the Feast of Winter Veil.", completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us dwarves.  Nowadays, it seems as though others have turned the legend of Greatfather Winter into something that helps to sell candies and presents.\n\nIt's no surprise that Goli is bitter about that sort of change.  He and other dwarves like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast." }
WordHunterWoW_QuestEN[7063] = { title = "The Feast of Winter Veil", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Muradin Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.  ", objectives = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Muradin Bronzebeard in Ironforge.", progress = "I bid you welcome to the Kingdom of Ironforge, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public thought over the years.  While I recognize that the goblins are helping to revive the season for their own ends, the fact that the citizenry thinks about it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young <class>.  I salute your erudite nature." }
WordHunterWoW_QuestEN[7064] = { title = "Corruption of Earth and Seed", description = "Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", objectives = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", completion = "This is most wonderful news, <name>! Thank you!\n\nI will speak with Marandis and ask his wisdom on the topic of Zaetar's remains, but at least you have overcome the hardest of the tasks.\n\nI was told that if we were successful in our mission, I had permission to reward those who aided us. I was given these items as tokens from our people--you may choose one." }
WordHunterWoW_QuestEN[7065] = { title = "Corruption of Earth and Seed", description = "In the depths of Maraudon lives a creature of chaos and evil, <name>. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", objectives = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", completion = "This is most wonderful news, <name>! Thank you!\n\nAlthough it concerns me that you were not able to bring back Zaetar's remains, who am I to question the will of Cenarius' first born. Perhaps now the will of the centaur will break and their thirst for blood will lessen--we can only hope.\n\nIf successful in our mission, I was given these items to reward any who aided us. You may choose one as a token of thanks." }
WordHunterWoW_QuestEN[7066] = { title = "Seed of Life", description = "The misbegotten centaur--my sons and daughters--have need of their father.\n\nLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.\n\nBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand.", objectives = "Seek out Remulos in Moonglade and give him the Seed of Life.", progress = "You have the scent of corruption on you, <name>... much like many adventurers these days. But something about you is different. Is there something you've come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.\n\nPlease, I implore you, tell me why you've sought an audience with me.", completion = "So my brother has finally found peace? I am proud to have lived to see this day. In all his arrogance and anger, I truly thought he was lost to us, but this... this symbol of his sacrifice only proves that he is not lost--he has only been reborn. He takes his place in nature as was his duty.\n\nThank you, <name>. By bringing this to me, you have secured a small amount of hope that I thought I had once lost. This seed will be important to the people of this war-torn land some day... I can sense it." }
WordHunterWoW_QuestEN[7067] = { title = "The Pariah's Instructions", description = "Though exiled as a heretic, my beliefs still ring true--that alone drives me onward. But for my destiny to be complete, I need the aid of an outsider... one not of any centaur tribe.\n\nThe task requires someone to enter the holy halls of Maraudon--a tomb my people protect, and only the most devout are ever allowed to enter.\n\nIf you agree to aid me, then you need only nod. I will pass you a parchment with my instructions on it. Read it over and consider my words.", objectives = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", progress = "What did you decide, <name>? Can you help me? Will you set foot on holy ground to help me forge one great centaur tribe!?", completion = "This is it, <race>! This is it! Now I can begin the great task of uniting the tribes. Thank you.\n\nTake this for your efforts, please. I hope when next we meet, it will be on much different terms." }
WordHunterWoW_QuestEN[7068] = { title = "Shadowshard Fragments", description = "Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.\n\nYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.\n\nThe place be dangerous, so maybe you be bringing some friends.", objectives = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", progress = "You find the crystals yet? Rituals of power, spells of great strength--those shadowshards maybe very helpful in all kind of arcane magics.", completion = "Ah, these be perfect for me magics. Here, you take one of these trinkets and be on your way... me got much studyin' to do." }
WordHunterWoW_QuestEN[7070] = { title = "Shadowshard Fragments", description = "I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.\n\nIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.", objectives = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", progress = "Have you made the trip yet? I realize it'd be quite dangerous, but if you were successful, it would very much be worth it.", completion = "These are perfect, <name>. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study." }
WordHunterWoW_QuestEN[7081] = { title = "Alterac Valley Graveyards", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, {name}, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", objectives = "Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", completion = "Well done!  Graveyards are vital to our control of Alterac Valley.  When you capture one, you help ensure the Alliance's sovereignty here.\n\nGo now, <name>.  Reenter the battle, and if you see a graveyard under the Horde's control... you know what to do!" }
WordHunterWoW_QuestEN[7082] = { title = "The Graveyards of Alterac", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, {name}, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", objectives = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", completion = "Well done, <name>!  With each graveyard under our control, the spirits of our enemies will wander more lost and aimless." }
WordHunterWoW_QuestEN[7101] = { title = "Towers and Bunkers", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", objectives = "Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", completion = "I heard of your mission's success!  That pleases me...\n\nOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!" }
WordHunterWoW_QuestEN[7102] = { title = "Towers and Bunkers", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", objectives = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", completion = "I received a field report stating you helped secure an enemy banner.  Well done, <name>!  With their ranged troops out of position we can move the line of battle forward!" }
WordHunterWoW_QuestEN[7121] = { title = "The Quartermaster", description = "{name}, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", objectives = "Speak with the Stormpike Quartermaster.", completion = "It's good to see fresh troops here, <name>, but with a little luck you'll get into some action and won't be fresh for long!\n\nSpeak with me again.  I have tasks I must discuss with you...." }
WordHunterWoW_QuestEN[7122] = { title = "Capture a Mine", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", objectives = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", completion = "You did it!  Well done, <name>!\n\nWhen we control a mine and have troops stationed there, it's much easier to gather minerals and supplies from it." }
WordHunterWoW_QuestEN[7123] = { title = "Speak with our Quartermaster", description = "{name}, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", objectives = "Speak with the Frostwolf Quartermaster.", completion = "Hail, <name>!  It is good to see a <class> like yourself, eager to do his part for the Horde.  Speak with me again, for I have vital tasks for you..." }
WordHunterWoW_QuestEN[7124] = { title = "Capture a Mine", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, {name}!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", objectives = "Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", completion = "You captured a mine!  With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.\n\nWell done, <name>.  The deed you have done is a great boon to our battle efforts." }
WordHunterWoW_QuestEN[7141] = { title = "The Battle of Alterac", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", objectives = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.", completion = "Well done, <name>!  With the Horde's nose bloodied after the death of their general, we'll have the breathing room we need to explore!" }
WordHunterWoW_QuestEN[7142] = { title = "The Battle for Alterac", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, {name}, and then return to me.", objectives = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in the Alterac Mountains.", completion = "Well done, <name>!  Stormpikes have no hope in this foolish invasion.\n\nHah!  So far, all they've done is get their general killed!" }
WordHunterWoW_QuestEN[7161] = { title = "Proving Grounds", description = "Hail, {class}. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...\n\nAll newcomers to the Valley must first complete the rite of battle.\n\nDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.", objectives = "Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond.", progress = "Wake up! Wake up, <name>! This is not a dream. You really are entrenched in the midst of a raging battle!", completion = "That burning sensation you feel is your soul being awakened. Your spirit has accepted the call to arms.\n\nYou are now one of the Frostwolf, <name>. Congratulations.\n\nCarry this insignia with you at all times. As you advance among the ranks of Frostwolf, I will replace the insignia with other, more powerful insignias.\n\nPerhaps someday you will be exalted among the Frostwolf Clan. Should that day ever come, you will be granted the Eye of Command." }
WordHunterWoW_QuestEN[7162] = { title = "Proving Grounds", description = "You've arrived just in time, {class}. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.\n\nBefore you make your way to the field of battle, you will want to join the rank of Stormpike.\n\nSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.", objectives = "Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.", progress = "Beware the harpies of the region, <class>. They'll not think twice to rip out your throat!", completion = "Take and wear this insignia with pride, <name>. As your rank among the Stormpike grows, so too will the insignia. Return to me as you gain honor with Stormpike, and I shall replace your insignia with other, more powerful insignias.\n\nPerhaps someday you will grow to be a legend on this field of battle. Should that day ever come, you will be granted the Eye of Command." }
WordHunterWoW_QuestEN[7163] = { title = "Rise and Be Recognized", description = "<Warmaster Laggrond salutes you.>\n\nIt is your time, {name}. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", objectives = "<Warmaster Laggrond salutes you.>\n\nIt is your time, <name>. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", progress = "<Warmaster Laggrond salutes you.>\n\nIt is your time, <name>. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", completion = "This new insignia reflects your rank amongst the Frostwolf. Keep it on you at all times.\n\nAnd <class>... Die with honor!" }
WordHunterWoW_QuestEN[7164] = { title = "Honored Amongst the Clan", description = "It is good to see you again, {class}. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, {name}. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", objectives = "It is good to see you again, <class>. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, <name>. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", progress = "It is good to see you again, <class>. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, <name>. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", completion = "<Warmaster Laggrond salutes.>\n\nGo, <name>! Continue your defense of the Frostwolf. This war must be won! For Drek'Thar! For the Warchief!" }
WordHunterWoW_QuestEN[7165] = { title = "Earned Reverence", description = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", objectives = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", progress = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", completion = "<Warmaster Laggrond roars.>\n\nThey have already begun telling tales of your deeds, soldier. The Stormpike shakes in fear when your name is uttered. Carry on!" }
WordHunterWoW_QuestEN[7166] = { title = "Legendary Heroes", description = "Your radiate command and power, {class}. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", objectives = "Your radiate command and power, <class>. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", progress = "Your radiate command and power, <class>. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", completion = "Soon, all on the field of battle will be under your watchful eye. Command of the Valley and its troops will be yours!" }
WordHunterWoW_QuestEN[7167] = { title = "The Eye of Command", description = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander {name}.\n\n<Warmaster Laggrond salutes.>", objectives = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander <name>.", progress = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander <name>.", completion = "Channel the power of the insignia. Let the enemy hear your words. The might of the Horde is unquestionable!" }
WordHunterWoW_QuestEN[7168] = { title = "Rise and Be Recognized", description = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, {class}. The time has come.\n\nPresent your insignia.", objectives = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, <class>. The time has come.\n\nPresent your insignia.", progress = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, <class>. The time has come.\n\nPresent your insignia.", completion = "Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!" }
WordHunterWoW_QuestEN[7169] = { title = "Honored Amongst the Guard", description = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", objectives = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", progress = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", completion = "The king has been made aware of your battlefront heroics, <class>. Continue in your stalwart defense of the Stormpike Guard!" }
WordHunterWoW_QuestEN[7170] = { title = "Earned Reverence", description = "I must know, {name}. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", objectives = "I must know, <name>. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", progress = "I must know, <name>. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", completion = "When we first met, I would have never guessed that a hero was in the making. Carry on, soldier!" }
WordHunterWoW_QuestEN[7171] = { title = "Legendary Heroes", description = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", objectives = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", progress = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", completion = "Surely it will be you who carries the Eye of Command!" }
WordHunterWoW_QuestEN[7172] = { title = "The Eye of Command", description = "Let them hear your voice, Commander {name}! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.\n", objectives = "Let them hear your voice, Commander <name>! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.", progress = "Let them hear your voice, Commander <name>! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.", completion = "It is you who must lead our troops to victory, Commander! The soldiers are under your command. They will follow your direct orders. Lead them.... Crush the Frostwolf." }
WordHunterWoW_QuestEN[7181] = { title = "The Legend of Korrak", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond." }
WordHunterWoW_QuestEN[7201] = { title = "The Last Element", description = "There is work to be had for those venturing into the depths, <name>.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.", objectives = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", progress = "<Rubs her hands together.>\n\nShow them to me!", completion = "Wonderful! I will have these sent by courier to the Undercity at once!\n\nAs for you - here is payment, as promised. Keep the change, you filthy beast!" }
WordHunterWoW_QuestEN[7202] = { title = "Korrak the Bloodrager", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.", objectives = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains." }
WordHunterWoW_QuestEN[7221] = { title = "Speak with Prospector Stonehewer", description = "Ah, <name>, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar.  She's recruiting for a vital mission into enemy territory.  You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar.  There's plenty to do for a hardworking <class> who's not afraid to get <his/her> hands dirty.Upon completion of this quest you will gain:", objectives = "Speak with Prospector Stonehewer in the Dun Baldar garrison.Ah, <name>, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar. She's recruiting for a vital mission into enemy territory. You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar. There's plenty to do for a hardworking <class> who's not afraid to get <his/her> hands dirty.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7222] = { title = "Speak with Voggah Deathgrip", description = "A <class>?  Good!  We are glad to see you in Alterac, <name>.  Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip.  He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.Upon completion of this quest you will gain:", objectives = "Speak with Voggah in Frostwolf Keep.A <class>?  Good!  We are glad to see you in Alterac, <name>. Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip. He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7223] = { title = "Armor Scraps", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", objectives = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.", progress = "Did you bring any armor scraps, <name>?", completion = "These are some good pieces, <name>.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!" }
WordHunterWoW_QuestEN[7224] = { title = "Enemy Booty", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", objectives = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.", progress = "How goes the hunting, <name>.  Do you have any armor scraps for me?", completion = "These will do nicely.  I'll melt them down and patch them up and you'll never know they came from those Stormpike cowards!\n\nThanks, <name>.  And let me polish up that armor of yours..." }
WordHunterWoW_QuestEN[7241] = { title = "In Defense of Frostwolf", description = "The drums of war sound off in a distant land, <class>. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge.\n\nBy the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf.\n\nIt is you who must now take the next step in your evolution.\n\nNorth of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry <class>, for the battle is upon us!", objectives = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.", completion = "To become a soldier of Frostwolf, one must first be tested..." }
WordHunterWoW_QuestEN[7261] = { title = "The Sovereign Imperative", description = "We are fighting a brutal battle in the valleys of Alterac. The savage Frostwolf Clan challenges the might of the Stormpike! They must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge.\n\nAlas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.", objectives = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.\n\nFor the glory of Bronzebeard!", completion = "Let's get to work!" }
WordHunterWoW_QuestEN[7281] = { title = "Brotherly Love", description = "Tragic... My brother faces me on the field of battle: A commander for the Stormpike.\n\nOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...\n\nDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.\n\nAnd soldier, do not go alone.", objectives = "Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete.", completion = "Your heroics will not go unnoticed, <name>.\n\nI must waste no time if he is to be saved. Sylvanas must be contacted!" }
WordHunterWoW_QuestEN[7282] = { title = "Brotherly Love", description = "He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.\n\nVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.", objectives = "Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete.", completion = "You did remember to burn the corpse, didn't you?" }
WordHunterWoW_QuestEN[7301] = { title = "Fallen Sky Lords", description = "We got them held prisoner, {race}. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.\n\nSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.", objectives = "Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.", completion = "Unbelievable! You did free them, right? Right??? Well at the very least we know where they were held." }
WordHunterWoW_QuestEN[7302] = { title = "Fallen Sky Lords", description = "Our air support is in shambles, {name}. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!\n\nGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.\n\nThat's all the information I have. Move out! Search through the areas thoroughly.", objectives = "Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.", completion = "Well done! The information you recovered will be invaluable to our cause." }
WordHunterWoW_QuestEN[7321] = { title = "Soothing Turtle Bisque", description = "Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...\n\nSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.\n\nIf you bring me some Turtle Meat from the snapjaws, I'll show you how it's done!", objectives = "Bring 10 pieces of Turtle Meat to Christoph Jeffcoat in Tarren Mill.", progress = "Any luck finding the ingredients?  I'll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...", completion = "My soothing turtle bisque will keep you warm on a cold night... if you care about that kind of thing." }
WordHunterWoW_QuestEN[7341] = { title = "A Fair Trade", description = "", objectives = "" }
WordHunterWoW_QuestEN[7342] = { title = "Arrows Are For Sissies", description = "", objectives = "" }
WordHunterWoW_QuestEN[7361] = { title = "Favor Amongst the Darkspear", description = "<Najak snarls.>\n\nBefore the night elves existed there was troll. It was from troll that the night elves came.\n\nTheir mutinous attacks against my people will not be tolerated. Staghelm seeks to wipe us out - to leave no trace of those that bore him and his ilk. It will not happen!\n\nFor every night elf that you slay and decapitate, Najak will grant you favor amongst the Darkspear. Word of your deeds will be spread across Kalimdor and the Eastern Kingdoms. Go now and serve the Darkspear!", objectives = "You have been tasked with slaying opposing night elf players in Alterac Valley.\n\nKill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head." }
WordHunterWoW_QuestEN[7362] = { title = "Ally of the Tauren", description = "The Elder Crone has sent me to this warzone to research the other races. More specifically, I am to collect gnome samples. Magatha is primarily interested in their survivability. Aye, the gnomes - while pitifully weak and miniscule - exude great resilience both in and out of combat.\n\nFortunately for you, I am looking for ruffians to do Magatha's bidding. Return to me with tufts of gnome hair and you shall be known to the tauren as an ally.", objectives = "You have been tasked with slaying opposing gnome players in Alterac Valley.\n\nKill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair." }
WordHunterWoW_QuestEN[7363] = { title = "The Human Condition", description = "Humans are so utterly detestable.\n\n<Commander Philips grimaces.>\n\nWhile it is true that I am a soldier of Frostwolf, I remain a servant of Sylvanas.\n\nDuring my tour of duty, I do extra work on the side for the Dark Apothecaries of the Undercity.\n\nI have been tasked with collecting human bone chips that are to be used in curing the human condition.\n\nI am authorized to pass that task on to my subordinates.\n\nFind them. Kill them. Return their bone chips to me.", objectives = "You have been tasked with slaying opposing human players in Alterac Valley.\n\nKill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a  Human Bone Chip.\n\nA cure for the human condition is close at hand!" }
WordHunterWoW_QuestEN[7364] = { title = "Gnomeregan Bounty", description = "The High Tinkerer himself has sent me to this field of battle to defend my gnomish brothers and sisters. We have received word that the tauren are singling out and slaying gnomes. Worst of all, they are removing tufts of glorious gnome hair from the corpses of the fallen. These atrocities must be stopped. We must reciprocate!\n\nI want them de-hoofed, {class}. Bring me their hooves! Show yourself as an ally of the gnomes.", objectives = "You have been tasked with slaying opposing tauren players in Alterac Valley.\n\nKill a tauren and return to Dirk Swindle at Dun'Baldar with a  Tauren Hoof." }
WordHunterWoW_QuestEN[7365] = { title = "Staghelm's Requiem", description = "Staghelm has given the order. All trolls on the field of battle must be exterminated. Their preposterous claims of birthing night elves must be met with force and due prejudice.\n\nSlay them and return to me with their mojo. To reiterate: I want you to steal their mojo.", objectives = "You have been tasked with slaying opposing troll players in Alterac Valley.\n\nKill a troll and return to Athramanis at Dun'Baldar with Darkspear Troll Mojo." }
WordHunterWoW_QuestEN[7366] = { title = "The Archbishop's Mercy", description = "The Archbishop is as kind as he is wise. For a man to look mercifully on such a wretched lot...\n\n<Commander Philips shakes his head in disbelief.>\n\nToo kind... Just too kind.\n\nThe Archbishop asks that we take pity on the undead and grant them swift and permanent deaths. For this grand display of mercy, we merely require their black, disease ridden hearts.\n\nBring me the hearts of the Forsaken so that they may be ceremoniously incinerated at the Cathedral of Light. Make haste, {name}!", objectives = "You have been tasked with slaying opposing Forsaken players in Alterac Valley.\n\nKill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart." }
WordHunterWoW_QuestEN[7367] = { title = "Defusing the Threat", description = "The Frostwolf have their front lines and bases booby trapped, {class}. You have to watch your step when invading enemy territory.\n\nIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.\n\nYou will probably find him in a tower near the Iceblood Garrison. Good luck!", objectives = "Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete." }
WordHunterWoW_QuestEN[7368] = { title = "Defusing the Threat", description = "I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.\n\nIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.\n\nIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.", objectives = "Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete." }
WordHunterWoW_QuestEN[7381] = { title = "The Return of Korrak", description = "While it is true that Korrak has been slain, one question remains: Will he remain dead? Trolls are notorious for their other-worldly tribal magics. I would not be surprised if the fallen leader was raised from the dead to once more rule over his clan.\n\nYou know what to do should this ever occur.\n\n<Warmaster Laggrond makes a cutting motion across his neck with his index finger.>\n\nAnd  this time, I want his skull. Just keep your eyes peeled, soldier.\n\nDismissed!You will receive:", objectives = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\n\nReturn the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills." }
WordHunterWoW_QuestEN[7382] = { title = "Korrak the Everliving", description = "There's something not quite right about all of this... Did anybody think to burn Korrak's corpse? Those trolls will stop at nothing to revive their fallen leader - as blue skinned pagan man-beasts often do.\n\nJust keep your eyes out, <name>. Don't be alarmed if Korrak makes a surprise appearance; and if he does, I want him executed - his corpse burned to ashes.\n\nFor good measure, lop off his head and bring me his skull before you ignite the lifeless mass.You will receive:", objectives = "Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\n\nReturn the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills." }
WordHunterWoW_QuestEN[7383] = { title = "Teldrassil: The Burden of the Kaldorei", description = "You must now visit the moonwell that rests under the boughs of the Oracle Tree, far to the northwest. The first and most powerful of our wells, its waters are said to possess the very essence of Elune's Powers.\n\nRetrieve a phial of its water and return to me. I will meet you at the crossroads in front of Darnassus when your task is complete.", objectives = "Fill the Amethyst Phial.", progress = "To be in the presence of the Oracle Tree... it is almost to feel wisdom take form.", completion = "Along with the druids, the Oracle Tree has been carefully monitoring the growth of Teldrassil. Our observations have been disheartening, but all is not without hope.\n\nThe tree is indeed recovering since it's blessing, but the growth is still somehow stunted... hindered.\n\nWe suspect some portion of the corruption remains within the tree, waiting to be cleansed. We simply need to find it." }
WordHunterWoW_QuestEN[7385] = { title = "A Gallon of Blood", description = "", objectives = "You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, <name>.", progress = "You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, <name>.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!" }
WordHunterWoW_QuestEN[7386] = { title = "Crystal Cluster", description = "", objectives = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, <name>.", progress = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, <name>.", completion = "Well done, <name>. I will use the power of these charms to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause." }
WordHunterWoW_QuestEN[7401] = { title = "WANTED: Dwarves!", description = "By order of Sergeant Yazra Bloodsnarl, all dwarves on the field of battle are to be killed on sight.\n\nShould you slay a dwarf in combat, rip out their spine, leaving a spineless heap of stink and rot to serve as a warning to any and all that dare oppose the might of the Frostwolf.\n\nReturn to Sergeant Yazra Bloodsnarl with proof of your heroics.", objectives = "You have been tasked with slaying opposing Dwarf players in Alterac Valley.\n\nKill a Dwarf and rip out their spine. Take the Dwarf Spine to Sergeant Yazra Bloodsnarl at Frostwolf Keep." }
WordHunterWoW_QuestEN[7402] = { title = "WANTED: Orcs!", description = "By order of Corporal Noreg Stormpike, all able bodied soldiers of Stormpike are required to slay any opposing orcs that they meet upon the field of battle.\n\nSoldiers are required to remove a tusk or tooth from the maw of the enemy and present said tooth as proof of their accomplishment.\n\nWear protective gloves.", objectives = "You have been tasked with slaying opposing Orc players in Alterac Valley.\n\nKill an Orc and take their Orc Tooth back to Corporal Noreg Stormpike at Dun Baldar." }
WordHunterWoW_QuestEN[7421] = { title = "Darkspear Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[7422] = { title = "Tuft it Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[7423] = { title = "I've Got A Fever For More Bone Chips", description = "", objectives = "" }
WordHunterWoW_QuestEN[7424] = { title = "What the Hoof?", description = "", objectives = "" }
WordHunterWoW_QuestEN[7425] = { title = "Staghelm's Mojo Jamboree", description = "", objectives = "" }
WordHunterWoW_QuestEN[7426] = { title = "One Man's Love", description = "", objectives = "" }
WordHunterWoW_QuestEN[7427] = { title = "Wanted: MORE DWARVES!", description = "", objectives = "" }
WordHunterWoW_QuestEN[7428] = { title = "Wanted: MORE ORCS!", description = "", objectives = "" }
WordHunterWoW_QuestEN[7429] = { title = "Free Knot!", description = "", objectives = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", completion = "Oh, thank you for freeing me!  You - ranked number one.  Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
WordHunterWoW_QuestEN[7441] = { title = "Pusillin and the Elder Azj'Tordin", description = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", objectives = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", progress = "I regret nothing, stranger. The Queen has long since passed. The works of the Shen'Dralar have been marred by the madness of Prince Tortheldrin. I seek only freedom... Escape...", completion = "You have found it! A curse upon that miserable imp. Alas, my material possessions are meager at best. You may choose from what I have to offer." }
WordHunterWoW_QuestEN[7461] = { title = "The Madness Within", description = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", completion = "We thank you, hero." }
WordHunterWoW_QuestEN[7462] = { title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[7463] = { title = "Arcane Refreshment", description = "A <race> mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.Upon completion of this quest you will gain:", objectives = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence." }
WordHunterWoW_QuestEN[7481] = { title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?" }
WordHunterWoW_QuestEN[7482] = { title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?" }
WordHunterWoW_QuestEN[7483] = { title = "Libram of Rapidity", description = "Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>", objectives = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", progress = "What is it? I have much cataloguing to do!", completion = "<Lydros yawns.>\n\nAs promised, the Arcanum of Rapidity. Don't spend it all in once place.\n\n<Lydros snickers.>" }
WordHunterWoW_QuestEN[7484] = { title = "Libram of Focus", description = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.", objectives = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", progress = "You again? What could you possibly want now?", completion = "Don't hurt yourself when applying the enchantment, <race>." }
WordHunterWoW_QuestEN[7485] = { title = "Libram of Protection", description = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north wing.", objectives = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", progress = "My patience prevents your suffering.", completion = "Yes, yes... Calm yourself. As promised, here is your Arcanum." }
WordHunterWoW_QuestEN[7486] = { title = "A Hero's Reward", description = "<name>, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, <name>.  Claim your reward.", objectives = "Claim your reward from Hydraxis' Coffer.<name>, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer. In it you will find your... reward.\n\nGo, <name>. Claim your reward.", completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, <name>.  May it protect you against the foes of the Waterlords.\"" }
WordHunterWoW_QuestEN[7487] = { title = "Attunement to the Core", description = "Rifts stir, tear, and collapse all around us, <race>. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.Upon completion of this quest you will gain:", objectives = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment." }
WordHunterWoW_QuestEN[7488] = { title = "Lethtendris's Web", description = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, <name>.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...", objectives = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", progress = "Do you have the web, <name>?  Its concentrated magical energy must be dissipated!", completion = "You retrieved the web!  Well done, <name>!  Lethtendris, like many elves of her ilk, are blind to the dangers the abuse of magic can cause to our world.  They believe they are masters of magic; they do not realize that they are slaves to their own addiction.  Her death saddens me, but it was necessary.\n\nThank you, <name>.  I will have the energies within the web released safely over a wide area, and then I'll destroy it to prevent future magical exploits." }
WordHunterWoW_QuestEN[7489] = { title = "Lethtendris's Web", description = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", objectives = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", progress = "<name>, do you have Lethtendris's Web?", completion = "You have done well, <name>.  This web holds within it vast stores of the magic of Dire Maul, and I fear what damage may be unleashed if those energies were harnessed by one so irresponsible as Lethtendris.  I am saddened by her death, but I know that she could never part with her web while alive.\n\nThank you, <name>.  I will send the web to students of magic more responsible than Lethtendris.  They will be the new wardens of its power." }
WordHunterWoW_QuestEN[7490] = { title = "Victory for the Horde", description = "You have accomplished the impossible.\n\nThe brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Warchief's advisor Eitrigg.", objectives = "Take the Head of Onyxia to Eitrigg in Orgrimmar.", progress = "<Garrosh's stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>", completion = "This is a great victory for the Horde, <name>. So many times you have honored your Warchief. It is time for the Warchief to honor you." }
WordHunterWoW_QuestEN[7491] = { title = "For All To See", description = "Overlord Natoj awaits your arrival in the Valley of Strength.\n\n<Eitrigg salutes you.>\n\nDo not keep the Horde waiting!", objectives = "Seek out Overlord Natoj in the Valley of Strength.", completion = "Choose your reward and let the celebration of your glorious victory begin." }
WordHunterWoW_QuestEN[7492] = { title = "Camp Mojache", description = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, <name>.  Go to Camp Mojache in Feralas and speak with Talo.", objectives = "Speak with Talo Thornhoof at Camp Mojache in Feralas.", completion = "Ah, it is good to see a <class> heed my summons.  I have need of your services, <name>, and fear they will take you down a dangerous path...\n\nA path into Dire Maul." }
WordHunterWoW_QuestEN[7493] = { title = "The Journey Has Just Begun", description = "", objectives = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian." }
WordHunterWoW_QuestEN[7494] = { title = "Feathermoon Stronghold", description = "<name>!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.", objectives = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", completion = "Hail, <name>.  I am pleased to see you, but regret that our meeting is not under more pleasant conditions.\n\nListen close, for I have a vital task for you..." }
WordHunterWoW_QuestEN[7495] = { title = "Victory for the Alliance", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Grand Admiral in honor of the King.", objectives = "Take the Head of Onyxia to Grand Admiral Jes-Tereth in Stormwind.", progress = "By Uther's beard!", completion = "Today, we celebrate this glorious victory!" }
WordHunterWoW_QuestEN[7496] = { title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", objectives = "Seek out Major Mattingly in the Valley of Heroes.", completion = "Few are graced with such ceremony, <name>. Please, choose your reward so that we may begin the celebration." }
WordHunterWoW_QuestEN[7497] = { title = "The Journey Has Just Begun", description = "", objectives = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian." }
WordHunterWoW_QuestEN[7498] = { title = "Garona: A Study on Stealth and Treachery", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners.", progress = "You have recovered a tome!", completion = "Excellent work, <race>. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes." }
