WordHunterWoW_QuestEN[7507] = { title = "Foror's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return Foror's Compendium of Dragon Slaying to the Athenaeum." }
WordHunterWoW_QuestEN[7508] = { title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", objectives = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros." }
WordHunterWoW_QuestEN[7509] = { title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.You will receive:", objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours." }
WordHunterWoW_QuestEN[7521] = { title = "Thunderaan the Windseeker", description = "I have told you all that I know, <name>. It is you who must find elementium. It is you who must destroy the Firelord's corporeal form.\n\nDo this and gain the blessing of Thunderaan.You will receive:", objectives = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Wind Seeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian." }
